INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C1','kor',3,2,'u6',2,'이 단원에서 배울 두 가지 — 재미나 감동을 느끼며 작품 감상하기(받아들이는 일)와 의견을 제시하는 글 쓰기(내 생각과 이유를 내놓는 일)',ARRAY['[4국05-05][4국03-03]']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C2','kor',3,2,'u6',2,'작품을 감상한다는 것 — 줄거리를 외우거나 점수를 매기는 일이 아니라, 마음이 움직인 자리를 찾고 어디를 보고 그랬는지 말하는 일',ARRAY['[4국05-05]']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C3','kor',3,2,'u6',2,'재미와 감동 — 재미는 웃음이 나거나 다음이 궁금하거나 놀라운 곳, 감동은 마음이 뭉클하거나 오래 남거나 내 일처럼 느껴지는 곳 — 한 작품 안에 둘 다 있을 수 있음',ARRAY['[4국05-05]']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C4','kor',3,2,'u6',2,'같은 작품을 다르게 느낌 — 같은 작품을 보고 다르게 느껴도 둘 다 제 감상이며, 어디를 보고 그렇게 느꼈는지 말하면 됨(하나가 틀린 것도, 아무렇게나 말해도 되는 것도 아님)',ARRAY['[4국05-05]']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C5','kor',3,2,'u6',2,'사람마다 느낀 곳이 다른 까닭 — 저마다 겪은 일과 처지가 달라 마음이 걸리는 자리가 다름',ARRAY['[4국05-05]']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C6','kor',3,2,'u6',2,'감상을 말하는 틀 — 어느 장면에서 + 어떤 마음이 들었는지를 이어 말함(줄거리만 옮기기·느낌만 던지기는 모자람)',ARRAY['[4국05-05]']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C7','kor',3,2,'u6',2,'느낌과 근거 잇기 — 느낀 것 옆에는 늘 무엇을 보고 그랬는지(작품 안의 근거)가 붙음',ARRAY['[4국05-05]']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C8','kor',3,2,'u6',3,'말없이 마음을 아는 법 — 말이 없어도 얼굴 표정·몸짓과 행동·말투와 목소리로 인물의 마음을 알 수 있음',ARRAY['[4국05-05]']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C9','kor',3,2,'u6',3,'행동으로 마음 짐작하기 — 말로 적지 않은 마음이 행동에 남아 있음 — 그 앞에 있었던 일과 이어 짐작함(「손에 힘이 들어갔다」 → 서운함)',ARRAY['[4국05-05]']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C11','kor',3,2,'u6',3,'감상하는 방법이 여럿 — 표정과 말투에 주의하며 보기 · 장면을 눈앞에 그리며 상상하기 · 인물의 일을 내 일과 이어 보기',ARRAY['[4국05-05]']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C12','kor',3,2,'u6',3,'한 작품에 느낄 자리가 여럿 — 한 이야기 안에 재미를 느끼는 곳도 감동을 느끼는 곳도 여럿 있음 — 단, 작품 안에 실제로 있는 곳',ARRAY['[4국05-05]']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C13','kor',3,2,'u6',3,'감상을 나누면 좋은 점 — 같은 곳을 느꼈는지 맞춰 보거나 확인받으려는 것이 아니라, 내가 못 보고 지나친 자리를 알게 되어 작품이 넓어짐',ARRAY['[4국05-05]']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C14','kor',3,2,'u6',5,'소중히 여기는 것은 말과 행동에서 — 인물이 무엇을 소중히 여기는지는 이야기에 적혀 있지 않고, 인물이 한 말과 행동을 보고 읽어 냄',ARRAY['[4국05-05]']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C16','kor',3,2,'u6',5,'부딪친 두 사람 둘 다 소중한 것 — 부딪친 두 인물은 한쪽이 잘못한 것이 아니라 둘 다 소중히 여기는 것이 있어 물러설 수 없었음 — 「누가 옳은가」는 한쪽을 고를 물음이 아님',ARRAY['[4국05-05]']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C17','kor',3,2,'u6',5,'인물에게 물어볼 질문 — 그때의 마음·그렇게 한 까닭·지금이라면 어떻게 할지처럼 인물이 답할 수 있는 질문(답이 이야기 밖에 있는 질문은 알맞지 않음)',ARRAY['[4국05-05]']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C18','kor',3,2,'u6',5,'내 일과 이어 보기 — 친구와 부딪친 일을 떠올릴 때 누가 잘못했는지보다 서로 무엇을 소중히 여겼는지를 먼저 봄(덮어 두기도 아님)',ARRAY['[4국05-05]']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C19','kor',3,2,'u6',7,'의견이란 — 어떤 일이나 대상에 대한 생각 — 있었던 일(사실)과 다르며 “좋겠다·하자·해야 한다”가 붙음',ARRAY['[4국03-03]']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C20','kor',3,2,'u6',7,'의견을 제시하는 글의 세 부분 — 문제 상황(무엇이 불편한지) · 내 의견(어떻게 하면 좋을지) · 그렇게 생각한 이유(왜 그런지) — 의견만 있으면 글이 서지 않음',ARRAY['[4국03-03]']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C21','kor',3,2,'u6',7,'글에서 의견과 이유 찾기 — “그래서 …면 좋겠다”는 의견, “왜냐하면·첫째·둘째·또”로 시작하는 줄은 이유',ARRAY['[4국03-03]']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C22','kor',3,2,'u6',7,'적절한 이유 — 이유는 의견과 이어져 의견을 받쳐 주어야 함(의견과 관련 없는 이유는 받침이 되지 못함)',ARRAY['[4국03-03]']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C23','kor',3,2,'u6',7,'의견과 이유를 재는 네 가지 — 문제 상황에 어울리는 의견인가 · 의견을 뒷받침하는 이유인가 · 이유가 겹치지 않고 여러 가지인가 · 문제를 푸는 데 도움이 되는가 — 「나만 잘한다」는 받침이 아님',ARRAY['[4국03-03]']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C24','kor',3,2,'u6',7,'한 문제에 여러 의견 — 같은 문제 상황에도 의견이 여럿 나올 수 있으며, 가르는 것은 어느 의견인가가 아니라 이유가 의견을 받쳐 주는가임',ARRAY['[4국03-03]']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C25','kor',3,2,'u6',7,'의견 글을 쓸 때 먼저 할 일 — 고운 말·친구가 좋아할 말보다 무엇이 불편한지(문제 상황)를 먼저 찾음',ARRAY['[4국03-03]']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C26','kor',3,2,'u6',9,'고쳐 쓸 때 살펴볼 것 — 어울리는 의견인가 · 이유가 받쳐 주는가 · 어색한 곳은 없는가 · 띄어쓰기와 맞춤법(글의 길이·글씨 모양이 아님)',ARRAY['[4국03-03][4국03-01]']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C27','kor',3,2,'u6',9,'이어지지 않는 이유 고치기 — 의견과 이어지지 않는 이유를 찾아, 지우기만 하지 않고 의견을 받쳐 주는 다른 이유로 바꿈',ARRAY['[4국03-03][4국03-01]']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C28','kor',3,2,'u6',9,'고칠 곳이 있는 글은 못 쓴 글이 아님 — 고칠 곳이 보인 것은 글을 다시 읽었다는 뜻이고, 글은 고쳐 가며 좋아짐 — 고쳐 쓰면 내 생각이 더 잘 전해짐',ARRAY['[4국03-03][4국03-01]']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C29','kor',3,2,'u6',9,'친구 글에 말해 주기 — 잘된 곳을 먼저 한 가지 말하고, 고칠 곳은 어디인지 짚어 까닭과 함께 말함(점수를 매기는 자리가 아님)',ARRAY['[4국03-03][4국03-01]']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C30','kor',3,2,'u6',10,'다룰 문제 고르기 — 우리가 함께 바꿀 수 있는 일을 고름 — 어쩔 수 없는 일·누군가를 탓하는 일은 의견 글의 문제가 아님',ARRAY['[4국03-03]']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C31','kor',3,2,'u6',10,'읽을 사람 정하기 — 쓰기 전에 누가 읽을지와 어디에 쓸지를 정하면 쓸 말이 정해짐(읽을 사람이 아는 일은 짧게, 함께 할 일은 자세히)',ARRAY['[4국03-03]']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C32','kor',3,2,'u6',10,'이유 떠올리기 — 내 의견대로 하면 무엇이 좋아질지를 먼저 적어 보면 이유가 보임',ARRAY['[4국03-03]']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C33','kor',3,2,'u6',10,'글의 뼈대 — 문제 상황 → 의견 → 이유 두 가지 → 맺음(함께 해 보자는 말)',ARRAY['[4국03-03]']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C34','kor',3,2,'u6',10,'점검표로 내 글 재기 — 문제를 풀 수 있는 의견인가 · 받쳐 주는 이유인가 · 어색한 곳 · 띄어쓰기와 맞춤법으로 재어 고쳐 씀(틀린 곳 찾기·점수 깎기가 아님)',ARRAY['[4국03-03][4국03-01]']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C35','kor',3,2,'u6',12,'의견을 제시하는 손 팻말 — 팻말에도 의견과 이유가 함께 — 의견만 크게 쓰면 명령이 되고, 이유만 길면 무엇을 하자는지 안 보임',ARRAY['[4국05-05][4국03-03]']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C36','kor',3,2,'u6',12,'「만약 이랬더라면?」 — 작품을 고치는 놀이가 아니라 마음이 움직인 장면의 말이나 행동을 바꾸어 보며 왜 그랬는지 다시 보는 놀이',ARRAY['[4국05-05][4국03-03]']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C37','kor',3,2,'u6',12,'한 줄 평 — 느낀 곳과 마음을 한 줄에 함께 담음(점수만·줄거리만으로는 친구가 따라올 수 없음)',ARRAY['[4국05-05][4국03-03]']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C38','kor',3,2,'u6',12,'-ㄹ게 · -ㄹ걸은 그대로 쓰기 — “갈게”가 [갈께]로 소리 나도 약속하는 말·되돌아보는 말은 글자 그대로 씀(기초 다지기)',ARRAY['[4국05-05][4국03-03]']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C39','kor',3,2,'u6',12,'묻는 말 -ㄹ까는 소리 나는 대로 — “먹을까?·갈까?”처럼 묻는 말은 소리 나는 대로 씀(‘-ㄹ가’ 아님, 기초 다지기)',ARRAY['[4국05-05][4국03-03]']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C40','kor',3,2,'u6',12,'낱말 잇기 — 앞 낱말의 끝 글자로 시작하는 낱말을 찾아 줄줄이 이음(기초 다지기)',ARRAY['[4국05-05][4국03-03]']::text[],40) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C41','kor',3,2,'u6',12,'ㅝ · ㅞ · ㅟ가 든 글자 쓰기 — ㅝ(ㅜ+ㅓ) · ㅞ(ㅜ+ㅔ) · ㅟ(ㅜ+ㅣ)를 살피며 씀(원숭이 · 웬일 · 스웨터 · 바퀴, 기초 다지기)',ARRAY['[4국05-05][4국03-03]']::text[],41) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C42','kor',3,2,'u6',3,'「건전지 엄마」 내용 알기 — 낮잠 시간 → 타는 냄새 → 위험을 무릅쓰고 나섬 → 있는 힘껏 비상벨 → 아이들 대피·집에서 행복하게 잠듦(대사 없는 만화 영화)',ARRAY['[4국05-05]']::text[],42) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C43','kor',3,2,'u6',5,'「신통방통 니 맘 내 맘 계산기」 내용 알기 — 신비가 자기 마음만 기준으로 친구들을 오해했다가 용용이가 준 계산기로 마리·기동·아빠의 진심을 깨닫고 반성함(드라마 · 낱말 신통방통하다·밑창·단짝)',ARRAY['[4국05-05]']::text[],43) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X01','kor',3,'u6',ARRAY['K3-2-u6-C2']::text[],'감상을 줄거리를 빠짐없이 외우는 일로 여긴다','마음이 움직인 자리는?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X02','kor',3,'u6',ARRAY['K3-2-u6-C2','K3-2-u6-C37']::text[],'감상을 작품에 점수를 매기거나 좋고 나쁨을 가리는 일로 여긴다','점수로는 마음이 안 보여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X03','kor',3,'u6',ARRAY['K3-2-u6-C4']::text[],'같은 작품을 보고 다르게 느끼면 둘 가운데 하나는 틀린 감상이라고 여긴다','어디를 보고 그랬는지 들어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X04','kor',3,'u6',ARRAY['K3-2-u6-C4','K3-2-u6-C7','K3-2-u6-C12']::text[],'감상은 근거 없이 아무렇게나 말해도 된다고 여겨, 작품에 없는 장면이나 작품 밖의 일을 든다','작품 안에서 무엇을 보았나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X05','kor',3,'u6',ARRAY['K3-2-u6-C5']::text[],'사람마다 느낀 곳이 다른 까닭을 한 사람만 제대로 읽었기 때문이라고 여긴다','겪은 일과 처지가 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X06','kor',3,'u6',ARRAY['K3-2-u6-C6','K3-2-u6-C37']::text[],'줄거리만 옮겨 말하고 감상을 말했다고 여긴다','그 장면에서 어떤 마음이었나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X07','kor',3,'u6',ARRAY['K3-2-u6-C6']::text[],'“그냥 좋았어”처럼 느낌만 던지고 어디에서 그랬는지는 말하지 않는다','어느 장면에서?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X08','kor',3,'u6',ARRAY['K3-2-u6-C3']::text[],'재미와 감동을 엇갈리게 알거나, 한 작품에는 둘 가운데 하나만 있다고 여긴다','웃음 · 뭉클함') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X09','kor',3,'u6',ARRAY['K3-2-u6-C8']::text[],'말없이 마음을 알 때 키·날씨·옷처럼 마음과 상관없는 것을 본다','얼굴 · 몸짓 · 말투') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X10','kor',3,'u6',ARRAY['K3-2-u6-C8','K3-2-u6-C9']::text[],'행동을 겉뜻으로만 읽거나 앞에 있었던 일과 잇지 않아 인물의 마음을 잘못 짐작한다','그 앞줄에 무슨 일이?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X11','kor',3,'u6',ARRAY['K3-2-u6-C10','K3-2-u6-C15']::text[],'이야기에 나온 일의 차례나 내용을 이야기에 없는 것으로 잘못 읽는다','그 줄을 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X12','kor',3,'u6',ARRAY['K3-2-u6-C11']::text[],'작품을 감상하는 방법은 하나뿐이라고 여기거나 방법을 엇갈리게 안다','표정 · 상상 · 내 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X13','kor',3,'u6',ARRAY['K3-2-u6-C12']::text[],'작품마다 정해진 감동 지점이 하나 있어 그 밖의 곳을 고르면 잘못 감상한 것이라고 여긴다','느낄 자리는 여럿') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X14','kor',3,'u6',ARRAY['K3-2-u6-C13']::text[],'감상을 나누는 까닭을 같은 곳을 느꼈는지 맞춰 보거나 내 감상이 맞는지 확인받는 것으로 여긴다','내가 못 본 자리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X15','kor',3,'u6',ARRAY['K3-2-u6-C14']::text[],'인물이 소중히 여기는 것이 이야기에 적혀 있다고 여기거나, 말과 행동을 살피지 않고 짐작한다','한 말과 한 행동') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X16','kor',3,'u6',ARRAY['K3-2-u6-C16','K3-2-u6-C18']::text[],'두 인물이 부딪치면 한쪽이 옳고 한쪽이 잘못한 것이라고 여겨 누가 옳은지 고르려 한다','둘 다 소중한 것이 있었나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X17','kor',3,'u6',ARRAY['K3-2-u6-C17']::text[],'인물에게 답이 이야기 밖에 있는 질문(가게·학교 이름·쓴 사람)을 한다','인물이 답할 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X18','kor',3,'u6',ARRAY['K3-2-u6-C18']::text[],'친구와 부딪친 일은 덮어 두고 말하지 않는 것이 좋다고 여긴다','무엇을 소중히 여겼는지 말해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X19','kor',3,'u6',ARRAY['K3-2-u6-C19']::text[],'있었던 일(사실)과 내 생각(의견)을 가르지 못한다','“좋겠다 · 하자”가 붙었나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X20','kor',3,'u6',ARRAY['K3-2-u6-C20']::text[],'의견을 제시하는 글에 의견만 있으면 되고 이유는 없어도 된다고 여긴다','읽는 사람이 “왜?”') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X21','kor',3,'u6',ARRAY['K3-2-u6-C20','K3-2-u6-C21','K3-2-u6-C33']::text[],'문제 상황·의견·이유(·맺음)를 엇갈리게 가른다','불편 · 하자 · 왜냐하면') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X22','kor',3,'u6',ARRAY['K3-2-u6-C22','K3-2-u6-C27','K3-2-u6-C34']::text[],'의견과 관련 없는 이유도 의견을 받쳐 준다고 여긴다','그 이유가 의견과 이어지나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X23','kor',3,'u6',ARRAY['K3-2-u6-C22','K3-2-u6-C23','K3-2-u6-C27']::text[],'「내가 제일 잘하기 때문이다」처럼 나만 잘한다는 것을 이유로 든다','의견대로 하면 무엇이 좋아지나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X24','kor',3,'u6',ARRAY['K3-2-u6-C24']::text[],'한 문제에는 정답 의견이 하나뿐이라 나와 다르거나 나중에 나온 의견은 틀렸다고 여긴다','이유가 받쳐 주는지로 재기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X25','kor',3,'u6',ARRAY['K3-2-u6-C23','K3-2-u6-C27']::text[],'같은 이유를 말만 바꾸어 되풀이하고 이유를 여러 가지 썼다고 여긴다','겹치지 않게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X26','kor',3,'u6',ARRAY['K3-2-u6-C25']::text[],'의견 글을 쓸 때 문제 상황보다 고운 말·긴 글·친구가 좋아할 말을 먼저 생각한다','무엇이 불편한지부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X27','kor',3,'u6',ARRAY['K3-2-u6-C26','K3-2-u6-C34']::text[],'고쳐 쓸 때 글의 길이·글씨 모양처럼 내용과 상관없는 것을 보거나, 한 가지만 본다','뜻이 통하나 · 맞춤법은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X28','kor',3,'u6',ARRAY['K3-2-u6-C27']::text[],'의견과 이어지지 않는 이유를 지우기만 하거나 그대로 둔다','받쳐 주는 이유로 바꾸기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X29','kor',3,'u6',ARRAY['K3-2-u6-C28','K3-2-u6-C34']::text[],'고칠 곳이 있는 글은 못 쓴 글이고 잘 쓴 글은 처음부터 고칠 곳이 없다고 여긴다','다시 읽었다는 뜻') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X30','kor',3,'u6',ARRAY['K3-2-u6-C28','K3-2-u6-C29']::text[],'고쳐 쓰기나 친구 글 읽기를 흠을 찾아 알려 주는 일로 여겨, 잘된 곳과 까닭 없이 고칠 곳만 말한다','잘된 곳 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X31','kor',3,'u6',ARRAY['K3-2-u6-C30']::text[],'날씨나 지난 일처럼 우리가 어쩔 수 없는 일을 의견 글의 문제로 고른다','우리 힘으로 바꿀 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X32','kor',3,'u6',ARRAY['K3-2-u6-C30','K3-2-u6-C35']::text[],'누군가를 탓하는 일(친구 이름 적기)을 의견 글이나 팻말의 문제로 삼는다','함께 바꿀 일인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X33','kor',3,'u6',ARRAY['K3-2-u6-C31']::text[],'읽을 사람을 생각하지 않고 누가 읽든 글을 똑같이 쓴다','누가 읽을까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X34','kor',3,'u6',ARRAY['K3-2-u6-C35']::text[],'팻말에 “하지 마!”처럼 의견(명령)만 크게 쓰면 된다고 여긴다','이유도 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X35','kor',3,'u6',ARRAY['K3-2-u6-C35']::text[],'팻말에 이유만 길게 늘어놓아 무엇을 하자는지 보이지 않게 쓴다','의견을 한눈에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X36','kor',3,'u6',ARRAY['K3-2-u6-C36']::text[],'「만약 이랬더라면?」에서 제목·길이처럼 마음이 움직인 장면과 상관없는 것을 바꾼다','마음이 움직인 장면') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X37','kor',3,'u6',ARRAY['K3-2-u6-C37']::text[],'한 줄 평을 점수나 별 개수만으로 쓴다','느낀 곳과 마음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X38','kor',3,'u6',ARRAY['K3-2-u6-C38']::text[],'약속하는 말·되돌아보는 말을 소리 나는 대로 쓴다(갈께·일어날껄)','쓸 때는 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X39','kor',3,'u6',ARRAY['K3-2-u6-C39']::text[],'묻는 말을 ‘-ㄹ가’로 쓰거나 약속하는 말과 섞는다(먹을가)','묻는 말은 소리 나는 대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X40','kor',3,'u6',ARRAY['K3-2-u6-C40']::text[],'낱말 잇기에서 앞 낱말의 끝 글자가 아닌 다른 글자로 잇는다','끝 글자로 시작') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X41','kor',3,'u6',ARRAY['K3-2-u6-C41']::text[],'ㅝ·ㅞ·ㅟ를 이루는 모음자를 엇갈리게 알아 글자를 틀리게 쓴다','ㅜ 옆에 무엇이 붙었나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X42','kor',3,'u6',ARRAY['K3-2-u6-C11','K3-2-u6-C12']::text[],'만화 영화나 드라마를 감상할 때 인물만 보고, 배경 음악·효과음 같은 소리는 재미나 감동과 상관없다고 여긴다','음악이 멈추거나 바뀐 곳에서 어떤 느낌이 들었나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X43','kor',3,'u6',ARRAY['K3-2-u6-C23','K3-2-u6-C30','K3-2-u6-C35']::text[],'의견을 「……하지 말자」처럼 하지 말라는 말로만 내고, 문제를 풀 방법(무엇을 하자)은 내지 않는다','그럼 무엇을 하면 문제가 풀릴까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X44','kor',3,'u6',ARRAY['K3-2-u6-C23','K3-2-u6-C26']::text[],'문제 상황과 어울리지 않는 의견을 내고도(체력을 기르자며 보드게임을 하자) 이유만 그럴듯하면 된다고 여긴다','그 의견대로 하면 처음 문제가 풀리나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X45','kor',3,'u6',ARRAY['K3-2-u6-C27','K3-2-u6-C34']::text[],'고쳐 쓰기는 다 쓴 뒤 점검표를 보고 한 번만 하는 일이며, 고칠 때 이유를 더하거나 쓴 내용을 빼면 안 된다고 여긴다','쓰는 동안에도 고칠 수 있나? 더하고 빼도 되나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X46','kor',3,'u6',ARRAY['K3-2-u6-C14','K3-2-u6-C16','K3-2-u6-C18']::text[],'내 마음만 기준으로 다른 사람의 말과 행동을 짐작해, 상대의 처지에서 생각해 보지 않고 오해한다','그 사람 자리에 서 보면 어떻게 보일까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X47','kor',3,'u6',ARRAY['K3-2-u6-C1','K3-2-u6-C19']::text[],'작품을 보고 느낀 재미나 감동을 표현하는 글과, 문제 상황에 대한 의견과 이유를 제시하는 글을 가르지 못한다','느낀 것을 쓰는 글? 무엇을 하자고 하는 글?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L02_basic#1','kor',3,2,'u6','L02','tb_g3_2_kor_u6_L02_basic','lesson_basic','K3-2-u6-C1',1,'mc','auto','「윤솔이와 지수의 대화」를 들었어요. 윤솔이가 쓰려고 하는 글은 무엇인가요?',ARRAY['K3-2-u6-X47','K3-2-u6-X01','K3-2-u6-X02']::text[],false,'{"seq":1,"concept":"K3-2-u6-C1","difficulty":1,"kind":"mc","stem":"「윤솔이와 지수의 대화」를 들었어요. 윤솔이가 쓰려고 하는 글은 무엇인가요?","options":[{"t":"한글 사용에 대한 자신의 의견을 제시하는 글","correct":true},{"t":"영화를 보고 느낀 재미나 감동만 쓴 글","mis":"K3-2-u6-X47"},{"t":"영화의 줄거리를 처음부터 끝까지 옮긴 글","mis":"K3-2-u6-X01"},{"t":"영화에 점수를 매겨 알리는 글","mis":"K3-2-u6-X02"}],"explanation":["지수가 “느낀 재미나 감동을 글로 쓰는 거야?” 하고 묻자 윤솔이는 “아니.”라고 했어요.","윤솔이는 한글 사용에 대한 자기 의견을 쓰겠다고 했어요.","감상을 표현하는 글과 의견을 제시하는 글은 서로 달라요."],"asset":{"type":"speech","turns":[{"who":"지수","text":"윤솔아, 뭐 해?"},{"who":"윤솔","text":"세종 대왕님께서 만드신 한글과 관련 있는 영화를 봤는데 영화를 보고 나서 쓰고 싶은 게 떠올랐어."},{"who":"지수","text":"영화를 보고 느낀 재미나 감동을 글로 쓰는 거야?"},{"who":"윤솔","text":"아니. 백성을 사랑하는 마음으로 만드신 한글에 감동받은 건 맞지만, 한글 사용에 대한 내 의견을 제시하는 글을 쓸 거야."},{"who":"윤솔","text":"소중한 한글을 바르게 사용하자는 의견이야. 요즘 우리가 사용하는 말에 외국어나 바람직하지 않은 말이 많은 것 같아."},{"who":"지수","text":"좋은 생각이다! 작품을 감상한 뒤에 자신의 의견을 제시하는 글을 쓸 수도 있구나."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L02_basic#2','kor',3,2,'u6','L02','tb_g3_2_kor_u6_L02_basic','lesson_basic','K3-2-u6-C3',1,'mc','auto','윤솔이는 한글과 관련 있는 영화를 보고 어떤 감동을 느꼈나요?',ARRAY['K3-2-u6-X04','K3-2-u6-X11']::text[],false,'{"seq":2,"concept":"K3-2-u6-C3","difficulty":1,"kind":"mc","stem":"윤솔이는 한글과 관련 있는 영화를 보고 어떤 감동을 느꼈나요?","options":[{"t":"세종 대왕님이 백성을 사랑하는 마음에 감동을 느꼈다","correct":true},{"t":"영화가 길어서 감동을 느꼈다","mis":"K3-2-u6-X04"},{"t":"외국어가 많이 나와서 재미를 느꼈다","mis":"K3-2-u6-X11"},{"t":"한글이 어려워서 감동을 느꼈다","mis":"K3-2-u6-X11"}],"explanation":["윤솔이는 “백성을 사랑하는 마음으로 만드신 한글에 감동받은 건 맞지만”이라고 했어요.","감동은 작품 안의 장면이나 인물의 마음에서 와요.","대화에 없는 내용을 고르지 않아요."],"asset":{"type":"speech","turns":[{"who":"지수","text":"윤솔아, 뭐 해?"},{"who":"윤솔","text":"세종 대왕님께서 만드신 한글과 관련 있는 영화를 봤는데 영화를 보고 나서 쓰고 싶은 게 떠올랐어."},{"who":"지수","text":"영화를 보고 느낀 재미나 감동을 글로 쓰는 거야?"},{"who":"윤솔","text":"아니. 백성을 사랑하는 마음으로 만드신 한글에 감동받은 건 맞지만, 한글 사용에 대한 내 의견을 제시하는 글을 쓸 거야."},{"who":"윤솔","text":"소중한 한글을 바르게 사용하자는 의견이야. 요즘 우리가 사용하는 말에 외국어나 바람직하지 않은 말이 많은 것 같아."},{"who":"지수","text":"좋은 생각이다! 작품을 감상한 뒤에 자신의 의견을 제시하는 글을 쓸 수도 있구나."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L02_basic#3','kor',3,2,'u6','L02','tb_g3_2_kor_u6_L02_basic','lesson_basic','K3-2-u6-C1',1,'ox','auto','작품을 감상한 뒤에 그 작품과 관련된 자신의 의견을 제시하는 글을 쓸 수도 있어요.',ARRAY['K3-2-u6-X47']::text[],false,'{"seq":3,"concept":"K3-2-u6-C1","difficulty":1,"kind":"ox","stem":"작품을 감상한 뒤에 그 작품과 관련된 자신의 의견을 제시하는 글을 쓸 수도 있어요.","answer":"O","reason_options":[{"t":"윤솔이도 한글 영화를 보고 한글을 바르게 사용하자는 의견 글을 쓰려고 하기 때문에","correct":true},{"t":"감상한 작품으로는 느낀 재미나 감동을 표현하는 글만 쓸 수 있기 때문에","mis":"K3-2-u6-X47"}],"mis":"K3-2-u6-X47","explanation":["지수도 “작품을 감상한 뒤에 자신의 의견을 제시하는 글을 쓸 수도 있구나.”라고 했어요.","한 작품에서 감상도, 의견도 생길 수 있어요.","그래서 O예요."],"asset":{"type":"speech","turns":[{"who":"지수","text":"윤솔아, 뭐 해?"},{"who":"윤솔","text":"세종 대왕님께서 만드신 한글과 관련 있는 영화를 봤는데 영화를 보고 나서 쓰고 싶은 게 떠올랐어."},{"who":"지수","text":"영화를 보고 느낀 재미나 감동을 글로 쓰는 거야?"},{"who":"윤솔","text":"아니. 백성을 사랑하는 마음으로 만드신 한글에 감동받은 건 맞지만, 한글 사용에 대한 내 의견을 제시하는 글을 쓸 거야."},{"who":"윤솔","text":"소중한 한글을 바르게 사용하자는 의견이야. 요즘 우리가 사용하는 말에 외국어나 바람직하지 않은 말이 많은 것 같아."},{"who":"지수","text":"좋은 생각이다! 작품을 감상한 뒤에 자신의 의견을 제시하는 글을 쓸 수도 있구나."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L02_basic#4','kor',3,2,'u6','L02','tb_g3_2_kor_u6_L02_basic','lesson_basic','K3-2-u6-C4',1,'mc','auto','「레오의 특별한 꿈」을 두고 세 친구가 이야기를 나누었어요. 친구들이 대화를 나누고 깨달은 점은 무엇인가요?',ARRAY['K3-2-u6-X13','K3-2-u6-X03','K3-2-u6-X01']::text[],false,'{"seq":4,"concept":"K3-2-u6-C4","difficulty":1,"kind":"mc","stem":"「레오의 특별한 꿈」을 두고 세 친구가 이야기를 나누었어요. 친구들이 대화를 나누고 깨달은 점은 무엇인가요?","options":[{"t":"같은 작품을 보고도 재미나 감동을 느낀 부분이 다를 수 있다","correct":true},{"t":"감동을 느낀 부분은 모두 같아야 한다","mis":"K3-2-u6-X13"},{"t":"가장 먼저 말한 친구의 감상이 맞다","mis":"K3-2-u6-X03"},{"t":"줄거리를 잘 외운 친구가 감상을 잘한다","mis":"K3-2-u6-X01"}],"explanation":["세 친구는 서로 다른 장면을 말했어요.","안쓰러운 장면, 재미있는 장면, 감동적인 장면이 모두 달랐어요.","마지막에 “같은 작품을 보고도 … 다를 수 있구나.”라고 했어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"1학기 때 교과서에서 읽은 「레오의 특별한 꿈」이 어때?"},{"who":"친구 2","text":"가짜 ‘델’을 달고 있다고 친구들에게 놀림받은 레오가 무척 안쓰러웠어. 나도 친구들에게 놀림받았을 때 속상했거든."},{"who":"친구 3","text":"신비한 능력이 없어도 좋으니까 ‘델’ 모양만이라도 만들어 달라고 마법사에게 조르는 레오의 모습이 조금은 재미있게 느껴졌어. 부모님께 물건을 사 달라고 부탁하는 내 모습 같았거든."},{"who":"친구 1","text":"그랬구나. 나는 레오가 진짜 꿈에 대해 생각하자 진짜 ‘델’이 생긴 장면이 감동적이었어. 나도 꿈을 이루기 위해 열심히 노력해야겠다고 생각했어."},{"who":"친구 2","text":"같은 작품을 보고도 재미나 감동을 느낀 부분이 다를 수 있구나."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L02_basic#5','kor',3,2,'u6','L02','tb_g3_2_kor_u6_L02_basic','lesson_basic','K3-2-u6-C7',2,'blank','auto','친구 3의 감상을 정리했어요. 빈칸에 알맞은 말은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L02_basic#6','kor',3,2,'u6','L02','tb_g3_2_kor_u6_L02_basic','lesson_basic','K3-2-u6-C5',2,'mc','auto','친구 2는 놀림받은 레오가 무척 안쓰러웠다고 했어요. 친구 2가 그렇게 느낀 까닭은 무엇인가요?',ARRAY['K3-2-u6-X01','K3-2-u6-X14','K3-2-u6-X11']::text[],false,'{"seq":6,"concept":"K3-2-u6-C5","difficulty":2,"kind":"mc","stem":"친구 2는 놀림받은 레오가 무척 안쓰러웠다고 했어요. 친구 2가 그렇게 느낀 까닭은 무엇인가요?","options":[{"t":"자신도 친구들에게 놀림받았을 때 무척 속상했던 경험이 있어서","correct":true},{"t":"이야기의 줄거리를 다 외웠기 때문에","mis":"K3-2-u6-X01"},{"t":"친구 1이 그렇게 느끼라고 해서","mis":"K3-2-u6-X14"},{"t":"레오가 마법의 숲에 갔기 때문에","mis":"K3-2-u6-X11"}],"explanation":["친구 2는 “나도 친구들에게 놀림받았을 때 속상했거든.”이라고 했어요.","사람마다 처한 환경이나 겪은 경험이 달라요.","그래서 마음이 움직이는 부분도 달라져요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"1학기 때 교과서에서 읽은 「레오의 특별한 꿈」이 어때?"},{"who":"친구 2","text":"가짜 ‘델’을 달고 있다고 친구들에게 놀림받은 레오가 무척 안쓰러웠어. 나도 친구들에게 놀림받았을 때 속상했거든."},{"who":"친구 3","text":"신비한 능력이 없어도 좋으니까 ‘델’ 모양만이라도 만들어 달라고 마법사에게 조르는 레오의 모습이 조금은 재미있게 느껴졌어. 부모님께 물건을 사 달라고 부탁하는 내 모습 같았거든."},{"who":"친구 1","text":"그랬구나. 나는 레오가 진짜 꿈에 대해 생각하자 진짜 ‘델’이 생긴 장면이 감동적이었어. 나도 꿈을 이루기 위해 열심히 노력해야겠다고 생각했어."},{"who":"친구 2","text":"같은 작품을 보고도 재미나 감동을 느낀 부분이 다를 수 있구나."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L02_basic#7','kor',3,2,'u6','L02','tb_g3_2_kor_u6_L02_basic','lesson_basic','K3-2-u6-C3',2,'mc','auto','「레오의 특별한 꿈」에서 세 친구가 말한 장면을 재미와 감동으로 바르게 나눈 것은 무엇인가요?',ARRAY['K3-2-u6-X08','K3-2-u6-X06']::text[],false,'{"seq":7,"concept":"K3-2-u6-C3","difficulty":2,"kind":"mc","stem":"「레오의 특별한 꿈」에서 세 친구가 말한 장면을 재미와 감동으로 바르게 나눈 것은 무엇인가요?","options":[{"t":"조르는 레오의 모습 — 재미 · 진짜 ‘델’이 생긴 장면 — 감동","correct":true},{"t":"조르는 레오의 모습 — 감동 · 진짜 ‘델’이 생긴 장면 — 재미","mis":"K3-2-u6-X08"},{"t":"두 장면 모두 재미만 있고 감동은 없다","mis":"K3-2-u6-X08"},{"t":"진짜 ‘델’이 생긴 장면은 줄거리일 뿐 재미도 감동도 아니다","mis":"K3-2-u6-X06"}],"explanation":["친구 3은 조르는 모습이 “조금은 재미있게 느껴졌어.”라고 했어요.","친구 1은 진짜 델이 생긴 장면이 “감동적이었어.”라고 했어요.","한 작품 안에 재미와 감동이 함께 있을 수 있어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"1학기 때 교과서에서 읽은 「레오의 특별한 꿈」이 어때?"},{"who":"친구 2","text":"가짜 ‘델’을 달고 있다고 친구들에게 놀림받은 레오가 무척 안쓰러웠어. 나도 친구들에게 놀림받았을 때 속상했거든."},{"who":"친구 3","text":"신비한 능력이 없어도 좋으니까 ‘델’ 모양만이라도 만들어 달라고 마법사에게 조르는 레오의 모습이 조금은 재미있게 느껴졌어. 부모님께 물건을 사 달라고 부탁하는 내 모습 같았거든."},{"who":"친구 1","text":"그랬구나. 나는 레오가 진짜 꿈에 대해 생각하자 진짜 ‘델’이 생긴 장면이 감동적이었어. 나도 꿈을 이루기 위해 열심히 노력해야겠다고 생각했어."},{"who":"친구 2","text":"같은 작품을 보고도 재미나 감동을 느낀 부분이 다를 수 있구나."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L02_basic#8','kor',3,2,'u6','L02','tb_g3_2_kor_u6_L02_basic','lesson_basic','K3-2-u6-C7',2,'match','auto','친구들이 재미나 감동을 느낀 부분과 그 까닭을 바르게 이어 보세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u6-C7","difficulty":2,"kind":"match","stem":"친구들이 재미나 감동을 느낀 부분과 그 까닭을 바르게 이어 보세요.","pairs":[{"l":"놀림받은 레오가 안쓰러웠다.","r":"나도 놀림받았을 때 무척 속상했기 때문이다."},{"l":"조르는 레오가 재미있었다.","r":"물건을 사 달라고 부탁하는 내 모습 같았기 때문이다."},{"l":"진짜 델이 생긴 장면이 감동적이었다.","r":"나도 꿈을 이루려고 노력해야겠다고 생각했기 때문이다."}],"mis":"K3-2-u6-X04","explanation":["느낀 부분마다 그렇게 느낀 까닭이 따로 있어요.","까닭은 그 장면과 자신의 경험·생각을 이어 줘요.","근거 없이 아무렇게나 잇지 않아요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"1학기 때 교과서에서 읽은 「레오의 특별한 꿈」이 어때?"},{"who":"친구 2","text":"가짜 ‘델’을 달고 있다고 친구들에게 놀림받은 레오가 무척 안쓰러웠어. 나도 친구들에게 놀림받았을 때 속상했거든."},{"who":"친구 3","text":"신비한 능력이 없어도 좋으니까 ‘델’ 모양만이라도 만들어 달라고 마법사에게 조르는 레오의 모습이 조금은 재미있게 느껴졌어. 부모님께 물건을 사 달라고 부탁하는 내 모습 같았거든."},{"who":"친구 1","text":"그랬구나. 나는 레오가 진짜 꿈에 대해 생각하자 진짜 ‘델’이 생긴 장면이 감동적이었어. 나도 꿈을 이루기 위해 열심히 노력해야겠다고 생각했어."},{"who":"친구 2","text":"같은 작품을 보고도 재미나 감동을 느낀 부분이 다를 수 있구나."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L02_basic#9','kor',3,2,'u6','L02','tb_g3_2_kor_u6_L02_basic','lesson_basic','K3-2-u6-C2',2,'mc','auto','2차시 시작에 다섯 고개 놀이를 해요. 친구가 재미나 감동을 느낀 작품을 머릿속으로 떠올렸을 때 다른 친구들이 할 일로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X01','K3-2-u6-X02','K3-2-u6-X04']::text[],false,'{"seq":9,"concept":"K3-2-u6-C2","difficulty":2,"kind":"mc","stem":"2차시 시작에 다섯 고개 놀이를 해요. 친구가 재미나 감동을 느낀 작품을 머릿속으로 떠올렸을 때 다른 친구들이 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"“예.”, “아니요.”로 답할 수 있는 질문을 돌아가며 한다","correct":true},{"t":"그 작품의 줄거리를 처음부터 끝까지 말해 달라고 한다","mis":"K3-2-u6-X01"},{"t":"그 작품에 몇 점을 주었는지 묻는다","mis":"K3-2-u6-X02"},{"t":"작품과 상관없는 일을 묻는다","mis":"K3-2-u6-X04"}],"explanation":["② 친구들이 돌아가며 “예.”, “아니요.”로 답할 수 있는 질문을 해요.","③ 작품을 알아맞힌 사람이 다음 문제를 내요.","놀이를 하며 내가 감상한 작품을 떠올려요."],"asset":{"type":"passage","lines":["① 한 명씩 돌아가며 재미나 감동을 느낀 작품을 머릿속으로 떠올린다.","② 친구들이 돌아가며 “예.”, “아니요.”로 답할 수 있는 질문을 한다.","③ 생각한 작품을 알아맞힌 사람이 다음 문제를 낸다.","④ 돌아가며 놀이를 계속 한다."],"numbered":false,"title":"이야기 제목 알아맞히기 다섯 고개 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L02_basic#10','kor',3,2,'u6','L02','tb_g3_2_kor_u6_L02_basic','lesson_basic','K3-2-u6-C7',3,'essay','teacher','『국어』 259쪽 2번처럼, 자신이 본 작품 가운데 하나를 골라 제목을 쓰고 재미나 감동을 느낀 부분과 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u6-C7","difficulty":3,"kind":"essay","stem":"『국어』 259쪽 2번처럼, 자신이 본 작품 가운데 하나를 골라 제목을 쓰고 재미나 감동을 느낀 부분과 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 제목 — 「아기 돼지 삼 형제」. 막내 돼지가 벽돌집을 지어 늑대를 물리치는 장면이 감동적이었다. 왜냐하면 나도 귀찮아도 숙제를 끝까지 해서 칭찬받은 적이 있어 꾸준히 하는 것이 중요하다고 느꼈기 때문이다.","scoring_points":["작품의 제목을 썼는가","재미나 감동을 느낀 부분(장면)을 썼는가","그렇게 느낀 까닭을 자신의 경험이나 생각과 이어 썼는가"]},"explanation":["독서 달력처럼 내가 본 작품을 떠올려요.","마음이 움직인 장면을 하나 골라요.","왜 그렇게 느꼈는지 까닭을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L02_challenge#1','kor',3,2,'u6','L02','tb_g3_2_kor_u6_L02_challenge','lesson_challenge','K3-2-u6-C1',2,'mc','auto','『국어』 257쪽 2번에서 세 친구가 경험을 말했어요. 의견을 제시하는 글을 써 본 경험을 말한 친구는 누구인가요?',ARRAY['K3-2-u6-X47']::text[],false,'{"seq":1,"concept":"K3-2-u6-C1","difficulty":2,"kind":"mc","stem":"『국어』 257쪽 2번에서 세 친구가 경험을 말했어요. 의견을 제시하는 글을 써 본 경험을 말한 친구는 누구인가요?","options":[{"t":"친구 1","correct":true},{"t":"친구 2","mis":"K3-2-u6-X47"},{"t":"친구 3","mis":"K3-2-u6-X47"}],"explanation":["친구 1은 쓰레기를 아무 데나 버리지 말자는 글을 써서 냈어요.","「버리지 말자」처럼 무엇을 하자는 생각을 담으면 의견을 제시하는 글이에요.","친구 2와 친구 3은 작품을 보고 감동이나 재미를 느낀 경험이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"학교에서 열린 글짓기 대회에 쓰레기를 아무 데나 버리지 말자는 글을 써서 낸 적이 있어."},{"who":"친구 2","text":"이순신 장군님이 나오는 영화를 감명 깊게 본 적이 있어."},{"who":"친구 3","text":"아기 오리들의 모험을 담은 만화를 재미있게 본 경험이 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L02_challenge#2','kor',3,2,'u6','L02','tb_g3_2_kor_u6_L02_challenge','lesson_challenge','K3-2-u6-C1',2,'mc','auto','이 단원 소단원 1에서 배울 내용을 차례대로 바르게 늘어놓은 것은 무엇인가요?',ARRAY['K3-2-u6-X11','K3-2-u6-X47']::text[],false,'{"seq":2,"concept":"K3-2-u6-C1","difficulty":2,"kind":"mc","stem":"이 단원 소단원 1에서 배울 내용을 차례대로 바르게 늘어놓은 것은 무엇인가요?","options":[{"t":"재미나 감동을 느낀 경험 말하기 → 만화 영화 감상하기 → 드라마 감상하기","correct":true},{"t":"드라마 감상하기 → 만화 영화 감상하기 → 재미나 감동을 느낀 경험 말하기","mis":"K3-2-u6-X11"},{"t":"의견을 제시하는 글 쓰기 → 만화 영화 감상하기 → 고쳐 쓰기","mis":"K3-2-u6-X47"},{"t":"만화 영화 감상하기 → 고쳐 쓰는 방법 알기 → 드라마 감상하기","mis":"K3-2-u6-X47"}],"explanation":["소단원 1은 재미나 감동을 느끼며 작품을 감상하는 공부예요.","경험 말하기 → 만화 영화 → 드라마 차례예요.","쓰기와 고쳐 쓰기는 소단원 2에서 배워요."],"asset":{"type":"passage","lines":["소단원 1 재미나 감동을 느끼며 작품 감상하기","  ① 작품을 감상하고 재미나 감동을 느낀 경험 말하기","  ② 재미나 감동을 느끼며 만화 영화 감상하기 ③ 드라마 감상하기","소단원 2 의견을 제시하는 글 쓰기","  ① 쓰는 방법 알기 ② 고쳐 쓰는 방법 알기 ③ 쓰고 고쳐 쓰기"],"title":"무엇을 배울까요 — 『국어』 256~257쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L02_challenge#3','kor',3,2,'u6','L02','tb_g3_2_kor_u6_L02_challenge','lesson_challenge','K3-2-u6-C1',3,'mc','auto','『국어』 256쪽 1번 (4)예요. 재미나 감동을 표현하는 글과 자신의 의견을 제시하는 글의 다른 점을 바르게 말한 것은 무엇인가요?',ARRAY['K3-2-u6-X47','K3-2-u6-X20','K3-2-u6-X06']::text[],false,'{"seq":3,"concept":"K3-2-u6-C1","difficulty":3,"kind":"mc","stem":"『국어』 256쪽 1번 (4)예요. 재미나 감동을 표현하는 글과 자신의 의견을 제시하는 글의 다른 점을 바르게 말한 것은 무엇인가요?","options":[{"t":"재미나 감동을 표현하는 글에는 감상한 사람이 느낀 재미나 감동이, 의견을 제시하는 글에는 문제 상황에 대한 의견과 이유가 나타난다","correct":true},{"t":"두 글은 이름만 다르고 쓰는 내용은 같다","mis":"K3-2-u6-X47"},{"t":"의견을 제시하는 글에는 이유를 쓰지 않는다","mis":"K3-2-u6-X20"},{"t":"재미나 감동을 표현하는 글에는 줄거리만 쓴다","mis":"K3-2-u6-X06"}],"explanation":["감상을 표현하는 글은 작품을 보고 느낀 재미나 감동이 잘 드러나요.","의견을 제시하는 글은 문제 상황에 대한 글쓴이의 의견과 이유가 나타나요.","윤솔이는 감동을 받았지만 의견을 제시하는 글을 쓰려고 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L02_challenge#4','kor',3,2,'u6','L02','tb_g3_2_kor_u6_L02_challenge','lesson_challenge','K3-2-u6-C4',3,'error','auto','「레오의 특별한 꿈」 대화를 읽고 친구들이 한 말이에요. 알맞지 않은 말은 무엇인가요?',ARRAY['K3-2-u6-X05','K3-2-u6-X03']::text[],false,'{"seq":4,"concept":"K3-2-u6-C4","difficulty":3,"kind":"error","stem":"「레오의 특별한 꿈」 대화를 읽고 친구들이 한 말이에요. 알맞지 않은 말은 무엇인가요?","options":[{"t":"“진짜 델이 생긴 장면이 감동적이라고 한 친구만 제대로 감상했어.”","correct":true,"mis_target":"K3-2-u6-X05"},{"t":"“같은 작품이라도 사람마다 재미나 감동을 느낀 부분이 다를 수 있어.”","mis":"K3-2-u6-X03"},{"t":"“레오를 안쓰럽게 느낀 친구는 놀림받았던 자기 경험을 떠올렸어.”","mis":"K3-2-u6-X05"}],"explanation":["세 친구는 모두 작품 속 장면을 근거로 말했어요.","느낀 부분이 달라도 모두 제 감상이에요.","한 사람만 제대로 감상했다고 할 수 없어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"1학기 때 교과서에서 읽은 「레오의 특별한 꿈」이 어때?"},{"who":"친구 2","text":"가짜 ‘델’을 달고 있다고 친구들에게 놀림받은 레오가 무척 안쓰러웠어. 나도 친구들에게 놀림받았을 때 속상했거든."},{"who":"친구 3","text":"신비한 능력이 없어도 좋으니까 ‘델’ 모양만이라도 만들어 달라고 마법사에게 조르는 레오의 모습이 조금은 재미있게 느껴졌어. 부모님께 물건을 사 달라고 부탁하는 내 모습 같았거든."},{"who":"친구 1","text":"그랬구나. 나는 레오가 진짜 꿈에 대해 생각하자 진짜 ‘델’이 생긴 장면이 감동적이었어. 나도 꿈을 이루기 위해 열심히 노력해야겠다고 생각했어."},{"who":"친구 2","text":"같은 작품을 보고도 재미나 감동을 느낀 부분이 다를 수 있구나."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L02_challenge#5','kor',3,2,'u6','L02','tb_g3_2_kor_u6_L02_challenge','lesson_challenge','K3-2-u6-C5',3,'mc','auto','같은 작품을 보고도 사람마다 재미나 감동을 느낀 부분이 다른 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X05','K3-2-u6-X13','K3-2-u6-X04']::text[],false,'{"seq":5,"concept":"K3-2-u6-C5","difficulty":3,"kind":"mc","stem":"같은 작품을 보고도 사람마다 재미나 감동을 느낀 부분이 다른 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"사람마다 처한 환경이나 겪은 경험이 다르기 때문","correct":true},{"t":"한 사람만 작품을 제대로 보았기 때문","mis":"K3-2-u6-X05"},{"t":"작품마다 감동할 곳이 하나로 정해져 있기 때문","mis":"K3-2-u6-X13"},{"t":"감상은 아무렇게나 말해도 되기 때문","mis":"K3-2-u6-X04"}],"explanation":["놀림받은 경험이 있는 친구는 놀림받는 장면에서 마음이 움직였어요.","사람마다 처한 환경과 경험이 달라요.","그래서 같은 작품에서도 느낀 부분이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L02_challenge#6','kor',3,2,'u6','L02','tb_g3_2_kor_u6_L02_challenge','lesson_challenge','K3-2-u6-C6',3,'blank','auto','친구 1의 감상을 정리했어요. 빈칸에 알맞은 말은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L02_challenge#7','kor',3,2,'u6','L02','tb_g3_2_kor_u6_L02_challenge','lesson_challenge','K3-2-u6-C7',3,'mc','auto','「레오의 특별한 꿈」을 감상한 말 가운데 재미나 감동을 느낀 부분과 그 까닭이 모두 드러난 것은 무엇인가요?',ARRAY['K3-2-u6-X07','K3-2-u6-X06','K3-2-u6-X02']::text[],false,'{"seq":7,"concept":"K3-2-u6-C7","difficulty":3,"kind":"mc","stem":"「레오의 특별한 꿈」을 감상한 말 가운데 재미나 감동을 느낀 부분과 그 까닭이 모두 드러난 것은 무엇인가요?","options":[{"t":"레오가 가짜 델을 스스로 없애는 장면이 멋졌어. 나도 거짓말 대신 솔직하게 말해서 마음이 편해진 적이 있거든.","correct":true},{"t":"그냥 다 재미있었어.","mis":"K3-2-u6-X07"},{"t":"레오는 마법의 숲에 가서 마법사를 만나고 마을로 돌아왔어.","mis":"K3-2-u6-X06"},{"t":"그 책은 별 다섯 개야.","mis":"K3-2-u6-X02"}],"explanation":["어느 장면에서 어떤 마음이 들었는지 말해요.","그렇게 느낀 까닭(나의 경험)도 붙여요.","느낌만, 줄거리만, 점수만으로는 감상이 드러나지 않아요."],"asset":{"type":"passage","lines":["(간추림) 꿈 마을 사람들 머리에는 저마다의 꿈이 담긴 ‘델’이 있지만 레오에게는 없었다.","(간추림) 마법사는 델 모양은 만들 수 있지만 능력은 만들 수 없다고 했다.","(간추림) 친구들은 레오 머리 위의 델이 가짜라는 것을 알아차렸다.","(간추림) 레오가 가짜 델을 스스로 없애고 진짜 꿈을 생각하자 진짜 델이 생겨났다."],"title":"「레오의 특별한 꿈」 간추린 줄거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L02_challenge#8','kor',3,2,'u6','L02','tb_g3_2_kor_u6_L02_challenge','lesson_challenge','K3-2-u6-C5',4,'ox','auto','「레오의 특별한 꿈」에서 조르는 장면이 재미있었다는 친구는, 진짜 델이 생긴 장면에 감동한 친구보다 작품을 덜 이해한 것이에요.',ARRAY['K3-2-u6-X03']::text[],false,'{"seq":8,"concept":"K3-2-u6-C5","difficulty":4,"kind":"ox","stem":"「레오의 특별한 꿈」에서 조르는 장면이 재미있었다는 친구는, 진짜 델이 생긴 장면에 감동한 친구보다 작품을 덜 이해한 것이에요.","answer":"X","reason_options":[{"t":"사람마다 겪은 일이 달라 마음이 움직인 곳이 다를 뿐, 둘 다 작품 속 장면을 근거로 말했기 때문에","correct":true},{"t":"감동을 느껴야 작품을 제대로 이해한 것이기 때문에","mis":"K3-2-u6-X03"}],"mis":"K3-2-u6-X03","explanation":["두 친구 모두 작품 안의 장면을 들었어요.","재미를 느낀 것도, 감동을 느낀 것도 제 감상이에요.","그래서 X예요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"1학기 때 교과서에서 읽은 「레오의 특별한 꿈」이 어때?"},{"who":"친구 2","text":"가짜 ‘델’을 달고 있다고 친구들에게 놀림받은 레오가 무척 안쓰러웠어. 나도 친구들에게 놀림받았을 때 속상했거든."},{"who":"친구 3","text":"신비한 능력이 없어도 좋으니까 ‘델’ 모양만이라도 만들어 달라고 마법사에게 조르는 레오의 모습이 조금은 재미있게 느껴졌어. 부모님께 물건을 사 달라고 부탁하는 내 모습 같았거든."},{"who":"친구 1","text":"그랬구나. 나는 레오가 진짜 꿈에 대해 생각하자 진짜 ‘델’이 생긴 장면이 감동적이었어. 나도 꿈을 이루기 위해 열심히 노력해야겠다고 생각했어."},{"who":"친구 2","text":"같은 작품을 보고도 재미나 감동을 느낀 부분이 다를 수 있구나."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L02_challenge#9','kor',3,2,'u6','L02','tb_g3_2_kor_u6_L02_challenge','lesson_challenge','K3-2-u6-C4',4,'essay','teacher','친구와 같은 작품을 보았는데 서로 다른 장면에서 재미나 감동을 느꼈어요. 이때 친구에게 어떻게 말하면 좋을지, 「레오의 특별한 꿈」 대화를 떠올려 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u6-C4","difficulty":4,"kind":"essay","stem":"친구와 같은 작품을 보았는데 서로 다른 장면에서 재미나 감동을 느꼈어요. 이때 친구에게 어떻게 말하면 좋을지, 「레오의 특별한 꿈」 대화를 떠올려 쓰세요.","answer_guide":{"answer":"예: “너는 조르는 장면이 재미있었구나. 나는 진짜 델이 생긴 장면이 감동적이었어. 나도 꿈을 이루려고 노력하고 싶었거든. 같은 작품인데 느낀 부분이 다르니까 다시 보면 네가 말한 장면도 눈여겨볼게.”","scoring_points":["친구의 감상을 인정하는 말을 썼는가","자신이 느낀 부분과 까닭을 썼는가","감상이 다를 수 있다는 생각이 드러났는가"]},"explanation":["친구의 감상도 제 감상이에요.","내가 느낀 부분과 까닭을 함께 말해요.","서로 나누면 작품을 더 넓게 볼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L02_challenge#10','kor',3,2,'u6','L02','tb_g3_2_kor_u6_L02_challenge','lesson_challenge','K3-2-u6-C1',4,'essay','teacher','윤솔이처럼 감상한 작품에서 의견을 제시하는 글을 떠올려 보아요. 자신이 본 작품 하나를 골라 느낀 감동을 한 문장으로 쓰고, 그 작품과 관련해 제시하고 싶은 의견을 이유와 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u6-C1","difficulty":4,"kind":"essay","stem":"윤솔이처럼 감상한 작품에서 의견을 제시하는 글을 떠올려 보아요. 자신이 본 작품 하나를 골라 느낀 감동을 한 문장으로 쓰고, 그 작품과 관련해 제시하고 싶은 의견을 이유와 함께 쓰세요.","answer_guide":{"answer":"예: 「이순신」 영화에서 나라를 지키려고 끝까지 싸운 장군의 모습에 감동했다. 그래서 우리 반도 맡은 일을 끝까지 책임지자는 의견을 제시하고 싶다. 왜냐하면 한 사람이 맡은 일을 미루면 다른 친구들이 힘들어지기 때문이다.","scoring_points":["작품과 느낀 감동을 썼는가","작품과 관련된 의견을 썼는가","의견에 대한 이유를 썼는가"]},"explanation":["먼저 작품에서 느낀 감동을 써요.","감상에서 떠오른 의견을 「……하자」로 써요.","왜 그렇게 생각하는지 이유도 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L03_basic#1','kor',3,2,'u6','L03','tb_g3_2_kor_u6_L03_basic','lesson_basic','K3-2-u6-C42',1,'mc','auto','「건전지 엄마」를 보기 전에 우리 주변에서 건전지가 쓰이는 곳(리모컨, 손전등, 시계, 장난감 …)을 생각그물로 정리했어요. 이렇게 하는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X01','K3-2-u6-X04','K3-2-u6-X02']::text[],false,'{"seq":1,"concept":"K3-2-u6-C42","difficulty":1,"kind":"mc","stem":"「건전지 엄마」를 보기 전에 우리 주변에서 건전지가 쓰이는 곳(리모컨, 손전등, 시계, 장난감 …)을 생각그물로 정리했어요. 이렇게 하는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"건전지가 하는 일을 떠올려 건전지 엄마가 하는 일과 이어 보며 작품을 더 잘 이해하려고","correct":true},{"t":"건전지의 값을 외우려고","mis":"K3-2-u6-X01"},{"t":"작품을 보지 않고 줄거리를 짐작해 끝내려고","mis":"K3-2-u6-X04"},{"t":"건전지를 가장 많이 아는 사람에게 점수를 주려고","mis":"K3-2-u6-X02"}],"explanation":["건전지는 물건이 움직이도록 힘을 주어요.","생활 속 건전지의 역할을 떠올리면","건전지 엄마가 하는 일을 더 잘 이해할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L03_basic#2','kor',3,2,'u6','L03','tb_g3_2_kor_u6_L03_basic','lesson_basic','K3-2-u6-C8',1,'mc','auto','「건전지 엄마」는 대사가 없는 만화 영화예요. 인물의 생각이나 마음을 짐작하려면 무엇을 살펴보면 좋을까요?',ARRAY['K3-2-u6-X09','K3-2-u6-X04']::text[],false,'{"seq":2,"concept":"K3-2-u6-C8","difficulty":1,"kind":"mc","stem":"「건전지 엄마」는 대사가 없는 만화 영화예요. 인물의 생각이나 마음을 짐작하려면 무엇을 살펴보면 좋을까요?","options":[{"t":"인물의 표정과 행동","correct":true},{"t":"인물의 키","mis":"K3-2-u6-X09"},{"t":"배경이 되는 날씨","mis":"K3-2-u6-X09"},{"t":"인물이 한 대사","mis":"K3-2-u6-X04"}],"explanation":["대사가 없어도 마음을 알 수 있어요.","얼굴 표정과 몸짓, 행동을 살펴봐요.","인물의 키나 날씨는 마음과 상관없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L03_basic#3','kor',3,2,'u6','L03','tb_g3_2_kor_u6_L03_basic','lesson_basic','K3-2-u6-C42',1,'mc','auto','「건전지 엄마」의 장면 가운데 가장 먼저 일어난 일은 무엇인가요?',ARRAY['K3-2-u6-X11']::text[],false,'{"seq":3,"concept":"K3-2-u6-C42","difficulty":1,"kind":"mc","stem":"「건전지 엄마」의 장면 가운데 가장 먼저 일어난 일은 무엇인가요?","options":[{"t":"어린이집에서 낮잠 시간에 아이들이 모두 잠들었다","correct":true},{"t":"건전지 엄마가 있는 힘껏 비상벨을 울렸다","mis":"K3-2-u6-X11"},{"t":"아이들이 무사히 대피했다","mis":"K3-2-u6-X11"},{"t":"건전지 엄마가 집에 와서 행복하게 잠들었다","mis":"K3-2-u6-X11"}],"explanation":["처음 장면은 평화로운 낮잠 시간이에요.","그다음 타는 냄새 → 구하러 나섬 → 비상벨 차례예요.","맨 끝에 아이들이 대피하고 건전지 엄마도 잠들어요."],"asset":{"type":"passage","lines":["① 어린이집에서 낮잠 시간에 아이들이 모두 잠들었습니다.","② 건전지 엄마는 타는 냄새가 나는 것을 느꼈습니다.","③ 건전지 엄마는 위험을 무릅쓰고 아이들을 구하려고 나섰습니다.","④ 건전지 엄마는 있는 힘껏 비상벨을 울렸습니다.","⑤ 비상벨을 들은 아이들은 무사히 대피하고,","   건전지 엄마도 집에 와서 행복하게 잠들었습니다."],"numbered":false,"title":"「건전지 엄마」 장면을 보고 요약하여 말하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L03_basic#4','kor',3,2,'u6','L03','tb_g3_2_kor_u6_L03_basic','lesson_basic','K3-2-u6-C11',1,'ox','auto','만화 영화를 감상할 때 배경 음악이나 효과음에 집중하며 보는 것도 재미나 감동을 느끼는 방법이에요.',ARRAY['K3-2-u6-X42']::text[],false,'{"seq":4,"concept":"K3-2-u6-C11","difficulty":1,"kind":"ox","stem":"만화 영화를 감상할 때 배경 음악이나 효과음에 집중하며 보는 것도 재미나 감동을 느끼는 방법이에요.","answer":"O","reason_options":[{"t":"예서처럼 평화로운 음악이 갑자기 멈추는 데서 무슨 일이 생길 것 같은 느낌을 받을 수 있기 때문에","correct":true},{"t":"재미나 감동은 인물의 모습에서만 느낄 수 있기 때문에","mis":"K3-2-u6-X42"}],"mis":"K3-2-u6-X42","explanation":["만화 영화는 영상과 소리가 함께 만든 작품이에요.","배경 음악과 효과음도 분위기를 생생하게 해 줘요.","그래서 O예요."],"asset":{"type":"speech","turns":[{"who":"하준","text":"아이들을 구하려고 달려가는 건전지 엄마의 표정을 보고 다급한 상황이 실감 났어."},{"who":"예서","text":"유치원 아이들이 낮잠 잘 때 평화로운 음악이 흐르다가 갑자기 멈춰서 무슨 일이 생길 것만 같았어."},{"who":"시윤","text":"아이들을 구한 건전지 엄마처럼 나도 용기 있게 행동하고 싶어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L03_basic#5','kor',3,2,'u6','L03','tb_g3_2_kor_u6_L03_basic','lesson_basic','K3-2-u6-C42',2,'mc','auto','『국어』 261쪽처럼 붙임딱지를 사건이 일어난 차례대로 붙이려고 해요. 바른 차례는 무엇인가요?',ARRAY['K3-2-u6-X11']::text[],false,'{"seq":5,"concept":"K3-2-u6-C42","difficulty":2,"kind":"mc","stem":"『국어』 261쪽처럼 붙임딱지를 사건이 일어난 차례대로 붙이려고 해요. 바른 차례는 무엇인가요?","options":[{"t":"㉯ → ㉱ → ㉲ → ㉮ → ㉰","correct":true},{"t":"㉯ → ㉮ → ㉱ → ㉲ → ㉰","mis":"K3-2-u6-X11"},{"t":"㉱ → ㉯ → ㉲ → ㉰ → ㉮","mis":"K3-2-u6-X11"},{"t":"㉯ → ㉱ → ㉮ → ㉰ → ㉲","mis":"K3-2-u6-X11"}],"explanation":["낮잠 시간(㉯) → 타는 냄새(㉱) → 구하러 나섬(㉲)이에요.","그다음 비상벨(㉮)을 울리고 아이들이 대피해요(㉰).","붙인 딱지를 보며 시간의 흐름에 따라 요약해 말해요."],"asset":{"type":"passage","lines":["㉮ 건전지 엄마가 있는 힘껏 비상벨을 울렸다.","㉯ 낮잠 시간에 아이들이 모두 잠들었다.","㉰ 아이들이 무사히 대피하고 건전지 엄마도 집에서 잠들었다.","㉱ 건전지 엄마가 타는 냄새를 느꼈다.","㉲ 건전지 엄마가 위험을 무릅쓰고 아이들을 구하려고 나섰다."],"numbered":false,"title":"「건전지 엄마」 장면 붙임딱지 (뒤섞임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L03_basic#6','kor',3,2,'u6','L03','tb_g3_2_kor_u6_L03_basic','lesson_basic','K3-2-u6-C9',2,'mc','auto','[장면 2]에서 건전지 엄마는 위험을 무릅쓰고 아이들을 구하려고 나섰어요. 이때 건전지 엄마의 생각이나 마음으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X10']::text[],false,'{"seq":6,"concept":"K3-2-u6-C9","difficulty":2,"kind":"mc","stem":"[장면 2]에서 건전지 엄마는 위험을 무릅쓰고 아이들을 구하려고 나섰어요. 이때 건전지 엄마의 생각이나 마음으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“여기서 포기할 수 없어. 어떻게든 아이들을 구해야 해.”","correct":true},{"t":"“오늘은 일하기 싫으니 그만 쉬어야지.”","mis":"K3-2-u6-X10"},{"t":"“아이들이 깨면 시끄러우니 조용히 있어야지.”","mis":"K3-2-u6-X10"},{"t":"“오늘도 참 뿌듯한 하루였어.”","mis":"K3-2-u6-X10"}],"explanation":["위험을 무릅쓰고 아이들을 구하려고 나선 행동이에요.","앞에서 타는 냄새를 느낀 일과 이어 보아요.","「뿌듯한 하루」는 모든 일이 끝난 맨 마지막 장면의 마음이에요."],"asset":{"type":"passage","lines":["[장면 1] 첫 장면 → “아이들에게 도움이 되도록 열심히 일해야지.” (교과서에 적힌 예)","[장면 2] 위험을 무릅쓰고 아이들을 구하려고 나선 건전지 엄마","[장면 3] 있는 힘껏 비상벨을 울리는 건전지 엄마","[장면 4] 집에 와서 아기 건전지들을 안아 주고 행복하게 잠든 건전지 엄마"],"numbered":false,"title":"인물의 표정이나 행동 → 인물의 생각이나 마음 (『국어』 262쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L03_basic#7','kor',3,2,'u6','L03','tb_g3_2_kor_u6_L03_basic','lesson_basic','K3-2-u6-C11',2,'match','auto','「건전지 엄마」를 감상한 친구들의 말과 그 친구가 쓴 감상 방법을 바르게 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K3-2-u6-C11","difficulty":2,"kind":"match","stem":"「건전지 엄마」를 감상한 친구들의 말과 그 친구가 쓴 감상 방법을 바르게 이어 보세요.","pairs":[{"l":"하준: 달려가는 건전지 엄마의 표정을 보고 다급한 상황이 실감 났어.","r":"인물의 실감 나는 표정이나 말투에 주의하며 보았다."},{"l":"예서: 평화로운 음악이 갑자기 멈춰서 무슨 일이 생길 것만 같았어.","r":"분위기를 생생하게 해 주는 배경 음악이나 효과음에 집중하며 보았다."},{"l":"시윤: 건전지 엄마처럼 나도 용기 있게 행동하고 싶어.","r":"이야기의 주제나 인물에게서 얻을 수 있는 교훈을 떠올리며 보았다."}],"mis":"K3-2-u6-X12","explanation":["하준이는 표정을, 예서는 음악을 보았어요.","시윤이는 인물에게서 배울 점을 떠올렸어요.","재미나 감동을 느끼는 감상 방법은 여러 가지예요."],"asset":{"type":"speech","turns":[{"who":"하준","text":"아이들을 구하려고 달려가는 건전지 엄마의 표정을 보고 다급한 상황이 실감 났어."},{"who":"예서","text":"유치원 아이들이 낮잠 잘 때 평화로운 음악이 흐르다가 갑자기 멈춰서 무슨 일이 생길 것만 같았어."},{"who":"시윤","text":"아이들을 구한 건전지 엄마처럼 나도 용기 있게 행동하고 싶어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L03_basic#8','kor',3,2,'u6','L03','tb_g3_2_kor_u6_L03_basic','lesson_basic','K3-2-u6-C9',2,'mc','auto','[장면 3]에서 건전지 엄마는 있는 힘껏 비상벨을 울렸어요. 이때 건전지 엄마가 속으로 했을 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X10']::text[],false,'{"seq":8,"concept":"K3-2-u6-C9","difficulty":2,"kind":"mc","stem":"[장면 3]에서 건전지 엄마는 있는 힘껏 비상벨을 울렸어요. 이때 건전지 엄마가 속으로 했을 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“얘들아, 제발 일어나!”","correct":true},{"t":"“시끄러우니 다들 계속 자렴.”","mis":"K3-2-u6-X10"},{"t":"“아이들에게 도움이 되도록 열심히 일해야지.”","mis":"K3-2-u6-X10"},{"t":"“비상벨 소리가 참 예쁘구나.”","mis":"K3-2-u6-X10"}],"explanation":["비상벨은 위험을 알리는 소리예요.","아이들이 깨어 대피해야 하는 다급한 상황이에요.","표정과 행동, 앞의 일과 어울리는 말을 골라요."],"asset":{"type":"passage","lines":["[장면 1] 첫 장면 → “아이들에게 도움이 되도록 열심히 일해야지.” (교과서에 적힌 예)","[장면 2] 위험을 무릅쓰고 아이들을 구하려고 나선 건전지 엄마","[장면 3] 있는 힘껏 비상벨을 울리는 건전지 엄마","[장면 4] 집에 와서 아기 건전지들을 안아 주고 행복하게 잠든 건전지 엄마"],"numbered":false,"title":"인물의 표정이나 행동 → 인물의 생각이나 마음 (『국어』 262쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L03_basic#9','kor',3,2,'u6','L03','tb_g3_2_kor_u6_L03_basic','lesson_basic','K3-2-u6-C13',2,'mc','auto','자신이 느낀 재미나 감동을 친구들과 나누면 좋은 점으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X14','K3-2-u6-X02']::text[],false,'{"seq":9,"concept":"K3-2-u6-C13","difficulty":2,"kind":"mc","stem":"자신이 느낀 재미나 감동을 친구들과 나누면 좋은 점으로 알맞은 것은 무엇인가요?","options":[{"t":"작품을 다시 볼 때 친구들이 말했던 장면이 생각나서 또 다른 재미를 느낄 수 있다","correct":true},{"t":"내 감상이 맞는지 확인받을 수 있다","mis":"K3-2-u6-X14"},{"t":"모두 같은 장면을 고르도록 맞출 수 있다","mis":"K3-2-u6-X14"},{"t":"감상 점수를 매겨 1등을 정할 수 있다","mis":"K3-2-u6-X02"}],"explanation":["친구들은 내가 못 보고 지나친 장면을 말해 줘요.","다시 볼 때 그 장면이 떠올라 작품이 넓어져요.","맞고 틀림을 가리려고 나누는 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L03_basic#10','kor',3,2,'u6','L03','tb_g3_2_kor_u6_L03_basic','lesson_basic','K3-2-u6-C12',3,'essay','teacher','『국어』 263쪽 (2)처럼, 「건전지 엄마」를 감상할 때 자신이 쓴 감상 방법과 재미나 감동을 느낀 부분을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u6-C12","difficulty":3,"kind":"essay","stem":"『국어』 263쪽 (2)처럼, 「건전지 엄마」를 감상할 때 자신이 쓴 감상 방법과 재미나 감동을 느낀 부분을 쓰세요.","answer_guide":{"answer":"예: 감상 방법 — 인물의 실감 나는 표정이나 말투에 유의하며 보았다. 느낀 부분 — 건전지 엄마가 아이들을 구하고 집으로 가서 아기 건전지들을 안아 줄 때 행복한 표정이 느껴져서 나도 덩달아 행복했다.","scoring_points":["감상 방법(표정·말투, 배경 음악·효과음, 주제·교훈 가운데)을 썼는가","재미나 감동을 느낀 장면을 썼는가","그 장면에서 든 마음을 썼는가"]},"explanation":["세 가지 감상 방법 가운데 내가 쓴 것을 골라요.","그 방법으로 보았을 때 마음이 움직인 장면을 써요.","장면 + 마음을 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L03_challenge#1','kor',3,2,'u6','L03','tb_g3_2_kor_u6_L03_challenge','lesson_challenge','K3-2-u6-C12',2,'blank','auto','『국어활동』 85쪽이에요. 정운이가 시 「눈사람 넷」에서 재미를 느낀 부분이에요. 빈칸에 알맞은 말은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L03_challenge#2','kor',3,2,'u6','L03','tb_g3_2_kor_u6_L03_challenge','lesson_challenge','K3-2-u6-C12',2,'match','auto','시 「눈사람 넷」을 읽고 친구들이 느낀 재미를 표현하도록 빈칸에 들어갈 말을 이어 보세요.','{}'::text[],false,'{"seq":2,"concept":"K3-2-u6-C12","difficulty":2,"kind":"match","stem":"시 「눈사람 넷」을 읽고 친구들이 느낀 재미를 표현하도록 빈칸에 들어갈 말을 이어 보세요.","pairs":[{"l":"정운: 눈이 (    ) 내린다고 표현한 부분","r":"펑펑"},{"l":"유연: 눈을 맞은 친구들을 (    )(으)로 표현한 것","r":"눈사람"},{"l":"단우: 집에 가는 것을 (    )을/를 데리고 간다고 표현한 것","r":"눈 세상"}],"mis":"K3-2-u6-X13","explanation":["세 친구는 한 시에서 서로 다른 부분을 재미있어했어요.","느낄 수 있는 자리가 한 곳만 있는 것이 아니에요.","그래도 모두 시 안에 있는 표현이에요."],"asset":{"type":"speech","turns":[{"who":"정운","text":"눈이 (    ) 내린다고 표현한 부분이 재미있었어."},{"who":"유연","text":"눈을 맞은 친구들을 (    )(으)로 표현한 것이 재미있었어."},{"who":"단우","text":"눈을 맞은 친구들이 집에 가는 것을 (    )을/를 데리고 간다고 표현한 것이 재미있었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L03_challenge#3','kor',3,2,'u6','L03','tb_g3_2_kor_u6_L03_challenge','lesson_challenge','K3-2-u6-C12',3,'mc','auto','『국어활동』 85쪽 3번이에요. 「눈사람 넷, 집에 간다 / 눈 세상 데리고 간다.」에서 재미를 느낀 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X01','K3-2-u6-X04','K3-2-u6-X13']::text[],false,'{"seq":3,"concept":"K3-2-u6-C12","difficulty":3,"kind":"mc","stem":"『국어활동』 85쪽 3번이에요. 「눈사람 넷, 집에 간다 / 눈 세상 데리고 간다.」에서 재미를 느낀 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"눈을 맞은 사람들을 눈사람이라고 표현한 부분이 재미있게 느껴져서","correct":true},{"t":"시에 「눈」이라는 낱말이 몇 번 나오는지 세어 보아서","mis":"K3-2-u6-X01"},{"t":"눈이 오면 학교에 가지 않아도 되어서","mis":"K3-2-u6-X04"},{"t":"시는 끝부분에서만 재미를 느낄 수 있어서","mis":"K3-2-u6-X13"}],"explanation":["눈을 흠뻑 맞은 친구 넷이 눈사람처럼 보였어요.","그 친구들이 눈 세상을 데리고 간다니 장면이 재미있게 떠올라요.","시에서 느낀 부분과 까닭을 함께 말해요."],"asset":{"type":"passage","lines":["눈사람 넷, 집에 간다","눈 세상 데리고 간다.","[친구들의 말에서] 눈이 펑펑 내리고, 눈을 맞은 친구들이 집에 간다."],"title":"시 「눈사람 넷」 끝부분 — 『국어활동』 84쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L03_challenge#4','kor',3,2,'u6','L03','tb_g3_2_kor_u6_L03_challenge','lesson_challenge','K3-2-u6-C11',3,'mc','auto','시를 감상하며 재미나 감동을 느끼는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X12','K3-2-u6-X13','K3-2-u6-X01']::text[],false,'{"seq":4,"concept":"K3-2-u6-C11","difficulty":3,"kind":"mc","stem":"시를 감상하며 재미나 감동을 느끼는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"눈 오는 날 친구들과 놀다 온몸이 하얘졌던 경험을 떠올리며 읽는다","correct":true},{"t":"시의 글자 수를 세며 읽는다","mis":"K3-2-u6-X12"},{"t":"한 번 읽고 정해진 감동 한 곳만 찾는다","mis":"K3-2-u6-X13"},{"t":"시를 쓴 사람의 이름만 외운다","mis":"K3-2-u6-X01"}],"explanation":["떠오르는 장면을 상상하며 읽어요.","시와 비슷한 내 경험을 떠올려요.","소리 내어 낭송하며 느낄 수도 있어요."],"asset":{"type":"passage","lines":["눈사람 넷, 집에 간다","눈 세상 데리고 간다.","[친구들의 말에서] 눈이 펑펑 내리고, 눈을 맞은 친구들이 집에 간다."],"title":"시 「눈사람 넷」 끝부분 — 『국어활동』 84쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L03_challenge#5','kor',3,2,'u6','L03','tb_g3_2_kor_u6_L03_challenge','lesson_challenge','K3-2-u6-C9',3,'error','auto','『국어』 262쪽 표에 친구들이 건전지 엄마의 생각이나 마음을 써 넣었어요. 인물의 표정이나 행동과 어울리지 않는 것은 무엇인가요?',ARRAY['K3-2-u6-X10','K3-2-u6-X09']::text[],false,'{"seq":5,"concept":"K3-2-u6-C9","difficulty":3,"kind":"error","stem":"『국어』 262쪽 표에 친구들이 건전지 엄마의 생각이나 마음을 써 넣었어요. 인물의 표정이나 행동과 어울리지 않는 것은 무엇인가요?","options":[{"t":"[장면 3] 있는 힘껏 비상벨을 울림 → “심심한데 노래나 불러 볼까?”","correct":true,"mis_target":"K3-2-u6-X10"},{"t":"[장면 2] 위험을 무릅쓰고 나아감 → “어떻게든 아이들을 구해야 해.”","mis":"K3-2-u6-X09"},{"t":"[장면 4] 아기 건전지들을 안아 주고 잠듦 → “오늘도 참 뿌듯한 하루였어.”","mis":"K3-2-u6-X10"}],"explanation":["정해진 정답은 없지만 표정이나 행동과 어울려야 해요.","비상벨을 있는 힘껏 울리는 것은 다급한 행동이에요.","어울리지 않으면 상황에 더 알맞은 말을 다시 생각해요."],"asset":{"type":"passage","lines":["[장면 1] 첫 장면 → “아이들에게 도움이 되도록 열심히 일해야지.” (교과서에 적힌 예)","[장면 2] 위험을 무릅쓰고 아이들을 구하려고 나선 건전지 엄마","[장면 3] 있는 힘껏 비상벨을 울리는 건전지 엄마","[장면 4] 집에 와서 아기 건전지들을 안아 주고 행복하게 잠든 건전지 엄마"],"numbered":false,"title":"인물의 표정이나 행동 → 인물의 생각이나 마음 (『국어』 262쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L03_challenge#6','kor',3,2,'u6','L03','tb_g3_2_kor_u6_L03_challenge','lesson_challenge','K3-2-u6-C11',3,'mc','auto','「건전지 엄마」와 비슷한 작품으로 「건전지 아빠」가 있어요. 같은 내용을 만화 영화와 그림책으로 각각 감상했을 때 해 볼 만한 활동은 무엇인가요?',ARRAY['K3-2-u6-X03','K3-2-u6-X42','K3-2-u6-X01']::text[],false,'{"seq":6,"concept":"K3-2-u6-C11","difficulty":3,"kind":"mc","stem":"「건전지 엄마」와 비슷한 작품으로 「건전지 아빠」가 있어요. 같은 내용을 만화 영화와 그림책으로 각각 감상했을 때 해 볼 만한 활동은 무엇인가요?","options":[{"t":"두 작품을 보고 다른 점과 각각에서 느낀 재미나 감동을 말해 본다","correct":true},{"t":"둘 가운데 하나는 틀린 작품이므로 하나만 고른다","mis":"K3-2-u6-X03"},{"t":"그림책은 음악이 없으니 감상할 거리가 없다고 정한다","mis":"K3-2-u6-X42"},{"t":"두 작품의 쪽수와 상영 시간만 비교한다","mis":"K3-2-u6-X01"}],"explanation":["만화 영화는 영상과 소리로, 그림책은 그림과 글로 감상해요.","감상하는 방법이 다르면 느낀 재미나 감동도 달라질 수 있어요.","다른 점을 말해 보면 감상이 넓어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L03_challenge#7','kor',3,2,'u6','L03','tb_g3_2_kor_u6_L03_challenge','lesson_challenge','K3-2-u6-C8',3,'mc','auto','건전지 엄마가 타는 냄새가 나는 것을 느낀 장면이에요. 대사는 없지만 이때 건전지 엄마의 마음으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X10','K3-2-u6-X09']::text[],false,'{"seq":7,"concept":"K3-2-u6-C8","difficulty":3,"kind":"mc","stem":"건전지 엄마가 타는 냄새가 나는 것을 느낀 장면이에요. 대사는 없지만 이때 건전지 엄마의 마음으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"걱정되고 다급한 마음","correct":true},{"t":"느긋하고 심심한 마음","mis":"K3-2-u6-X10"},{"t":"졸리고 귀찮은 마음","mis":"K3-2-u6-X10"},{"t":"건전지 엄마의 키가 작아서 슬픈 마음","mis":"K3-2-u6-X09"}],"explanation":["아이들이 모두 잠든 낮잠 시간이에요.","타는 냄새는 불이 났을지도 모른다는 신호예요.","표정과 행동을 살피며 걱정되고 다급한 마음을 짐작해요."],"asset":{"type":"passage","lines":["① 어린이집에서 낮잠 시간에 아이들이 모두 잠들었습니다.","② 건전지 엄마는 타는 냄새가 나는 것을 느꼈습니다.","③ 건전지 엄마는 위험을 무릅쓰고 아이들을 구하려고 나섰습니다.","④ 건전지 엄마는 있는 힘껏 비상벨을 울렸습니다.","⑤ 비상벨을 들은 아이들은 무사히 대피하고,","   건전지 엄마도 집에 와서 행복하게 잠들었습니다."],"numbered":false,"title":"「건전지 엄마」 장면을 보고 요약하여 말하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L03_challenge#8','kor',3,2,'u6','L03','tb_g3_2_kor_u6_L03_challenge','lesson_challenge','K3-2-u6-C9',4,'essay','teacher','[장면 4]에서 건전지 엄마는 집에 와서 아기 건전지들을 안아 주고 행복하게 잠들어요. 이때 건전지 엄마의 생각이나 마음을 말로 쓰고, 그렇게 짐작한 까닭을 표정이나 행동에서 찾아 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u6-C9","difficulty":4,"kind":"essay","stem":"[장면 4]에서 건전지 엄마는 집에 와서 아기 건전지들을 안아 주고 행복하게 잠들어요. 이때 건전지 엄마의 생각이나 마음을 말로 쓰고, 그렇게 짐작한 까닭을 표정이나 행동에서 찾아 쓰세요.","answer_guide":{"answer":"예: “아이들도 무사하고 우리 아기들도 곁에 있으니 정말 다행이야.” 까닭 — 아기 건전지들을 안아 주고 행복하게 잠든 모습에서 안심되고 행복한 마음을 알 수 있기 때문이다.","scoring_points":["인물의 생각이나 마음을 말로 썼는가","표정이나 행동을 근거로 들었는가","앞의 사건(아이들을 구한 일)과 이어 짐작했는가"]},"explanation":["정해진 정답은 없어요.","표정과 행동이 근거예요.","앞에서 있었던 일과 이어 보면 마음이 보여요."],"asset":{"type":"passage","lines":["[장면 1] 첫 장면 → “아이들에게 도움이 되도록 열심히 일해야지.” (교과서에 적힌 예)","[장면 2] 위험을 무릅쓰고 아이들을 구하려고 나선 건전지 엄마","[장면 3] 있는 힘껏 비상벨을 울리는 건전지 엄마","[장면 4] 집에 와서 아기 건전지들을 안아 주고 행복하게 잠든 건전지 엄마"],"numbered":false,"title":"인물의 표정이나 행동 → 인물의 생각이나 마음 (『국어』 262쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L03_challenge#9','kor',3,2,'u6','L03','tb_g3_2_kor_u6_L03_challenge','lesson_challenge','K3-2-u6-C12',4,'essay','teacher','미술 시간과 이어서 「건전지 엄마」에서 재미나 감동을 느낀 부분을 그림으로 그리려고 해요. 어떤 장면을 어떻게 그릴지 쓰고, 그 장면을 고른 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u6-C12","difficulty":4,"kind":"essay","stem":"미술 시간과 이어서 「건전지 엄마」에서 재미나 감동을 느낀 부분을 그림으로 그리려고 해요. 어떤 장면을 어떻게 그릴지 쓰고, 그 장면을 고른 까닭을 쓰세요.","answer_guide":{"answer":"예: 건전지 엄마가 위험을 무릅쓰고 아이들을 구하려고 나서는 장면을 그리겠다. 이마에 땀방울을 그리고 잠든 아이들을 함께 그려 위험한 상황을 나타내겠다. 무서울 텐데도 아이들을 먼저 생각하는 모습에서 가장 큰 감동을 느꼈기 때문이다.","scoring_points":["그릴 장면을 정했는가","어떻게 그릴지(표정·행동·배경)를 썼는가","그 장면에서 느낀 재미나 감동을 까닭으로 썼는가"]},"explanation":["느낀 재미나 감동은 그림으로도 나타낼 수 있어요.","인물의 표정과 행동을 살려 그려요.","왜 그 장면인지 까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L03_challenge#10','kor',3,2,'u6','L03','tb_g3_2_kor_u6_L03_challenge','lesson_challenge','K3-2-u6-C11',4,'mc','auto','「건전지 엄마」를 감상한 말 가운데 시윤이와 같은 감상 방법(주제나 교훈 떠올리기)으로 감상한 것은 무엇인가요?',ARRAY['K3-2-u6-X12','K3-2-u6-X04']::text[],false,'{"seq":10,"concept":"K3-2-u6-C11","difficulty":4,"kind":"mc","stem":"「건전지 엄마」를 감상한 말 가운데 시윤이와 같은 감상 방법(주제나 교훈 떠올리기)으로 감상한 것은 무엇인가요?","options":[{"t":"“위험한 순간에도 아이들부터 챙기는 모습을 보니, 나도 어려운 친구를 먼저 도울 줄 아는 사람이 되고 싶어.”","correct":true},{"t":"“평화로운 음악이 갑자기 멈추는 순간 가슴이 철렁했어.”","mis":"K3-2-u6-X12"},{"t":"“달려가는 건전지 엄마의 표정을 보니 얼마나 급한지 알겠더라.”","mis":"K3-2-u6-X12"},{"t":"“건전지는 장난감에 넣는 물건이야.”","mis":"K3-2-u6-X04"}],"explanation":["시윤이는 인물에게서 얻을 수 있는 교훈을 떠올렸어요.","음악에 집중한 말은 예서, 표정에 주의한 말은 하준이의 방법이에요.","작품과 상관없는 말은 감상이 아니에요."],"asset":{"type":"speech","turns":[{"who":"하준","text":"아이들을 구하려고 달려가는 건전지 엄마의 표정을 보고 다급한 상황이 실감 났어."},{"who":"예서","text":"유치원 아이들이 낮잠 잘 때 평화로운 음악이 흐르다가 갑자기 멈춰서 무슨 일이 생길 것만 같았어."},{"who":"시윤","text":"아이들을 구한 건전지 엄마처럼 나도 용기 있게 행동하고 싶어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L05_basic#1','kor',3,2,'u6','L05','tb_g3_2_kor_u6_L05_basic','lesson_basic','K3-2-u6-C43',1,'sa','auto','드라마 「신통방통 니 맘 내 맘 계산기」에 나오는 용용이는 세상에 사라지지 않고 살아남은 단 하나의 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u6-C43","difficulty":1,"kind":"sa","stem":"드라마 「신통방통 니 맘 내 맘 계산기」에 나오는 용용이는 세상에 사라지지 않고 살아남은 단 하나의 무엇인가요? 두 글자로 쓰세요.","answer":["공룡"],"explanation":["등장인물은 신비, 용용이, 아빠, 마리, 기동이에요.","용용이는 살아남은 단 하나의 공룡이에요.","용용이가 신비에게 마법으로 계산기를 주어요."],"asset":{"type":"passage","lines":["등장인물 — 신비, 용용이(살아남은 단 하나의 공룡), 아빠, 마리, 기동","(간추림) 신비는 주변 사람들의 행동을 자기중심적으로 생각해","친구들의 마음을 오해했다.","(간추림) 용용이가 마법으로 ‘니 맘 내 맘 계산기’를 주었다.","(간추림) 신비는 계산기로 친구들과 가족의 진심을 깨닫고 반성했다."],"title":"「신통방통 니 맘 내 맘 계산기」 간추린 줄거리"},"mis":"K3-2-u6-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L05_basic#2','kor',3,2,'u6','L05','tb_g3_2_kor_u6_L05_basic','lesson_basic','K3-2-u6-C43',1,'match','auto','『국어』 265쪽 낱말 알기예요. 낱말과 뜻을 바르게 이어 보세요.','{}'::text[],false,'{"seq":2,"concept":"K3-2-u6-C43","difficulty":1,"kind":"match","stem":"『국어』 265쪽 낱말 알기예요. 낱말과 뜻을 바르게 이어 보세요.","pairs":[{"l":"신통방통하다","r":"매우 대견하고 칭찬해 줄 만하다."},{"l":"밑창","r":"신발의 바닥 밑에 붙이는 가죽이나 고무 따위의 조각."},{"l":"단짝","r":"서로 뜻이 맞거나 매우 친해 늘 함께 어울리는 친구."}],"mis":"K3-2-u6-X11","explanation":["드라마에 나온 낱말의 뜻을 알아보아요.","뜻을 모르면 국어사전이나 대화 상황에서 찾아요.","낱말을 넣어 문장도 만들어 보아요."],"asset":{"type":"passage","lines":["보기: 신통방통하다 · 밑창 · 단짝","㉮ 서로 뜻이 맞거나 매우 친해 늘 함께 어울리는 친구.","㉯ 신발의 바닥 밑에 붙이는 가죽이나 고무 따위의 조각.","㉰ 매우 대견하고 칭찬해 줄 만하다."],"numbered":false,"title":"낱말 알기 — 『국어』 265쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L05_basic#3','kor',3,2,'u6','L05','tb_g3_2_kor_u6_L05_basic','lesson_basic','K3-2-u6-C43',1,'mc','auto','신비가 마리와 기동이에게 실망한 까닭은 무엇인가요?',ARRAY['K3-2-u6-X11']::text[],false,'{"seq":3,"concept":"K3-2-u6-C43","difficulty":1,"kind":"mc","stem":"신비가 마리와 기동이에게 실망한 까닭은 무엇인가요?","options":[{"t":"친구들과 나누어 먹으려고 과자를 가져왔는데 별로 고마워하지 않는다고 생각해서","correct":true},{"t":"마리와 기동이가 과자를 가져오지 않아서","mis":"K3-2-u6-X11"},{"t":"용용이가 계산기를 빼앗아 가서","mis":"K3-2-u6-X11"},{"t":"아빠가 치킨을 혼자 먹어서","mis":"K3-2-u6-X11"}],"explanation":["신비는 과자를 나누어 주었어요.","그런데 친구들이 별로 고마워하지 않는다고 생각했어요.","그래서 “뭐야? 별로 안 고마운 거야?”라고 했어요."],"asset":{"type":"speech","turns":[{"who":"신비","text":"뭐야? 별로 안 고마운 거야?"},{"who":"기동","text":"인심 썼다. 자! 먼저 먹어."},{"who":"아빠","text":"아빠는 신비가 먹는 것만 봐도 배가 불러요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L05_basic#4','kor',3,2,'u6','L05','tb_g3_2_kor_u6_L05_basic','lesson_basic','K3-2-u6-C17',1,'ox','auto','뜨거운 의자 놀이에서 의자에 앉은 친구는 자기 자신이 아니라 정한 인물이 되어 대답해요.',ARRAY['K3-2-u6-X17']::text[],false,'{"seq":4,"concept":"K3-2-u6-C17","difficulty":1,"kind":"ox","stem":"뜨거운 의자 놀이에서 의자에 앉은 친구는 자기 자신이 아니라 정한 인물이 되어 대답해요.","answer":"O","reason_options":[{"t":"다른 친구들이 그 인물에게 궁금한 점을 묻고, 인물의 마음으로 답해 보는 놀이이기 때문에","correct":true},{"t":"인물에게는 드라마에 나오지 않는 일만 물어야 하기 때문에","mis":"K3-2-u6-X17"}],"mis":"K3-2-u6-X17","explanation":["③ 한 친구가 정한 인물이 되어 의자에 앉아요.","⑤ 의자에 앉은 친구는 그 인물이 되어 대답해요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 교실 앞에 의자 하나를 놓는다.","② 드라마에 나오는 인물 가운데에서 한 명을 정한다.","③ 한 친구가 정한 인물이 되어 의자에 앉는다.","④ 다른 친구들은 그 인물에게 궁금한 점을 묻는다.","⑤ 의자에 앉은 친구는 그 인물이 되어 대답한다."],"numbered":false,"title":"인물에게 묻고 답하기(뜨거운 의자) — 『국어』 266쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L05_basic#5','kor',3,2,'u6','L05','tb_g3_2_kor_u6_L05_basic','lesson_basic','K3-2-u6-C43',2,'mc','auto','용용이가 신비에게 니 맘 내 맘 계산기를 준 까닭은 무엇일까요?',ARRAY['K3-2-u6-X04','K3-2-u6-X10','K3-2-u6-X11']::text[],false,'{"seq":5,"concept":"K3-2-u6-C43","difficulty":2,"kind":"mc","stem":"용용이가 신비에게 니 맘 내 맘 계산기를 준 까닭은 무엇일까요?","options":[{"t":"신비가 다른 친구들의 처지에서 생각해 보게 하려고","correct":true},{"t":"신비의 수학 숙제를 도와주려고","mis":"K3-2-u6-X04"},{"t":"과자값을 계산하려고","mis":"K3-2-u6-X10"},{"t":"신비가 친구들과 놀지 못하게 하려고","mis":"K3-2-u6-X11"}],"explanation":["신비는 친구들 마음을 몰라 서운해했어요.","계산기로 친구들의 마음을 들여다볼 수 있어요.","다른 사람의 처지에서 생각해 보게 하려는 것이에요."],"asset":{"type":"passage","lines":["등장인물 — 신비, 용용이(살아남은 단 하나의 공룡), 아빠, 마리, 기동","(간추림) 신비는 주변 사람들의 행동을 자기중심적으로 생각해","친구들의 마음을 오해했다.","(간추림) 용용이가 마법으로 ‘니 맘 내 맘 계산기’를 주었다.","(간추림) 신비는 계산기로 친구들과 가족의 진심을 깨닫고 반성했다."],"title":"「신통방통 니 맘 내 맘 계산기」 간추린 줄거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L05_basic#6','kor',3,2,'u6','L05','tb_g3_2_kor_u6_L05_basic','lesson_basic','K3-2-u6-C14',2,'mc','auto','아빠는 “아빠는 신비가 먹는 것만 봐도 배가 불러요.”라고 했어요. 이 말에서 아빠가 소중하게 여기는 것은 무엇인가요?',ARRAY['K3-2-u6-X10','K3-2-u6-X15']::text[],false,'{"seq":6,"concept":"K3-2-u6-C14","difficulty":2,"kind":"mc","stem":"아빠는 “아빠는 신비가 먹는 것만 봐도 배가 불러요.”라고 했어요. 이 말에서 아빠가 소중하게 여기는 것은 무엇인가요?","options":[{"t":"딸인 신비와 가족","correct":true},{"t":"배가 부른 것","mis":"K3-2-u6-X10"},{"t":"치킨을 먹지 않는 것","mis":"K3-2-u6-X10"},{"t":"니 맘 내 맘 계산기","mis":"K3-2-u6-X15"}],"explanation":["아빠는 맛있는 것을 신비에게 먼저 주어요.","항상 신비를 먼저 생각하는 말과 행동이에요.","이런 말과 행동에서 가족에 대한 사랑을 알 수 있어요."],"asset":{"type":"speech","turns":[{"who":"신비","text":"뭐야? 별로 안 고마운 거야?"},{"who":"기동","text":"인심 썼다. 자! 먼저 먹어."},{"who":"아빠","text":"아빠는 신비가 먹는 것만 봐도 배가 불러요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L05_basic#7','kor',3,2,'u6','L05','tb_g3_2_kor_u6_L05_basic','lesson_basic','K3-2-u6-C17',2,'mc','auto','뜨거운 의자 놀이에서 마리나 기동이 역할을 맡은 친구에게 할 질문으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X17']::text[],false,'{"seq":7,"concept":"K3-2-u6-C17","difficulty":2,"kind":"mc","stem":"뜨거운 의자 놀이에서 마리나 기동이 역할을 맡은 친구에게 할 질문으로 알맞은 것은 무엇인가요?","options":[{"t":"“평소에 신비를 어떻게 생각하나요?”","correct":true},{"t":"“이 드라마를 만든 방송국 이름은 무엇인가요?”","mis":"K3-2-u6-X17"},{"t":"“드라마를 찍은 날 날씨는 어땠나요?”","mis":"K3-2-u6-X17"},{"t":"“기동이 역할을 한 사람은 몇 살인가요?”","mis":"K3-2-u6-X17"}],"explanation":["인물이 드라마 속에서 답할 수 있는 질문을 해요.","인물의 마음이나 그렇게 한 까닭을 물어요.","드라마 밖의 일은 인물이 답할 수 없어요."],"asset":{"type":"passage","lines":["① 교실 앞에 의자 하나를 놓는다.","② 드라마에 나오는 인물 가운데에서 한 명을 정한다.","③ 한 친구가 정한 인물이 되어 의자에 앉는다.","④ 다른 친구들은 그 인물에게 궁금한 점을 묻는다.","⑤ 의자에 앉은 친구는 그 인물이 되어 대답한다."],"numbered":false,"title":"인물에게 묻고 답하기(뜨거운 의자) — 『국어』 266쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L05_basic#8','kor',3,2,'u6','L05','tb_g3_2_kor_u6_L05_basic','lesson_basic','K3-2-u6-C14',2,'mc','auto','이야기에서 인물들이 소중하게 생각하는 것을 파악하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X15','K3-2-u6-X09']::text[],false,'{"seq":8,"concept":"K3-2-u6-C14","difficulty":2,"kind":"mc","stem":"이야기에서 인물들이 소중하게 생각하는 것을 파악하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"인물이 처한 상황에서 인물이 한 말과 행동을 살펴본다","correct":true},{"t":"이야기 끝에 적힌 교훈 문장을 찾는다","mis":"K3-2-u6-X15"},{"t":"인물이 입은 옷의 색깔을 본다","mis":"K3-2-u6-X09"},{"t":"가장 많이 나온 인물 하나만 본다","mis":"K3-2-u6-X15"}],"explanation":["소중하게 여기는 것은 이야기에 적혀 있지 않아요.","인물이 처한 상황을 먼저 보아요.","그때 한 말과 행동에서 읽어 내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L05_basic#9','kor',3,2,'u6','L05','tb_g3_2_kor_u6_L05_basic','lesson_basic','K3-2-u6-C16',2,'mc','auto','공익 광고 「우리 개는 순한데」에서 강아지를 호랑이로 표현한 까닭은 무엇일까요?',ARRAY['K3-2-u6-X04','K3-2-u6-X16','K3-2-u6-X46']::text[],false,'{"seq":9,"concept":"K3-2-u6-C16","difficulty":2,"kind":"mc","stem":"공익 광고 「우리 개는 순한데」에서 강아지를 호랑이로 표현한 까닭은 무엇일까요?","options":[{"t":"주인에게는 귀엽지만 다른 사람에게는 위협적일 수 있기 때문","correct":true},{"t":"강아지가 정말로 호랑이로 변했기 때문","mis":"K3-2-u6-X04"},{"t":"주인의 말이 언제나 옳다는 것을 보여 주려고","mis":"K3-2-u6-X16"},{"t":"개를 무서워하는 사람의 마음은 생각하지 않아도 되기 때문","mis":"K3-2-u6-X46"}],"explanation":["주인에게는 귀여운 강아지예요.","다른 사람에게는 위협적일 수 있어서 호랑이로 표현했어요.","서로의 처지를 생각해 목줄을 하자는 광고예요."],"asset":{"type":"passage","lines":["[공익 광고] 반려견과 외출할 때 목줄을 착용해야 한다는 공익 광고","광고에서는 강아지를 호랑이로 표현했다."],"title":"공익 광고 「우리 개는 순한데」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L05_basic#10','kor',3,2,'u6','L05','tb_g3_2_kor_u6_L05_basic','lesson_basic','K3-2-u6-C18',3,'essay','teacher','『국어』 267쪽처럼, 신비처럼 다른 사람에 대한 오해가 풀렸던 경험을 쓰세요. 처음에 어떻게 오해했고 어떻게 풀렸는지 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u6-C18","difficulty":3,"kind":"essay","stem":"『국어』 267쪽처럼, 신비처럼 다른 사람에 대한 오해가 풀렸던 경험을 쓰세요. 처음에 어떻게 오해했고 어떻게 풀렸는지 함께 쓰세요.","answer_guide":{"answer":"예: 친구가 내 인사를 받지 않아서 나를 싫어한다고 생각했다. 나중에 물어보니 그날 안경을 두고 와서 내가 잘 안 보였다고 했다. 그 뒤로 서운한 일이 생기면 먼저 물어보게 되었다.","scoring_points":["오해한 일을 썼는가","오해가 풀린 과정을 썼는가","그때의 생각이나 느낌을 썼는가"]},"explanation":["드라마 속 인물과 비슷한 내 경험을 떠올려요.","처음 생각과 알고 난 뒤의 생각을 견주어요.","친구들의 경험을 듣고 내 생각도 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L05_challenge#1','kor',3,2,'u6','L05','tb_g3_2_kor_u6_L05_challenge','lesson_challenge','K3-2-u6-C43',2,'mc','auto','드라마를 보기 전에 『국어』 264쪽 장면을 보고 내용을 예상해요. 신비가 토라진 표정을 짓고 있을 때 예상할 수 있는 내용으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X10','K3-2-u6-X04','K3-2-u6-X09']::text[],false,'{"seq":1,"concept":"K3-2-u6-C43","difficulty":2,"kind":"mc","stem":"드라마를 보기 전에 『국어』 264쪽 장면을 보고 내용을 예상해요. 신비가 토라진 표정을 짓고 있을 때 예상할 수 있는 내용으로 알맞은 것은 무엇인가요?","options":[{"t":"친구들과 다툰 것 같다","correct":true},{"t":"신비가 상을 받아 기뻐하는 것 같다","mis":"K3-2-u6-X10"},{"t":"신비가 공룡을 무서워하는 것 같다","mis":"K3-2-u6-X04"},{"t":"신비의 키가 커진 것 같다","mis":"K3-2-u6-X09"}],"explanation":["토라진 표정은 서운하거나 화가 났을 때 지어요.","표정을 보고 무슨 일이 있었는지 예상해요.","계산기를 받고 다시 기분이 좋아졌을 것 같다고 예상할 수도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L05_challenge#2','kor',3,2,'u6','L05','tb_g3_2_kor_u6_L05_challenge','lesson_challenge','K3-2-u6-C43',2,'blank','auto','드라마에 나온 낱말로 문장을 만들었어요. 빈칸에 알맞은 낱말은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L05_challenge#3','kor',3,2,'u6','L05','tb_g3_2_kor_u6_L05_challenge','lesson_challenge','K3-2-u6-C14',3,'mc','auto','마리와 기동이는 신비를 어떻게 생각하고 있을까요? 까닭과 함께 가장 알맞게 말한 것은 무엇인가요?',ARRAY['K3-2-u6-X46','K3-2-u6-X15','K3-2-u6-X11']::text[],false,'{"seq":3,"concept":"K3-2-u6-C14","difficulty":3,"kind":"mc","stem":"마리와 기동이는 신비를 어떻게 생각하고 있을까요? 까닭과 함께 가장 알맞게 말한 것은 무엇인가요?","options":[{"t":"둘 다 신비를 좋은 친구라고 생각한다 — 둘 다 신비를 배려하는 행동을 했기 때문","correct":true},{"t":"둘 다 신비를 싫어한다 — 과자를 받고 고맙다고 크게 말하지 않았기 때문","mis":"K3-2-u6-X46"},{"t":"알 수 없다 — 드라마에 「좋은 친구」라고 적혀 있지 않기 때문","mis":"K3-2-u6-X15"},{"t":"기동이만 좋은 친구다 — 마리는 신비에게 아무것도 해 주지 않았기 때문","mis":"K3-2-u6-X11"}],"explanation":["기동이는 치킨을 양보했고, 마리는 화장실에서 자리를 양보했어요.","말보다 행동에서 신비를 생각하는 마음이 보여요.","내 마음만 기준으로 보면 친구의 마음을 오해할 수 있어요."],"asset":{"type":"speech","turns":[{"who":"신비","text":"뭐야? 별로 안 고마운 거야?"},{"who":"기동","text":"인심 썼다. 자! 먼저 먹어."},{"who":"아빠","text":"아빠는 신비가 먹는 것만 봐도 배가 불러요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L05_challenge#4','kor',3,2,'u6','L05','tb_g3_2_kor_u6_L05_challenge','lesson_challenge','K3-2-u6-C16',3,'mc','auto','드라마에서 신비의 마음은 어떻게 변했나요?',ARRAY['K3-2-u6-X16','K3-2-u6-X18','K3-2-u6-X15']::text[],false,'{"seq":4,"concept":"K3-2-u6-C16","difficulty":3,"kind":"mc","stem":"드라마에서 신비의 마음은 어떻게 변했나요?","options":[{"t":"처음에는 내 마음만 기준으로 생각해 친구들을 오해했다가, 상대의 처지에서 바라보는 방법을 깨닫고 친구들의 마음을 이해했다","correct":true},{"t":"처음부터 끝까지 친구들이 잘못했다고 생각했다","mis":"K3-2-u6-X16"},{"t":"친구들과 서운했던 일을 덮어 두고 다시는 말하지 않기로 했다","mis":"K3-2-u6-X18"},{"t":"계산기가 없으면 친구의 마음은 절대 알 수 없다고 믿게 되었다","mis":"K3-2-u6-X15"}],"explanation":["신비는 친구들이 고마워하지 않는다고 서운해했어요.","계산기로 친구들과 아빠의 진심을 알게 되었어요.","자기 생각만 하지 않고 다른 사람의 처지에서 배려하는 마음이 생겼어요."],"asset":{"type":"passage","lines":["등장인물 — 신비, 용용이(살아남은 단 하나의 공룡), 아빠, 마리, 기동","(간추림) 신비는 주변 사람들의 행동을 자기중심적으로 생각해","친구들의 마음을 오해했다.","(간추림) 용용이가 마법으로 ‘니 맘 내 맘 계산기’를 주었다.","(간추림) 신비는 계산기로 친구들과 가족의 진심을 깨닫고 반성했다."],"title":"「신통방통 니 맘 내 맘 계산기」 간추린 줄거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L05_challenge#5','kor',3,2,'u6','L05','tb_g3_2_kor_u6_L05_challenge','lesson_challenge','K3-2-u6-C14',3,'error','auto','드라마 속 인물의 말과 행동에 대한 친구들의 생각이에요. 알맞지 않은 생각은 무엇인가요?',ARRAY['K3-2-u6-X15','K3-2-u6-X03']::text[],false,'{"seq":5,"concept":"K3-2-u6-C14","difficulty":3,"kind":"error","stem":"드라마 속 인물의 말과 행동에 대한 친구들의 생각이에요. 알맞지 않은 생각은 무엇인가요?","options":[{"t":"“마리가 화장실에서 신비에게 자리를 양보했지만, 그런 행동으로는 마리의 마음을 알 수 없어.”","correct":true,"mis_target":"K3-2-u6-X15"},{"t":"“기동이가 신비에게 치킨을 양보하는 모습에서 배려심을 느꼈어.”","mis":"K3-2-u6-X15"},{"t":"“신비도 서운해하기 전에 친구들이 잘해 준 일은 없는지 생각했어야 해.”","mis":"K3-2-u6-X03"}],"explanation":["인물이 소중히 여기는 것은 말과 행동에서 읽어 내요.","자리를 양보한 행동에서 친구를 생각하는 마음이 보여요.","인물에 대한 생각은 사람마다 달라도 서로 존중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L05_challenge#6','kor',3,2,'u6','L05','tb_g3_2_kor_u6_L05_challenge','lesson_challenge','K3-2-u6-C14',3,'mc','auto','『국어』 267쪽에서 친구 1은 「신비의 열린 가방을 닫아 주는 마리의 행동」에서 감동을 느꼈어요. 친구 1이 이 행동에서 느낀 것은 무엇인가요?',ARRAY['K3-2-u6-X10','K3-2-u6-X15']::text[],false,'{"seq":6,"concept":"K3-2-u6-C14","difficulty":3,"kind":"mc","stem":"『국어』 267쪽에서 친구 1은 「신비의 열린 가방을 닫아 주는 마리의 행동」에서 감동을 느꼈어요. 친구 1이 이 행동에서 느낀 것은 무엇인가요?","options":[{"t":"친구를 생각하는 마음","correct":true},{"t":"가방을 빨리 닫고 싶은 귀찮은 마음","mis":"K3-2-u6-X10"},{"t":"신비의 물건을 갖고 싶은 마음","mis":"K3-2-u6-X10"},{"t":"마리가 소중히 여기는 것은 드라마에 적혀 있지 않아 알 수 없다","mis":"K3-2-u6-X15"}],"explanation":["열린 가방을 말없이 닫아 주었어요.","친구가 물건을 잃어버리지 않게 챙겨 준 행동이에요.","작은 행동에서도 인물의 마음을 느낄 수 있어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"신비의 열린 가방을 닫아 주는 마리의 행동에서 친구를 생각하는 마음이 잘 느껴졌어."},{"who":"친구 2","text":"신비가 자신을 사랑하는 아빠의 마음을 깨달았을 때 흐른 배경 음악 때문에 감동이 더 잘 느껴졌어."},{"who":"친구 3","text":"신비가 아빠를 위한 이벤트를 하는 장면에서 가족을 사랑하는 마음이 잘 느껴져서 감동받았어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L05_challenge#7','kor',3,2,'u6','L05','tb_g3_2_kor_u6_L05_challenge','lesson_challenge','K3-2-u6-C17',3,'mc','auto','뜨거운 의자 놀이에서 아빠 역할을 맡은 친구에게 할 질문으로, 인물의 마음을 묻는 알맞은 질문은 무엇인가요?',ARRAY['K3-2-u6-X17']::text[],false,'{"seq":7,"concept":"K3-2-u6-C17","difficulty":3,"kind":"mc","stem":"뜨거운 의자 놀이에서 아빠 역할을 맡은 친구에게 할 질문으로, 인물의 마음을 묻는 알맞은 질문은 무엇인가요?","options":[{"t":"“신비에게 서운했던 점은 없나요?”","correct":true},{"t":"“아빠 역할을 한 배우의 이름은 무엇인가요?”","mis":"K3-2-u6-X17"},{"t":"“이 드라마는 몇 년에 만들어졌나요?”","mis":"K3-2-u6-X17"},{"t":"“드라마를 찍은 집은 어디에 있나요?”","mis":"K3-2-u6-X17"}],"explanation":["각 인물의 마음을 묻는 질문을 해요.","서로의 처지를 이해하고 인물이 추구하는 가치를 알아 가요.","「아빠에게 신비는 어떤 사람인가요?」도 좋은 질문이에요."],"asset":{"type":"passage","lines":["① 교실 앞에 의자 하나를 놓는다.","② 드라마에 나오는 인물 가운데에서 한 명을 정한다.","③ 한 친구가 정한 인물이 되어 의자에 앉는다.","④ 다른 친구들은 그 인물에게 궁금한 점을 묻는다.","⑤ 의자에 앉은 친구는 그 인물이 되어 대답한다."],"numbered":false,"title":"인물에게 묻고 답하기(뜨거운 의자) — 『국어』 266쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L05_challenge#8','kor',3,2,'u6','L05','tb_g3_2_kor_u6_L05_challenge','lesson_challenge','K3-2-u6-C16',4,'essay','teacher','공익 광고 「우리 개는 순한데」는 무엇을 소중히 여기자고 말하는지 쓰고, 반려동물을 좋아하는 사람과 좋아하지 않는 사람이 서로 어떻게 하면 좋을지 자신의 생각을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u6-C16","difficulty":4,"kind":"essay","stem":"공익 광고 「우리 개는 순한데」는 무엇을 소중히 여기자고 말하는지 쓰고, 반려동물을 좋아하는 사람과 좋아하지 않는 사람이 서로 어떻게 하면 좋을지 자신의 생각을 쓰세요.","answer_guide":{"answer":"예: 공공질서를 지키기 위해 반려동물과 외출할 때 목줄을 하자는 것을 소중히 여긴다. 반려동물을 좋아하는 사람은 남이 무서워할 수 있으니 목줄을 하고, 좋아하지 않는 사람도 강아지가 놀라지 않게 함부로 만지지 않는다. 서로의 처지를 배려하면 모두 편하게 다닐 수 있다.","scoring_points":["광고가 소중히 여기는 가치를 썼는가","두 처지의 사람이 할 일을 각각 썼는가","서로의 처지를 배려하는 자신의 생각을 썼는가"]},"explanation":["광고에서 내세우는 가치를 생각해요.","한쪽만 옳다고 하지 않고 두 처지를 함께 보아요.","광고 내용에 대한 내 생각을 말해요."],"asset":{"type":"passage","lines":["[공익 광고] 반려견과 외출할 때 목줄을 착용해야 한다는 공익 광고","광고에서는 강아지를 호랑이로 표현했다."],"title":"공익 광고 「우리 개는 순한데」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L05_challenge#9','kor',3,2,'u6','L05','tb_g3_2_kor_u6_L05_challenge','lesson_challenge','K3-2-u6-C17',4,'essay','teacher','「신통방통 니 맘 내 맘 계산기」에 나오는 인물 한 명을 골라, 그 인물에게 할 질문 두 가지를 쓰고 그 인물이 되어 대답을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u6-C17","difficulty":4,"kind":"essay","stem":"「신통방통 니 맘 내 맘 계산기」에 나오는 인물 한 명을 골라, 그 인물에게 할 질문 두 가지를 쓰고 그 인물이 되어 대답을 쓰세요.","answer_guide":{"answer":"예: 인물 — 신비. 질문 1 「친구들에게 서운했던 점이 무엇인가요?」 대답 「과자를 나눠 줬는데 고맙다는 말을 안 해서 서운했어요.」 질문 2 「상대의 처지를 보고 난 뒤에 마음이 어떻게 변했나요?」 대답 「친구들도 나를 배려하고 있었다는 걸 알고 미안해졌어요.」","scoring_points":["인물을 정했는가","인물의 마음이나 까닭을 묻는 질문 두 가지를 썼는가","인물의 처지에서 대답을 썼는가"]},"explanation":["인물이 드라마 속에서 답할 수 있는 질문을 만들어요.","그 인물이 되어 마음을 담아 대답해요.","묻고 답하며 인물이 추구하는 가치를 알게 돼요."],"asset":{"type":"passage","lines":["① 교실 앞에 의자 하나를 놓는다.","② 드라마에 나오는 인물 가운데에서 한 명을 정한다.","③ 한 친구가 정한 인물이 되어 의자에 앉는다.","④ 다른 친구들은 그 인물에게 궁금한 점을 묻는다.","⑤ 의자에 앉은 친구는 그 인물이 되어 대답한다."],"numbered":false,"title":"인물에게 묻고 답하기(뜨거운 의자) — 『국어』 266쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L05_challenge#10','kor',3,2,'u6','L05','tb_g3_2_kor_u6_L05_challenge','lesson_challenge','K3-2-u6-C18',4,'mc','auto','친구가 「두 친구가 나에게 안 들리게 귓속말을 해서 속상했는데, 알고 보니 내 생일 선물을 준비하는 것이었다.」는 경험을 말했어요. 이 경험과 드라마의 공통점으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X16','K3-2-u6-X18','K3-2-u6-X46']::text[],false,'{"seq":10,"concept":"K3-2-u6-C18","difficulty":4,"kind":"mc","stem":"친구가 「두 친구가 나에게 안 들리게 귓속말을 해서 속상했는데, 알고 보니 내 생일 선물을 준비하는 것이었다.」는 경험을 말했어요. 이 경험과 드라마의 공통점으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"상대의 진짜 마음을 모른 채 내 생각만으로 오해했다가 알고 나서 풀렸다","correct":true},{"t":"친구들이 잘못해서 사과를 받았다","mis":"K3-2-u6-X16"},{"t":"속상한 일은 덮어 두는 것이 가장 좋다","mis":"K3-2-u6-X18"},{"t":"귓속말을 하는 친구는 나쁜 친구다","mis":"K3-2-u6-X46"}],"explanation":["신비도 친구들의 진심을 모르고 서운해했어요.","친구 2도 귓속말의 까닭을 모르고 속상해했어요.","상대의 처지와 진심을 알고 나니 오해가 풀렸어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"동생과 싸웠을 때 엄마가 나를 더 혼내셔서 속상했는데, 그날 밤에 침대로 와서 안아 주셔서 오해가 풀렸어."},{"who":"친구 2","text":"두 친구가 나에게 안 들리게 귓속말을 해서 속상했는데, 알고 보니 내 생일 선물을 준비하는 것이어서 오히려 미안했어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L07_basic#1','kor',3,2,'u6','L07','tb_g3_2_kor_u6_L07_basic','lesson_basic','K3-2-u6-C19',1,'mc','auto','드라마를 보고 쓴 네 문장 가운데 의견을 나타낸 문장은 무엇인가요?',ARRAY['K3-2-u6-X19']::text[],false,'{"seq":1,"concept":"K3-2-u6-C19","difficulty":1,"kind":"mc","stem":"드라마를 보고 쓴 네 문장 가운데 의견을 나타낸 문장은 무엇인가요?","options":[{"t":"㉱ 신비처럼 다른 친구들의 마음을 이해해 주어야 합니다.","correct":true},{"t":"㉮ 신비는 친구들에게 과자를 나누어 주었습니다.","mis":"K3-2-u6-X19"},{"t":"㉯ 마리는 신비에게 화장실을 양보해 주었습니다.","mis":"K3-2-u6-X19"},{"t":"㉰ 신비는 니 맘 내 맘 계산기로 친구들의 마음을 들여다보았습니다.","mis":"K3-2-u6-X19"}],"explanation":["㉮·㉯·㉰는 드라마에서 실제로 있었던 일(사실)이에요.","㉱에는 「……해야 합니다」처럼 쓴 사람의 생각이 담겨 있어요.","어떤 일이나 대상에 대한 생각이 의견이에요."],"asset":{"type":"passage","lines":["㉮ 신비는 친구들에게 과자를 나누어 주었습니다.","㉯ 마리는 신비에게 화장실을 양보해 주었습니다.","㉰ 신비는 니 맘 내 맘 계산기로 친구들의 마음을 들여다보았습니다.","㉱ 신비처럼 다른 친구들의 마음을 이해해 주어야 합니다."],"numbered":false,"title":"드라마를 보고 쓴 네 문장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L07_basic#2','kor',3,2,'u6','L07','tb_g3_2_kor_u6_L07_basic','lesson_basic','K3-2-u6-C19',1,'blank','auto','『국어』 268쪽이에요. 빈칸에 알맞은 낱말은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L07_basic#3','kor',3,2,'u6','L07','tb_g3_2_kor_u6_L07_basic','lesson_basic','K3-2-u6-C21',1,'mc','auto','「다른 사람의 마음 이해하기」에서 글쓴이의 의견은 무엇인가요?',ARRAY['K3-2-u6-X21','K3-2-u6-X19']::text[],false,'{"seq":3,"concept":"K3-2-u6-C21","difficulty":1,"kind":"mc","stem":"「다른 사람의 마음 이해하기」에서 글쓴이의 의견은 무엇인가요?","options":[{"t":"다른 사람의 마음을 잘 이해하기 위해서는 그 사람의 처지에서 생각해 보는 연습이 필요하다","correct":true},{"t":"우리 주변에도 상대의 마음을 모른 채 오해해 갈등을 겪는 일이 많다","mis":"K3-2-u6-X21"},{"t":"같은 일을 겪어도 사람마다 느끼는 마음이나 생각이 다를 수 있다","mis":"K3-2-u6-X21"},{"t":"국어 시간에 드라마를 보았다","mis":"K3-2-u6-X19"}],"explanation":["2번 문장 끝에 「필요하다고 생각한다」가 있어요.","1번은 문제 상황, 3번은 그렇게 생각한 이유예요.","드라마를 본 것은 있었던 일이에요."],"asset":{"type":"passage","lines":["(간추림) 국어 시간에 드라마를 보았다. 신비는 친구들이 마음을 몰라주어 서운해했다.","1 신비가 경험한 것처럼 우리 주변에도 상대의 마음을 모른 채","  오해해 상대와 갈등을 겪는 일이 많다.","2 다른 사람의 마음을 잘 이해하기 위해서는 그 사람의 처지에서","  생각해 보는 연습이 필요하다고 생각한다.","3 왜냐하면 같은 일을 겪어도 사람마다 느끼는 마음이나 생각이 다를 수 있기 때문이다.","(간추림) 상대의 마음도 헤아려 주면 갈등이 줄어든다. 다투기 전에 상대의 처지를 생각해 보자."],"numbered":false,"title":"「다른 사람의 마음 이해하기」 — 『국어』 268쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L07_basic#4','kor',3,2,'u6','L07','tb_g3_2_kor_u6_L07_basic','lesson_basic','K3-2-u6-C20',1,'ox','auto','의견을 제시하는 글을 쓸 때에는 주제나 문제 상황에 대한 자신의 의견과 그렇게 생각한 이유를 써야 해요.',ARRAY['K3-2-u6-X20']::text[],false,'{"seq":4,"concept":"K3-2-u6-C20","difficulty":1,"kind":"ox","stem":"의견을 제시하는 글을 쓸 때에는 주제나 문제 상황에 대한 자신의 의견과 그렇게 생각한 이유를 써야 해요.","answer":"O","reason_options":[{"t":"이유가 있어야 읽는 사람이 왜 그런 의견을 냈는지 알고 고개를 끄덕일 수 있기 때문에","correct":true},{"t":"의견만 분명하면 이유는 쓰지 않아도 되기 때문에","mis":"K3-2-u6-X20"}],"mis":"K3-2-u6-X20","explanation":["『국어』 269쪽에서 정리한 내용이에요.","의견만 있으면 읽는 사람이 「왜?」 하고 묻게 돼요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L07_basic#5','kor',3,2,'u6','L07','tb_g3_2_kor_u6_L07_basic','lesson_basic','K3-2-u6-C20',2,'match','auto','『국어』 269쪽 3번이에요. 「다른 사람의 마음 이해하기」의 문장과 의견을 제시하는 글을 쓰는 방법을 바르게 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u6-C20","difficulty":2,"kind":"match","stem":"『국어』 269쪽 3번이에요. 「다른 사람의 마음 이해하기」의 문장과 의견을 제시하는 글을 쓰는 방법을 바르게 이어 보세요.","pairs":[{"l":"1 우리 주변에도 상대의 마음을 모른 채 오해해 갈등을 겪는 일이 많다.","r":"문제 상황을 자세히 쓴다."},{"l":"2 그 사람의 처지에서 생각해 보는 연습이 필요하다고 생각한다.","r":"자신의 의견을 제시한다."},{"l":"3 왜냐하면 같은 일을 겪어도 사람마다 마음이나 생각이 다를 수 있기 때문이다.","r":"그렇게 생각한 이유를 쓴다."}],"mis":"K3-2-u6-X21","explanation":["무엇이 문제인지 먼저 써요.","「……라고 생각한다」로 의견을 내요.","「왜냐하면 ……때문이다」로 이유를 써요."],"asset":{"type":"passage","lines":["(간추림) 국어 시간에 드라마를 보았다. 신비는 친구들이 마음을 몰라주어 서운해했다.","1 신비가 경험한 것처럼 우리 주변에도 상대의 마음을 모른 채","  오해해 상대와 갈등을 겪는 일이 많다.","2 다른 사람의 마음을 잘 이해하기 위해서는 그 사람의 처지에서","  생각해 보는 연습이 필요하다고 생각한다.","3 왜냐하면 같은 일을 겪어도 사람마다 느끼는 마음이나 생각이 다를 수 있기 때문이다.","(간추림) 상대의 마음도 헤아려 주면 갈등이 줄어든다. 다투기 전에 상대의 처지를 생각해 보자."],"numbered":false,"title":"「다른 사람의 마음 이해하기」 — 『국어』 268쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L07_basic#6','kor',3,2,'u6','L07','tb_g3_2_kor_u6_L07_basic','lesson_basic','K3-2-u6-C21',2,'mc','auto','「건강하고 행복한 급식 시간」의 문제 상황은 무엇인가요?',ARRAY['K3-2-u6-X21','K3-2-u6-X19']::text[],false,'{"seq":6,"concept":"K3-2-u6-C21","difficulty":2,"kind":"mc","stem":"「건강하고 행복한 급식 시간」의 문제 상황은 무엇인가요?","options":[{"t":"급식 시간에 편식을 하는 친구들이 있다","correct":true},{"t":"음식을 골고루 먹어야 한다","mis":"K3-2-u6-X21"},{"t":"다양한 음식을 즐길 수 있다","mis":"K3-2-u6-X21"},{"t":"김치볶음밥은 맛있다","mis":"K3-2-u6-X19"}],"explanation":["글의 첫 문장이 문제 상황이에요.","「골고루 먹어야 한다」는 의견, 「즐길 수 있다」는 이유예요.","문제 상황 → 의견 → 이유 차례로 찾아요."],"asset":{"type":"passage","lines":["급식 시간에 편식을 하는 친구들이 종종 있습니다.","하지만 저는 음식을 골고루 먹어야 한다고 생각합니다.","첫째, 음식을 골고루 먹어야 우리 몸에 필요한 여러 영양소를 얻을 수 있습니다.","(간추림) 근육에는 고기·생선·콩, 힘에는 곡물, 몸의 조절에는 과일·채소.","둘째, 자신이 경험해 보지 못한 다양한 음식을 즐길 수 있습니다.","(간추림) 김치를 싫어했는데 김치볶음밥을 먹은 뒤 김치를 좋아하게 되었다.","음식을 골고루 먹으면서 건강하고 행복한 급식 시간을 만들어 봅시다."],"title":"「건강하고 행복한 급식 시간」 — 『국어』 270쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L07_basic#7','kor',3,2,'u6','L07','tb_g3_2_kor_u6_L07_basic','lesson_basic','K3-2-u6-C23',2,'blank','auto','『국어』 271쪽에서 의견과 이유가 적절한지 알아보는 방법을 정리했어요. ㉠에 알맞은 낱말은 무엇인가요?',ARRAY['K3-2-u6-X25','K3-2-u6-X22']::text[],false,'{"seq":7,"concept":"K3-2-u6-C23","difficulty":2,"kind":"blank","stem":"『국어』 271쪽에서 의견과 이유가 적절한지 알아보는 방법을 정리했어요. ㉠에 알맞은 낱말은 무엇인가요?","options":[{"t":"뒷받침","correct":true},{"t":"다양","mis":"K3-2-u6-X25"},{"t":"도움","mis":"K3-2-u6-X22"}],"explanation":["의견을 받쳐 주는 이유여야 해요.","㉠ 뒷받침 · ㉡ 다양 · ㉢ 도움이에요.","네 가지 방법으로 의견과 이유를 재어 보아요."],"asset":{"type":"passage","lines":["● 주제나 문제 상황에 어울리는 의견을 내야 합니다.","● 의견을 (  ㉠  )하는 적절한 이유를 들어야 합니다.","● (  ㉡  )한 이유를 중복되지 않게 제시해야 합니다.","● 의견은 문제 해결에 (  ㉢  )이/가 되는 것이어야 합니다.","보기: 다양 · 도움 · 뒷받침"],"title":"의견과 이유가 적절한지 알아보는 방법 — 『국어』 271쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L07_basic#8','kor',3,2,'u6','L07','tb_g3_2_kor_u6_L07_basic','lesson_basic','K3-2-u6-C25',2,'mc','auto','『국어』 272쪽 5번 대화를 살펴보고 찾은 문제 상황으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X21','K3-2-u6-X26']::text[],false,'{"seq":8,"concept":"K3-2-u6-C25","difficulty":2,"kind":"mc","stem":"『국어』 272쪽 5번 대화를 살펴보고 찾은 문제 상황으로 알맞은 것은 무엇인가요?","options":[{"t":"운동량이 부족해서 체력이 떨어지는 학생이 많다","correct":true},{"t":"아침 시간에 친구들과 줄넘기를 하자","mis":"K3-2-u6-X21"},{"t":"줄넘기는 친구들과 함께 하면 더 재미있다","mis":"K3-2-u6-X21"},{"t":"친구들이 좋아할 고운 말을 먼저 고른다","mis":"K3-2-u6-X26"}],"explanation":["의견을 제시하는 글은 문제 상황을 찾는 데서 시작해요.","대화에서 「체력이 떨어지는 학생이 많대.」가 문제예요.","줄넘기를 하자는 것은 그 문제를 풀려는 의견이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"요즘 운동량이 부족해서 체력이 떨어지는 학생이 많대."},{"who":"친구 2","text":"그럼 체력을 기르려면 어떻게 해야 할까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L07_basic#9','kor',3,2,'u6','L07','tb_g3_2_kor_u6_L07_basic','lesson_basic','K3-2-u6-C19',2,'mc','auto','다음 가운데 의견을 제시할 때 쓰는 표현이 들어간 문장은 무엇인가요?',ARRAY['K3-2-u6-X19']::text[],false,'{"seq":9,"concept":"K3-2-u6-C19","difficulty":2,"kind":"mc","stem":"다음 가운데 의견을 제시할 때 쓰는 표현이 들어간 문장은 무엇인가요?","options":[{"t":"아침 시간에 친구들과 함께 줄넘기를 하면 좋겠다.","correct":true},{"t":"어제 친구들과 줄넘기를 했다.","mis":"K3-2-u6-X19"},{"t":"줄넘기는 줄을 넘는 운동이다.","mis":"K3-2-u6-X19"},{"t":"우리 반에는 줄넘기가 열 개 있다.","mis":"K3-2-u6-X19"}],"explanation":["의견에는 「……라고 생각한다」, 「……하자」를 써요.","「……면 좋겠다」, 「……해야 한다」도 의견을 나타내요.","나머지는 있었던 일이나 사실이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L07_basic#10','kor',3,2,'u6','L07','tb_g3_2_kor_u6_L07_basic','lesson_basic','K3-2-u6-C21',3,'sa','auto','「건강하고 행복한 급식 시간」의 첫째 이유예요. 음식을 골고루 먹어야 우리 몸에 필요한 여러 무엇을 얻을 수 있다고 했나요? 한 낱말로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u6-C21","difficulty":3,"kind":"sa","stem":"「건강하고 행복한 급식 시간」의 첫째 이유예요. 음식을 골고루 먹어야 우리 몸에 필요한 여러 무엇을 얻을 수 있다고 했나요? 한 낱말로 쓰세요.","answer":["영양소","여러 영양소"],"explanation":["첫째 이유 문장을 다시 읽어요.","「여러 영양소를 얻을 수 있습니다.」라고 했어요.","편식하면 영양소를 골고루 얻지 못할 수 있어요."],"asset":{"type":"passage","lines":["급식 시간에 편식을 하는 친구들이 종종 있습니다.","하지만 저는 음식을 골고루 먹어야 한다고 생각합니다.","첫째, 음식을 골고루 먹어야 우리 몸에 필요한 여러 영양소를 얻을 수 있습니다.","(간추림) 근육에는 고기·생선·콩, 힘에는 곡물, 몸의 조절에는 과일·채소.","둘째, 자신이 경험해 보지 못한 다양한 음식을 즐길 수 있습니다.","(간추림) 김치를 싫어했는데 김치볶음밥을 먹은 뒤 김치를 좋아하게 되었다.","음식을 골고루 먹으면서 건강하고 행복한 급식 시간을 만들어 봅시다."],"title":"「건강하고 행복한 급식 시간」 — 『국어』 270쪽"},"mis":"K3-2-u6-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L07_challenge#1','kor',3,2,'u6','L07','tb_g3_2_kor_u6_L07_challenge','lesson_challenge','K3-2-u6-C22',2,'mc','auto','「음식을 골고루 먹어야 한다」는 의견을 뒷받침하는 적절한 이유는 무엇인가요?',ARRAY['K3-2-u6-X22','K3-2-u6-X23','K3-2-u6-X25']::text[],false,'{"seq":1,"concept":"K3-2-u6-C22","difficulty":2,"kind":"mc","stem":"「음식을 골고루 먹어야 한다」는 의견을 뒷받침하는 적절한 이유는 무엇인가요?","options":[{"t":"자신이 경험해 보지 못한 다양한 음식을 즐길 수 있다","correct":true},{"t":"급식실이 학교에서 가장 넓다","mis":"K3-2-u6-X22"},{"t":"나는 우리 반에서 반찬을 가장 빨리 먹는다","mis":"K3-2-u6-X23"},{"t":"골고루 먹으면 음식을 골고루 먹게 된다","mis":"K3-2-u6-X25"}],"explanation":["이유는 의견과 이어져 의견을 받쳐 주어야 해요.","나만 잘한다는 것이나 같은 말 되풀이는 이유가 되지 못해요.","글쓴이는 김치볶음밥 경험으로 이 이유를 뒷받침했어요."],"asset":{"type":"passage","lines":["급식 시간에 편식을 하는 친구들이 종종 있습니다.","하지만 저는 음식을 골고루 먹어야 한다고 생각합니다.","첫째, 음식을 골고루 먹어야 우리 몸에 필요한 여러 영양소를 얻을 수 있습니다.","(간추림) 근육에는 고기·생선·콩, 힘에는 곡물, 몸의 조절에는 과일·채소.","둘째, 자신이 경험해 보지 못한 다양한 음식을 즐길 수 있습니다.","(간추림) 김치를 싫어했는데 김치볶음밥을 먹은 뒤 김치를 좋아하게 되었다.","음식을 골고루 먹으면서 건강하고 행복한 급식 시간을 만들어 봅시다."],"title":"「건강하고 행복한 급식 시간」 — 『국어』 270쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L07_challenge#2','kor',3,2,'u6','L07','tb_g3_2_kor_u6_L07_challenge','lesson_challenge','K3-2-u6-C23',2,'mc','auto','『국어』 271쪽 (3)이에요. 「건강하고 행복한 급식 시간」의 의견과 이유가 적절한지 바르게 말한 것은 무엇인가요?',ARRAY['K3-2-u6-X24','K3-2-u6-X22','K3-2-u6-X27']::text[],false,'{"seq":2,"concept":"K3-2-u6-C23","difficulty":2,"kind":"mc","stem":"『국어』 271쪽 (3)이에요. 「건강하고 행복한 급식 시간」의 의견과 이유가 적절한지 바르게 말한 것은 무엇인가요?","options":[{"t":"적절하다 — 편식이라는 문제 상황에 어울리는 의견이고, 겹치지 않는 두 이유가 의견을 뒷받침하기 때문","correct":true},{"t":"적절하지 않다 — 김치를 싫어하는 사람도 있으니 정답 의견이 아니기 때문","mis":"K3-2-u6-X24"},{"t":"적절하지 않다 — 이유가 의견과 상관없기 때문","mis":"K3-2-u6-X22"},{"t":"적절하다 — 글이 길고 어려운 낱말이 많기 때문","mis":"K3-2-u6-X27"}],"explanation":["편식 문제에 골고루 먹자는 의견이 어울려요.","영양소와 다양한 음식이라는 두 이유는 겹치지 않아요.","두 이유 모두 건강하고 행복한 급식이라는 문제 해결에 도움이 돼요."],"asset":{"type":"passage","lines":["급식 시간에 편식을 하는 친구들이 종종 있습니다.","하지만 저는 음식을 골고루 먹어야 한다고 생각합니다.","첫째, 음식을 골고루 먹어야 우리 몸에 필요한 여러 영양소를 얻을 수 있습니다.","(간추림) 근육에는 고기·생선·콩, 힘에는 곡물, 몸의 조절에는 과일·채소.","둘째, 자신이 경험해 보지 못한 다양한 음식을 즐길 수 있습니다.","(간추림) 김치를 싫어했는데 김치볶음밥을 먹은 뒤 김치를 좋아하게 되었다.","음식을 골고루 먹으면서 건강하고 행복한 급식 시간을 만들어 봅시다."],"title":"「건강하고 행복한 급식 시간」 — 『국어』 270쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L07_challenge#3','kor',3,2,'u6','L07','tb_g3_2_kor_u6_L07_challenge','lesson_challenge','K3-2-u6-C20',3,'mc','auto','『국어』 272쪽 5번 (2)예요. 내 의견이 「아침 시간에 친구들과 함께 줄넘기를 하면 좋겠다.」일 때 그렇게 생각한 이유 두 가지로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X25','K3-2-u6-X23','K3-2-u6-X21']::text[],false,'{"seq":3,"concept":"K3-2-u6-C20","difficulty":3,"kind":"mc","stem":"『국어』 272쪽 5번 (2)예요. 내 의견이 「아침 시간에 친구들과 함께 줄넘기를 하면 좋겠다.」일 때 그렇게 생각한 이유 두 가지로 알맞은 것은 무엇인가요?","options":[{"t":"줄넘기를 하면 체력을 기르는 데 도움이 된다 · 친구들과 함께 하면 혼자 할 때보다 더 재미있다","correct":true},{"t":"줄넘기를 하면 체력을 기르는 데 도움이 된다 · 줄넘기를 하면 체력이 좋아진다","mis":"K3-2-u6-X25"},{"t":"내가 줄넘기를 가장 잘한다 · 나는 줄넘기를 좋아한다","mis":"K3-2-u6-X23"},{"t":"운동량이 부족한 학생이 많다 · 체력이 떨어지는 학생이 많다","mis":"K3-2-u6-X21"}],"explanation":["두 이유는 서로 겹치지 않아야 해요.","나만 잘한다는 것은 의견을 받쳐 주지 못해요.","운동량이 부족하다는 것은 이유가 아니라 문제 상황이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"요즘 운동량이 부족해서 체력이 떨어지는 학생이 많대."},{"who":"친구 2","text":"그럼 체력을 기르려면 어떻게 해야 할까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L07_challenge#4','kor',3,2,'u6','L07','tb_g3_2_kor_u6_L07_challenge','lesson_challenge','K3-2-u6-C23',3,'error','auto','『국어』 273쪽 스스로 확인하기를 하며 친구들이 한 말이에요. 알맞지 않은 말은 무엇인가요?',ARRAY['K3-2-u6-X25','K3-2-u6-X44','K3-2-u6-X22']::text[],false,'{"seq":4,"concept":"K3-2-u6-C23","difficulty":3,"kind":"error","stem":"『국어』 273쪽 스스로 확인하기를 하며 친구들이 한 말이에요. 알맞지 않은 말은 무엇인가요?","options":[{"t":"“이유를 겹치게 여러 번 쓰면 의견이 더 튼튼해져.”","correct":true,"mis_target":"K3-2-u6-X25"},{"t":"“내 의견이 문제 상황에 어울리는지 봐야 해.”","mis":"K3-2-u6-X44"},{"t":"“내 의견이 문제 해결에 도움이 되는지 봐야 해.”","mis":"K3-2-u6-X22"}],"explanation":["다양한 이유를 중복되지 않게 제시해야 해요.","같은 이유를 말만 바꾸어 되풀이하면 이유가 늘지 않아요.","나머지 두 말은 점검표에 있는 내용이에요."],"asset":{"type":"passage","lines":["주제나 문제 상황에 어울리는 의견이었나요?  ○○○","의견과 이유가 관련 있나요?  ○○○","다양한 이유를 중복되지 않게 제시했나요?  ○○○","의견은 문제 해결에 도움이 되었나요?  ○○○","(매우 잘함 ●●● · 잘함 ●● · 보통임 ●)"],"title":"적절한 이유를 들어 의견을 제시했는지 스스로 확인하기 — 『국어』 273쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L07_challenge#5','kor',3,2,'u6','L07','tb_g3_2_kor_u6_L07_challenge','lesson_challenge','K3-2-u6-C22',3,'mc','auto','의견이 적절한지 따져 보아야 하는 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X24','K3-2-u6-X44','K3-2-u6-X27']::text[],false,'{"seq":5,"concept":"K3-2-u6-C22","difficulty":3,"kind":"mc","stem":"의견이 적절한지 따져 보아야 하는 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"문제 상황에 맞지 않는 의견대로 하면 문제가 풀리지 않거나 잘못된 결과가 생길 수 있어서","correct":true},{"t":"먼저 말한 사람의 의견이 늘 옳아서","mis":"K3-2-u6-X24"},{"t":"이유가 그럴듯하면 의견은 무엇이든 괜찮아서","mis":"K3-2-u6-X44"},{"t":"의견은 길게 쓸수록 좋아서","mis":"K3-2-u6-X27"}],"explanation":["의견이 적절한지 따지지 않고 행동하면","문제가 그대로 남거나 오히려 나빠질 수 있어요.","그래서 의견과 이유가 적절한지 꼭 살펴봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L07_challenge#6','kor',3,2,'u6','L07','tb_g3_2_kor_u6_L07_challenge','lesson_challenge','K3-2-u6-C19',3,'blank','auto','『국어』 273쪽이에요. 의견을 제시할 때 쓸 수 있는 표현을 모았어요. 빈칸에 알맞은 것은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L07_challenge#7','kor',3,2,'u6','L07','tb_g3_2_kor_u6_L07_challenge','lesson_challenge','K3-2-u6-C21',3,'mc','auto','「다른 사람의 마음 이해하기」에서 글쓴이가 그렇게 생각한 이유 두 가지를 바르게 고른 것은 무엇인가요?',ARRAY['K3-2-u6-X19','K3-2-u6-X21','K3-2-u6-X46']::text[],false,'{"seq":7,"concept":"K3-2-u6-C21","difficulty":3,"kind":"mc","stem":"「다른 사람의 마음 이해하기」에서 글쓴이가 그렇게 생각한 이유 두 가지를 바르게 고른 것은 무엇인가요?","options":[{"t":"같은 일을 겪어도 사람마다 마음이나 생각이 다를 수 있다 · 상대의 마음도 헤아려 주면 갈등이 줄어든다","correct":true},{"t":"신비가 서운해했다 · 국어 시간에 드라마를 보았다","mis":"K3-2-u6-X19"},{"t":"처지에서 생각해 보는 연습이 필요하다 · 오해로 갈등을 겪는 일이 많다","mis":"K3-2-u6-X21"},{"t":"상대의 마음은 몰라도 된다 · 내 마음이 기준이다","mis":"K3-2-u6-X46"}],"explanation":["「왜냐하면 …… 때문이다」와 그 뒤 문장을 보아요.","처지에서 생각하자는 것은 의견, 갈등이 많다는 것은 문제 상황이에요.","내 마음만 기준으로 삼지 말자는 것이 글의 생각이에요."],"asset":{"type":"passage","lines":["(간추림) 국어 시간에 드라마를 보았다. 신비는 친구들이 마음을 몰라주어 서운해했다.","1 신비가 경험한 것처럼 우리 주변에도 상대의 마음을 모른 채","  오해해 상대와 갈등을 겪는 일이 많다.","2 다른 사람의 마음을 잘 이해하기 위해서는 그 사람의 처지에서","  생각해 보는 연습이 필요하다고 생각한다.","3 왜냐하면 같은 일을 겪어도 사람마다 느끼는 마음이나 생각이 다를 수 있기 때문이다.","(간추림) 상대의 마음도 헤아려 주면 갈등이 줄어든다. 다투기 전에 상대의 처지를 생각해 보자."],"numbered":false,"title":"「다른 사람의 마음 이해하기」 — 『국어』 268쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L07_challenge#8','kor',3,2,'u6','L07','tb_g3_2_kor_u6_L07_challenge','lesson_challenge','K3-2-u6-C20',4,'essay','teacher','『국어』 272~273쪽 5번처럼, 「운동량이 부족해서 체력이 떨어지는 학생이 많다.」는 문제 상황에 대해 제목·의견·이유 두 가지가 드러나게 의견을 제시하는 글을 쓰세요. (줄넘기 말고 다른 의견으로 써도 좋아요.)','{}'::text[],false,'{"seq":8,"concept":"K3-2-u6-C20","difficulty":4,"kind":"essay","stem":"『국어』 272~273쪽 5번처럼, 「운동량이 부족해서 체력이 떨어지는 학생이 많다.」는 문제 상황에 대해 제목·의견·이유 두 가지가 드러나게 의견을 제시하는 글을 쓰세요. (줄넘기 말고 다른 의견으로 써도 좋아요.)","answer_guide":{"answer":"예: 제목 — 쉬는 시간에 운동장 한 바퀴 걷기를 하자. 요즘 운동량이 부족해서 체력이 떨어지는 학생이 많다. 그래서 쉬는 시간마다 운동장을 한 바퀴씩 걸으면 좋겠다. 걷기는 누구나 쉽게 할 수 있어 꾸준히 하면 체력을 기르는 데 도움이 된다. 또 바깥 공기를 마시면 다음 시간에 머리가 맑아지기 때문이다.","scoring_points":["제목을 썼는가","문제 상황에 어울리는 의견을 「……하자/……면 좋겠다」로 썼는가","의견을 뒷받침하는 겹치지 않는 이유 두 가지를 썼는가"]},"explanation":["문제 상황 → 의견 → 이유 차례로 써요.","의견은 문제를 푸는 데 도움이 되어야 해요.","이유는 겹치지 않게 두 가지 써요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"요즘 운동량이 부족해서 체력이 떨어지는 학생이 많대."},{"who":"친구 2","text":"그럼 체력을 기르려면 어떻게 해야 할까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L07_challenge#9','kor',3,2,'u6','L07','tb_g3_2_kor_u6_L07_challenge','lesson_challenge','K3-2-u6-C23',4,'essay','teacher','『국어』 271쪽 (2)의 네 가지 방법으로 「건강하고 행복한 급식 시간」을 재어 보고, 의견과 이유가 적절한지 까닭을 들어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u6-C23","difficulty":4,"kind":"essay","stem":"『국어』 271쪽 (2)의 네 가지 방법으로 「건강하고 행복한 급식 시간」을 재어 보고, 의견과 이유가 적절한지 까닭을 들어 쓰세요.","answer_guide":{"answer":"예: 편식하는 친구들이 있다는 문제 상황에 음식을 골고루 먹자는 의견이 어울린다. 영양소를 얻을 수 있다는 이유와 다양한 음식을 즐길 수 있다는 이유가 의견을 뒷받침하고 서로 겹치지 않는다. 골고루 먹으면 건강하고 즐거운 급식 시간이 되니 문제 해결에도 도움이 된다. 그래서 적절하다.","scoring_points":["문제 상황과 의견이 어울리는지 썼는가","이유가 의견을 뒷받침하고 겹치지 않는지 썼는가","문제 해결에 도움이 되는지 판단해 썼는가"]},"explanation":["네 가지 방법을 하나씩 대어 보아요.","판단에는 까닭을 붙여요.","이 방법은 내가 글을 쓸 때에도 써요."],"asset":{"type":"passage","lines":["급식 시간에 편식을 하는 친구들이 종종 있습니다.","하지만 저는 음식을 골고루 먹어야 한다고 생각합니다.","첫째, 음식을 골고루 먹어야 우리 몸에 필요한 여러 영양소를 얻을 수 있습니다.","(간추림) 근육에는 고기·생선·콩, 힘에는 곡물, 몸의 조절에는 과일·채소.","둘째, 자신이 경험해 보지 못한 다양한 음식을 즐길 수 있습니다.","(간추림) 김치를 싫어했는데 김치볶음밥을 먹은 뒤 김치를 좋아하게 되었다.","음식을 골고루 먹으면서 건강하고 행복한 급식 시간을 만들어 봅시다."],"title":"「건강하고 행복한 급식 시간」 — 『국어』 270쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L07_challenge#10','kor',3,2,'u6','L07','tb_g3_2_kor_u6_L07_challenge','lesson_challenge','K3-2-u6-C25',4,'mc','auto','의견을 제시하는 글을 쓰기 전 계획하기 단계에서 생각할 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X26','K3-2-u6-X27','K3-2-u6-X24']::text[],false,'{"seq":10,"concept":"K3-2-u6-C25","difficulty":4,"kind":"mc","stem":"의견을 제시하는 글을 쓰기 전 계획하기 단계에서 생각할 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"이 글을 쓰는 목적, 글을 읽을 사람, 글의 주제와 분량","correct":true},{"t":"친구가 좋아할 고운 말을 먼저 고르는 것","mis":"K3-2-u6-X26"},{"t":"글씨를 예쁘게 쓰는 방법","mis":"K3-2-u6-X27"},{"t":"하나뿐인 정답 의견을 찾는 것","mis":"K3-2-u6-X24"}],"explanation":["계획하기에서는 왜 쓰는지, 누가 읽을지 생각해요.","주제가 무엇인지, 어떤 형태로 얼마나 쓸지도 정해요.","모든 과정은 문제 상황을 해결하려는 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L09_basic#1','kor',3,2,'u6','L09','tb_g3_2_kor_u6_L09_basic','lesson_basic','K3-2-u6-C26',1,'blank','auto','『국어』 274쪽 1번이에요. ㉠에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u6-X27']::text[],false,'{"seq":1,"concept":"K3-2-u6-C26","difficulty":1,"kind":"blank","stem":"『국어』 274쪽 1번이에요. ㉠에 알맞은 말은 무엇인가요?","options":[{"t":"문제 상황","correct":true},{"t":"글의 길이","mis":"K3-2-u6-X27"},{"t":"글씨 모양","mis":"K3-2-u6-X27"}],"explanation":["주제나 문제 상황에 어울리는 의견을 썼는지 확인해요.","㉠ 문제 상황 · ㉡ 적절 · ㉢ 문제 해결이에요.","글의 길이나 글씨 모양은 고쳐 쓸 때 볼 것이 아니에요."],"asset":{"type":"passage","lines":["● 주제나 (    ㉠    )에 어울리는 의견을 썼는지 확인한다.","● 의견을 뒷받침하는 (    ㉡    )한 이유를 썼는지 확인한다.","● 의견과 그 이유가 (    ㉢    )에 도움이 되는지 살펴본다.","보기: 적절 · 문제 해결 · 문제 상황","※ 글의 내용에 어색한 부분, 띄어쓰기나 맞춤법이 틀린 부분도 살펴본다."],"title":"의견을 제시하는 글을 고쳐 쓰는 방법 — 『국어』 274쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L09_basic#2','kor',3,2,'u6','L09','tb_g3_2_kor_u6_L09_basic','lesson_basic','K3-2-u6-C26',1,'mc','auto','의견을 제시하는 글을 고쳐 쓸 때 살펴볼 것은 무엇인가요?',ARRAY['K3-2-u6-X27','K3-2-u6-X26']::text[],false,'{"seq":2,"concept":"K3-2-u6-C26","difficulty":1,"kind":"mc","stem":"의견을 제시하는 글을 고쳐 쓸 때 살펴볼 것은 무엇인가요?","options":[{"t":"띄어쓰기나 맞춤법이 틀린 부분은 없는지","correct":true},{"t":"글이 몇 줄인지","mis":"K3-2-u6-X27"},{"t":"글씨가 예쁜지","mis":"K3-2-u6-X27"},{"t":"어려운 낱말을 많이 썼는지","mis":"K3-2-u6-X26"}],"explanation":["의견과 이유뿐 아니라 내용에 어색한 부분도 보아요.","띄어쓰기나 맞춤법이 틀린 부분도 살펴봐요.","줄 수나 글씨 모양은 내용과 상관없어요."],"asset":{"type":"passage","lines":["● 주제나 (    ㉠    )에 어울리는 의견을 썼는지 확인한다.","● 의견을 뒷받침하는 (    ㉡    )한 이유를 썼는지 확인한다.","● 의견과 그 이유가 (    ㉢    )에 도움이 되는지 살펴본다.","보기: 적절 · 문제 해결 · 문제 상황","※ 글의 내용에 어색한 부분, 띄어쓰기나 맞춤법이 틀린 부분도 살펴본다."],"title":"의견을 제시하는 글을 고쳐 쓰는 방법 — 『국어』 274쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L09_basic#3','kor',3,2,'u6','L09','tb_g3_2_kor_u6_L09_basic','lesson_basic','K3-2-u6-C27',1,'mc','auto','「체력을 기르기 위해 달리기를 하자」에서 어색한 부분은 몇 번 줄인가요?',ARRAY['K3-2-u6-X21','K3-2-u6-X22']::text[],false,'{"seq":3,"concept":"K3-2-u6-C27","difficulty":1,"kind":"mc","stem":"「체력을 기르기 위해 달리기를 하자」에서 어색한 부분은 몇 번 줄인가요?","options":[{"t":"5번 줄","correct":true},{"t":"1번 줄","mis":"K3-2-u6-X21"},{"t":"3번 줄","mis":"K3-2-u6-X22"},{"t":"7번 줄","mis":"K3-2-u6-X21"}],"explanation":["5번 줄은 「내가 달리기를 가장 잘하기 때문」이라고 했어요.","내가 잘한다는 것은 함께 달리기를 하자는 의견을 받쳐 주지 못해요.","1번은 문제 상황, 3번은 알맞은 이유, 7번은 맺음이에요."],"asset":{"type":"passage","lines":["제목: 체력을 기르기 위해 달리기를 하자","1 요즘 운동량이 부족해서 체력이 약한 어린이가 많다.","2 그래서 체력을 기르기 위해 점심시간에 함께 달리기를 하면 좋겠다.","3 첫째, 친구들과 함께 달리면 운동 효과가 더 좋아지기 때문이다.","4 (간추림) 여럿이 같이 달리면 힘이 나서 더 열심히 달릴 수 있다.","5 둘째, 내가 우리 반에서 달리기를 가장 잘하기 때문이다.","6 (간추림) 기록을 재면 내가 가장 빠르기 때문에 달리기는 항상 자신이 있다.","7 그래서 우리 반 친구들이 다 함께 달리기를 하며 체력을 길렀으면 좋겠다."],"numbered":false,"title":"고쳐 쓸 글 — 『국어』 274쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L09_basic#4','kor',3,2,'u6','L09','tb_g3_2_kor_u6_L09_basic','lesson_basic','K3-2-u6-C29',1,'ox','auto','친구 글의 고쳐야 할 부분을 말할 때에는 비난하거나 무시하지 말고, 고쳐 쓰면 좋을 부분과 그렇게 생각한 이유만 간단하게 말해요.',ARRAY['K3-2-u6-X30']::text[],false,'{"seq":4,"concept":"K3-2-u6-C29","difficulty":1,"kind":"ox","stem":"친구 글의 고쳐야 할 부분을 말할 때에는 비난하거나 무시하지 말고, 고쳐 쓰면 좋을 부분과 그렇게 생각한 이유만 간단하게 말해요.","answer":"O","reason_options":[{"t":"친구가 무엇을 왜 고치면 좋을지 알아야 글을 더 좋게 고칠 수 있기 때문에","correct":true},{"t":"흠을 많이 찾아 줄수록 친구에게 도움이 되기 때문에","mis":"K3-2-u6-X30"}],"mis":"K3-2-u6-X30","explanation":["고쳐 쓸 점은 점검표를 바탕으로 분명하게 말해요.","비난이나 무시는 도움이 되지 않아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L09_basic#5','kor',3,2,'u6','L09','tb_g3_2_kor_u6_L09_basic','lesson_basic','K3-2-u6-C27',2,'mc','auto','「체력을 기르기 위해 달리기를 하자」의 5번 줄을 고쳐야 하는 까닭은 무엇인가요?',ARRAY['K3-2-u6-X27','K3-2-u6-X23']::text[],false,'{"seq":5,"concept":"K3-2-u6-C27","difficulty":2,"kind":"mc","stem":"「체력을 기르기 위해 달리기를 하자」의 5번 줄을 고쳐야 하는 까닭은 무엇인가요?","options":[{"t":"내가 달리기를 잘한다는 것은 함께 달리기를 하자는 의견을 뒷받침하지 못하기 때문","correct":true},{"t":"문장이 너무 짧기 때문","mis":"K3-2-u6-X27"},{"t":"「둘째」라는 말을 썼기 때문","mis":"K3-2-u6-X27"},{"t":"나만 잘하는 것도 훌륭한 이유이므로 고칠 필요가 없다","mis":"K3-2-u6-X23"}],"explanation":["이유는 의견대로 하면 무엇이 좋아지는지를 말해야 해요.","나만 잘한다는 것은 모두에게 좋은 점이 아니에요.","그래서 의견과 관련 있는 이유로 바꾸어요."],"asset":{"type":"passage","lines":["제목: 체력을 기르기 위해 달리기를 하자","1 요즘 운동량이 부족해서 체력이 약한 어린이가 많다.","2 그래서 체력을 기르기 위해 점심시간에 함께 달리기를 하면 좋겠다.","3 첫째, 친구들과 함께 달리면 운동 효과가 더 좋아지기 때문이다.","4 (간추림) 여럿이 같이 달리면 힘이 나서 더 열심히 달릴 수 있다.","5 둘째, 내가 우리 반에서 달리기를 가장 잘하기 때문이다.","6 (간추림) 기록을 재면 내가 가장 빠르기 때문에 달리기는 항상 자신이 있다.","7 그래서 우리 반 친구들이 다 함께 달리기를 하며 체력을 길렀으면 좋겠다."],"numbered":false,"title":"고쳐 쓸 글 — 『국어』 274쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L09_basic#6','kor',3,2,'u6','L09','tb_g3_2_kor_u6_L09_basic','lesson_basic','K3-2-u6-C27',2,'mc','auto','『국어』 275쪽 3번이에요. 5번 줄을 바르게 고쳐 쓴 것은 무엇인가요?',ARRAY['K3-2-u6-X28','K3-2-u6-X22','K3-2-u6-X23']::text[],false,'{"seq":6,"concept":"K3-2-u6-C27","difficulty":2,"kind":"mc","stem":"『국어』 275쪽 3번이에요. 5번 줄을 바르게 고쳐 쓴 것은 무엇인가요?","options":[{"t":"둘째, 달리기를 매일 하면 체력도 길러지고 건강해진다. 온몸의 근육을 쓰고 심장과 폐도 튼튼해지기 때문이다.","correct":true},{"t":"5번 줄을 지우기만 하고 다른 이유는 쓰지 않는다.","mis":"K3-2-u6-X28"},{"t":"둘째, 나는 달리기가 정말 좋다.","mis":"K3-2-u6-X22"},{"t":"둘째, 우리 반에서 내가 두 번째로 빠르기 때문이다.","mis":"K3-2-u6-X23"}],"explanation":["이어지지 않는 이유는 지우기만 하지 않아요.","의견을 받쳐 주는 다른 이유로 바꾸어 써요.","매일 달리면 체력과 건강에 좋다는 이유는 의견과 잘 이어져요."],"asset":{"type":"passage","lines":["제목: 체력을 기르기 위해 달리기를 하자","1 요즘 운동량이 부족해서 체력이 약한 어린이가 많다.","2 그래서 체력을 기르기 위해 점심시간에 함께 달리기를 하면 좋겠다.","3 첫째, 친구들과 함께 달리면 운동 효과가 더 좋아지기 때문이다.","4 (간추림) 여럿이 같이 달리면 힘이 나서 더 열심히 달릴 수 있다.","5 둘째, 내가 우리 반에서 달리기를 가장 잘하기 때문이다.","6 (간추림) 기록을 재면 내가 가장 빠르기 때문에 달리기는 항상 자신이 있다.","7 그래서 우리 반 친구들이 다 함께 달리기를 하며 체력을 길렀으면 좋겠다."],"numbered":false,"title":"고쳐 쓸 글 — 『국어』 274쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L09_basic#7','kor',3,2,'u6','L09','tb_g3_2_kor_u6_L09_basic','lesson_basic','K3-2-u6-C26',2,'mc','auto','「체력을 기르기 위해 보드게임을 하자」라는 글을 읽었어요. 이 글에서 가장 먼저 고칠 점은 무엇인가요?',ARRAY['K3-2-u6-X25','K3-2-u6-X29','K3-2-u6-X27']::text[],false,'{"seq":7,"concept":"K3-2-u6-C26","difficulty":2,"kind":"mc","stem":"「체력을 기르기 위해 보드게임을 하자」라는 글을 읽었어요. 이 글에서 가장 먼저 고칠 점은 무엇인가요?","options":[{"t":"체력을 기르자는 문제 상황에 보드게임을 하자는 의견이 어울리지 않는다","correct":true},{"t":"이유가 두 가지뿐이라서 너무 적다","mis":"K3-2-u6-X25"},{"t":"고칠 곳이 있으니 못 쓴 글이라 버린다","mis":"K3-2-u6-X29"},{"t":"띄어쓰기만 고치면 된다","mis":"K3-2-u6-X27"}],"explanation":["운동량이 부족해 체력이 떨어진다는 것이 문제 상황이에요.","보드게임은 앉아서 하는 놀이라 체력을 기르는 데 맞지 않아요.","이유가 그럴듯해도 의견이 문제 상황과 어울려야 해요."],"asset":{"type":"passage","lines":["제목: 체력을 기르기 위해 보드게임을 하자","(간추림) 운동량이 부족해서 체력이 떨어지는 학생이 많다.","(간추림) 그래서 우리 반에 보드게임을 가져와서 함께 놀아야 한다.","(간추림) 첫째, 보드게임을 하면 두뇌 발달에 도움이 된다.","(간추림) 둘째, 보드게임을 하면 친구들과 더 친해질 수 있다."],"numbered":false,"title":"문제 상황과 어울리지 않는 의견을 제시한 글 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L09_basic#8','kor',3,2,'u6','L09','tb_g3_2_kor_u6_L09_basic','lesson_basic','K3-2-u6-C28',2,'mc','auto','『국어』 275쪽 5번이에요. 의견을 제시하는 글을 쓴 뒤에 고쳐 쓰면 좋은 점으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X29','K3-2-u6-X27','K3-2-u6-X02']::text[],false,'{"seq":8,"concept":"K3-2-u6-C28","difficulty":2,"kind":"mc","stem":"『국어』 275쪽 5번이에요. 의견을 제시하는 글을 쓴 뒤에 고쳐 쓰면 좋은 점으로 알맞은 것은 무엇인가요?","options":[{"t":"잘못된 의견이나 이유를 고치면 내 의견을 더 설득력 있게 제시할 수 있다","correct":true},{"t":"고칠 곳이 있는 글은 처음부터 다시 써야 한다는 것을 알 수 있다","mis":"K3-2-u6-X29"},{"t":"글을 길게 늘릴 수 있다","mis":"K3-2-u6-X27"},{"t":"선생님께 점수를 더 받을 수 있다","mis":"K3-2-u6-X02"}],"explanation":["고쳐 쓰면 읽는 사람의 처지에서 내 의견이 잘 전해지는지 볼 수 있어요.","잘못된 의견이나 이유를 고치면 더 설득력이 생겨요.","문제를 잘 해결할 의견인지도 다시 확인해요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"읽는 사람의 처지에서 내가 제시한 의견이 효과적으로 표현되었는지 확인할 수 있어."},{"who":"친구 2","text":"잘못된 의견이나 이유를 고치면 내 의견을 더 설득력 있게 제시할 수 있어."},{"who":"친구 3","text":"문제 상황을 잘 해결할 수 있는 의견과 이유인지 다시 한번 확인할 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L09_basic#9','kor',3,2,'u6','L09','tb_g3_2_kor_u6_L09_basic','lesson_basic','K3-2-u6-C29',2,'mc','auto','『국어』 275쪽 4번처럼 친구와 글을 바꾸어 읽었어요. 친구에게 할 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X30','K3-2-u6-X27']::text[],false,'{"seq":9,"concept":"K3-2-u6-C29","difficulty":2,"kind":"mc","stem":"『국어』 275쪽 4번처럼 친구와 글을 바꾸어 읽었어요. 친구에게 할 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“이유를 두 가지 쓴 점이 좋아. 그런데 둘째 이유는 의견과 관련이 없어 보여서 바꾸면 좋겠어.”","correct":true},{"t":"“너 글 진짜 못 썼다.”","mis":"K3-2-u6-X30"},{"t":"“틀린 데가 너무 많네. 다 고쳐.”","mis":"K3-2-u6-X30"},{"t":"“글씨가 삐뚤어서 별로야.”","mis":"K3-2-u6-X27"}],"explanation":["잘된 점을 먼저 말해요.","고칠 부분과 그렇게 생각한 이유를 간단히 말해요.","비난하거나 무시하는 말은 하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L09_basic#10','kor',3,2,'u6','L09','tb_g3_2_kor_u6_L09_basic','lesson_basic','K3-2-u6-C26',3,'essay','teacher','「체력을 기르기 위해 보드게임을 하자」의 의견을 문제 상황에 어울리는 의견으로 바꾸어 쓰고, 그 의견을 뒷받침하는 이유를 한 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u6-C26","difficulty":3,"kind":"essay","stem":"「체력을 기르기 위해 보드게임을 하자」의 의견을 문제 상황에 어울리는 의견으로 바꾸어 쓰고, 그 의견을 뒷받침하는 이유를 한 가지 쓰세요.","answer_guide":{"answer":"예: 의견 — 체력을 기르기 위해 쉬는 시간에 친구들과 운동장에서 술래잡기를 하자. 이유 — 술래잡기를 하면 많이 뛰게 되어 자연스럽게 체력을 기를 수 있기 때문이다.","scoring_points":["체력을 기르는 데 어울리는 의견으로 바꾸었는가","의견을 「……하자/……면 좋겠다」로 썼는가","의견을 뒷받침하는 이유를 썼는가"]},"explanation":["먼저 문제 상황을 다시 읽어요.","그 문제를 풀 수 있는 의견으로 바꾸어요.","의견과 이어지는 이유를 붙여요."],"asset":{"type":"passage","lines":["제목: 체력을 기르기 위해 보드게임을 하자","(간추림) 운동량이 부족해서 체력이 떨어지는 학생이 많다.","(간추림) 그래서 우리 반에 보드게임을 가져와서 함께 놀아야 한다.","(간추림) 첫째, 보드게임을 하면 두뇌 발달에 도움이 된다.","(간추림) 둘째, 보드게임을 하면 친구들과 더 친해질 수 있다."],"numbered":false,"title":"문제 상황과 어울리지 않는 의견을 제시한 글 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L09_challenge#1','kor',3,2,'u6','L09','tb_g3_2_kor_u6_L09_challenge','lesson_challenge','K3-2-u6-C26',2,'blank','auto','『국어』 274쪽 1번이에요. ㉢에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u6-X27','K3-2-u6-X30']::text[],false,'{"seq":1,"concept":"K3-2-u6-C26","difficulty":2,"kind":"blank","stem":"『국어』 274쪽 1번이에요. ㉢에 알맞은 말은 무엇인가요?","options":[{"t":"문제 해결","correct":true},{"t":"글씨 연습","mis":"K3-2-u6-X27"},{"t":"친구 칭찬","mis":"K3-2-u6-X30"}],"explanation":["의견과 그 이유가 문제 해결에 도움이 되는지 살펴봐요.","의견을 제시하는 글은 문제 상황을 해결하려고 써요.","그래서 문제 해결에 도움이 되어야 해요."],"asset":{"type":"passage","lines":["● 주제나 (    ㉠    )에 어울리는 의견을 썼는지 확인한다.","● 의견을 뒷받침하는 (    ㉡    )한 이유를 썼는지 확인한다.","● 의견과 그 이유가 (    ㉢    )에 도움이 되는지 살펴본다.","보기: 적절 · 문제 해결 · 문제 상황","※ 글의 내용에 어색한 부분, 띄어쓰기나 맞춤법이 틀린 부분도 살펴본다."],"title":"의견을 제시하는 글을 고쳐 쓰는 방법 — 『국어』 274쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L09_challenge#2','kor',3,2,'u6','L09','tb_g3_2_kor_u6_L09_challenge','lesson_challenge','K3-2-u6-C28',2,'ox','auto','고칠 곳이 보이는 글은 잘못 쓴 글이므로 처음부터 다시 써야 해요.',ARRAY['K3-2-u6-X29']::text[],false,'{"seq":2,"concept":"K3-2-u6-C28","difficulty":2,"kind":"ox","stem":"고칠 곳이 보이는 글은 잘못 쓴 글이므로 처음부터 다시 써야 해요.","answer":"X","reason_options":[{"t":"고칠 곳을 찾았다는 것은 글을 다시 읽었다는 뜻이고, 그 부분을 고치면 글이 더 좋아지기 때문에","correct":true},{"t":"잘 쓴 글은 처음부터 고칠 곳이 없기 때문에","mis":"K3-2-u6-X29"}],"mis":"K3-2-u6-X29","explanation":["글은 고쳐 가며 좋아져요.","고칠 부분만 바르게 고쳐 쓰면 돼요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L09_challenge#3','kor',3,2,'u6','L09','tb_g3_2_kor_u6_L09_challenge','lesson_challenge','K3-2-u6-C27',3,'mc','auto','「체력을 기르기 위해 보드게임을 하자」를 고쳐 쓰려고 해요. 가장 알맞은 방법은 무엇인가요?',ARRAY['K3-2-u6-X44','K3-2-u6-X27','K3-2-u6-X28']::text[],false,'{"seq":3,"concept":"K3-2-u6-C27","difficulty":3,"kind":"mc","stem":"「체력을 기르기 위해 보드게임을 하자」를 고쳐 쓰려고 해요. 가장 알맞은 방법은 무엇인가요?","options":[{"t":"체력을 기르는 데 도움이 되는 의견으로 바꾸고, 그에 맞는 이유를 쓴다","correct":true},{"t":"의견은 그대로 두고 보드게임의 좋은 점을 하나 더 쓴다","mis":"K3-2-u6-X44"},{"t":"제목만 바꾼다","mis":"K3-2-u6-X27"},{"t":"이유를 모두 지우기만 한다","mis":"K3-2-u6-X28"}],"explanation":["두뇌 발달, 친해짐은 보드게임의 좋은 점이지만 체력 문제를 풀지 못해요.","이유를 더해도 의견이 어울리지 않으면 그대로예요.","의견부터 문제 상황에 맞게 고쳐요."],"asset":{"type":"passage","lines":["제목: 체력을 기르기 위해 보드게임을 하자","(간추림) 운동량이 부족해서 체력이 떨어지는 학생이 많다.","(간추림) 그래서 우리 반에 보드게임을 가져와서 함께 놀아야 한다.","(간추림) 첫째, 보드게임을 하면 두뇌 발달에 도움이 된다.","(간추림) 둘째, 보드게임을 하면 친구들과 더 친해질 수 있다."],"numbered":false,"title":"문제 상황과 어울리지 않는 의견을 제시한 글 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L09_challenge#4','kor',3,2,'u6','L09','tb_g3_2_kor_u6_L09_challenge','lesson_challenge','K3-2-u6-C26',3,'error','auto','고쳐 쓰기에 대해 친구들이 한 말이에요. 알맞지 않은 말은 무엇인가요?',ARRAY['K3-2-u6-X27','K3-2-u6-X26']::text[],false,'{"seq":4,"concept":"K3-2-u6-C26","difficulty":3,"kind":"error","stem":"고쳐 쓰기에 대해 친구들이 한 말이에요. 알맞지 않은 말은 무엇인가요?","options":[{"t":"“의견과 이유만 보면 되니까 띄어쓰기나 맞춤법은 안 봐도 돼.”","correct":true,"mis_target":"K3-2-u6-X27"},{"t":"“글의 내용에 어색한 부분은 없는지도 봐야 해.”","mis":"K3-2-u6-X27"},{"t":"“문단의 짜임에 맞게 썼는지도 살펴보자.”","mis":"K3-2-u6-X26"}],"explanation":["의견과 이유 말고도 살필 것이 있어요.","내용에 어색한 부분, 문단의 짜임도 보아요.","띄어쓰기나 맞춤법 같은 표현도 살펴봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L09_challenge#5','kor',3,2,'u6','L09','tb_g3_2_kor_u6_L09_challenge','lesson_challenge','K3-2-u6-C29',3,'mc','auto','「체력을 기르기 위해 달리기를 하자」를 쓴 친구에게 고칠 점을 말해 주려고 해요. 말하는 차례로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X30','K3-2-u6-X02','K3-2-u6-X29']::text[],false,'{"seq":5,"concept":"K3-2-u6-C29","difficulty":3,"kind":"mc","stem":"「체력을 기르기 위해 달리기를 하자」를 쓴 친구에게 고칠 점을 말해 주려고 해요. 말하는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"잘된 점을 먼저 한 가지 말하고, 고칠 부분을 짚어 그렇게 생각한 이유와 함께 말한다","correct":true},{"t":"고칠 부분만 빠르게 모두 말한다","mis":"K3-2-u6-X30"},{"t":"몇 점짜리 글인지 먼저 말한다","mis":"K3-2-u6-X02"},{"t":"고칠 곳이 있으니 다시 쓰라고 한다","mis":"K3-2-u6-X29"}],"explanation":["첫째 이유처럼 잘된 곳을 먼저 말해 줘요.","그다음 5번 줄처럼 고칠 부분과 까닭을 말해요.","친구가 무엇을 왜 고칠지 알 수 있게요."],"asset":{"type":"passage","lines":["제목: 체력을 기르기 위해 달리기를 하자","1 요즘 운동량이 부족해서 체력이 약한 어린이가 많다.","2 그래서 체력을 기르기 위해 점심시간에 함께 달리기를 하면 좋겠다.","3 첫째, 친구들과 함께 달리면 운동 효과가 더 좋아지기 때문이다.","4 (간추림) 여럿이 같이 달리면 힘이 나서 더 열심히 달릴 수 있다.","5 둘째, 내가 우리 반에서 달리기를 가장 잘하기 때문이다.","6 (간추림) 기록을 재면 내가 가장 빠르기 때문에 달리기는 항상 자신이 있다.","7 그래서 우리 반 친구들이 다 함께 달리기를 하며 체력을 길렀으면 좋겠다."],"numbered":false,"title":"고쳐 쓸 글 — 『국어』 274쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L09_challenge#6','kor',3,2,'u6','L09','tb_g3_2_kor_u6_L09_challenge','lesson_challenge','K3-2-u6-C28',3,'mc','auto','고쳐 쓰기를 마친 친구가 「고쳐 쓰니 문제 상황을 잘 해결할 수 있는 의견과 이유인지 다시 한번 확인할 수 있었어.」라고 했어요. 이 친구가 깨달은 것으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X29','K3-2-u6-X27','K3-2-u6-X30']::text[],false,'{"seq":6,"concept":"K3-2-u6-C28","difficulty":3,"kind":"mc","stem":"고쳐 쓰기를 마친 친구가 「고쳐 쓰니 문제 상황을 잘 해결할 수 있는 의견과 이유인지 다시 한번 확인할 수 있었어.」라고 했어요. 이 친구가 깨달은 것으로 알맞은 것은 무엇인가요?","options":[{"t":"고쳐 쓰기는 글을 더 좋게 만드는 과정이다","correct":true},{"t":"고칠 곳이 있었으니 처음 글은 못 쓴 글이다","mis":"K3-2-u6-X29"},{"t":"고쳐 쓰기는 글의 길이를 늘리는 일이다","mis":"K3-2-u6-X27"},{"t":"고쳐 쓰기는 다른 사람의 흠을 찾는 일이다","mis":"K3-2-u6-X30"}],"explanation":["고쳐 쓰면 내 의견이 잘 전해지는지 다시 볼 수 있어요.","잘못된 의견이나 이유도 바로잡을 수 있어요.","고칠 곳이 있었다고 못 쓴 글이 되는 것은 아니에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"읽는 사람의 처지에서 내가 제시한 의견이 효과적으로 표현되었는지 확인할 수 있어."},{"who":"친구 2","text":"잘못된 의견이나 이유를 고치면 내 의견을 더 설득력 있게 제시할 수 있어."},{"who":"친구 3","text":"문제 상황을 잘 해결할 수 있는 의견과 이유인지 다시 한번 확인할 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L09_challenge#7','kor',3,2,'u6','L09','tb_g3_2_kor_u6_L09_challenge','lesson_challenge','K3-2-u6-C27',3,'sa','auto','「체력을 기르기 위해 달리기를 하자」에서 의견을 뒷받침하지 못하는 이유가 쓰인 줄은 몇 번인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"K3-2-u6-C27","difficulty":3,"kind":"sa","stem":"「체력을 기르기 위해 달리기를 하자」에서 의견을 뒷받침하지 못하는 이유가 쓰인 줄은 몇 번인가요? 숫자로 쓰세요.","answer":["5","5번"],"explanation":["이유 두 가지를 찾아 하나씩 의견과 이어 보아요.","3번 줄은 함께 달리면 운동 효과가 좋아진다는 알맞은 이유예요.","5번 줄은 나만 잘한다는 것이라 의견을 받쳐 주지 못해요."],"asset":{"type":"passage","lines":["제목: 체력을 기르기 위해 달리기를 하자","1 요즘 운동량이 부족해서 체력이 약한 어린이가 많다.","2 그래서 체력을 기르기 위해 점심시간에 함께 달리기를 하면 좋겠다.","3 첫째, 친구들과 함께 달리면 운동 효과가 더 좋아지기 때문이다.","4 (간추림) 여럿이 같이 달리면 힘이 나서 더 열심히 달릴 수 있다.","5 둘째, 내가 우리 반에서 달리기를 가장 잘하기 때문이다.","6 (간추림) 기록을 재면 내가 가장 빠르기 때문에 달리기는 항상 자신이 있다.","7 그래서 우리 반 친구들이 다 함께 달리기를 하며 체력을 길렀으면 좋겠다."],"numbered":false,"title":"고쳐 쓸 글 — 『국어』 274쪽"},"mis":"K3-2-u6-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L09_challenge#8','kor',3,2,'u6','L09','tb_g3_2_kor_u6_L09_challenge','lesson_challenge','K3-2-u6-C27',4,'essay','teacher','「체력을 기르기 위해 달리기를 하자」의 5번 줄을 다른 이유로 고쳐 쓰고, 고친 이유가 왜 의견을 뒷받침하는지 쓰세요. (『국어』 275쪽 예와 다른 이유로 써 보세요.)','{}'::text[],false,'{"seq":8,"concept":"K3-2-u6-C27","difficulty":4,"kind":"essay","stem":"「체력을 기르기 위해 달리기를 하자」의 5번 줄을 다른 이유로 고쳐 쓰고, 고친 이유가 왜 의견을 뒷받침하는지 쓰세요. (『국어』 275쪽 예와 다른 이유로 써 보세요.)","answer_guide":{"answer":"예: 둘째, 점심시간에 달리기를 하면 오후 수업 시간에 졸지 않고 더 집중할 수 있기 때문이다. — 함께 달리기를 하자는 의견대로 하면 생기는 좋은 점이라 의견을 받쳐 준다.","scoring_points":["5번 줄을 다른 이유로 고쳐 썼는가","고친 이유가 함께 달리기를 하자는 의견과 이어지는가","왜 뒷받침하는지 까닭을 썼는가"]},"explanation":["이어지지 않는 이유는 지우기만 하지 않아요.","의견대로 하면 무엇이 좋아지는지 써요.","그래야 이유가 의견을 받쳐 줘요."],"asset":{"type":"passage","lines":["제목: 체력을 기르기 위해 달리기를 하자","1 요즘 운동량이 부족해서 체력이 약한 어린이가 많다.","2 그래서 체력을 기르기 위해 점심시간에 함께 달리기를 하면 좋겠다.","3 첫째, 친구들과 함께 달리면 운동 효과가 더 좋아지기 때문이다.","4 (간추림) 여럿이 같이 달리면 힘이 나서 더 열심히 달릴 수 있다.","5 둘째, 내가 우리 반에서 달리기를 가장 잘하기 때문이다.","6 (간추림) 기록을 재면 내가 가장 빠르기 때문에 달리기는 항상 자신이 있다.","7 그래서 우리 반 친구들이 다 함께 달리기를 하며 체력을 길렀으면 좋겠다."],"numbered":false,"title":"고쳐 쓸 글 — 『국어』 274쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L09_challenge#9','kor',3,2,'u6','L09','tb_g3_2_kor_u6_L09_challenge','lesson_challenge','K3-2-u6-C29',4,'essay','teacher','「체력을 기르기 위해 보드게임을 하자」를 쓴 친구의 글 아래에 고쳐 쓸 점을 적어 주려고 해요. 잘된 점 한 가지, 고칠 부분, 그렇게 생각한 이유를 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u6-C29","difficulty":4,"kind":"essay","stem":"「체력을 기르기 위해 보드게임을 하자」를 쓴 친구의 글 아래에 고쳐 쓸 점을 적어 주려고 해요. 잘된 점 한 가지, 고칠 부분, 그렇게 생각한 이유를 쓰세요.","answer_guide":{"answer":"예: 잘된 점 — 「첫째」, 「둘째」로 이유를 나누어 써서 읽기 쉬워. 고칠 부분 — 보드게임을 하자는 의견. 이유 — 체력을 기르자는 문제 상황인데 보드게임은 앉아서 하는 놀이라 체력을 기르는 데 도움이 되기 어려워.","scoring_points":["잘된 점을 먼저 썼는가","고칠 부분을 분명하게 짚었는가","고칠 이유를 비난 없이 간단명료하게 썼는가"]},"explanation":["잘된 점부터 적어 줘요.","고칠 부분은 점검표를 바탕으로 분명하게 짚어요.","비난하지 않고 이유만 간단히 써요."],"asset":{"type":"passage","lines":["제목: 체력을 기르기 위해 보드게임을 하자","(간추림) 운동량이 부족해서 체력이 떨어지는 학생이 많다.","(간추림) 그래서 우리 반에 보드게임을 가져와서 함께 놀아야 한다.","(간추림) 첫째, 보드게임을 하면 두뇌 발달에 도움이 된다.","(간추림) 둘째, 보드게임을 하면 친구들과 더 친해질 수 있다."],"numbered":false,"title":"문제 상황과 어울리지 않는 의견을 제시한 글 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L09_challenge#10','kor',3,2,'u6','L09','tb_g3_2_kor_u6_L09_challenge','lesson_challenge','K3-2-u6-C26',4,'mc','auto','의견을 제시하는 글을 고쳐 쓸 때 살펴볼 것을 바르게 모은 것은 무엇인가요?',ARRAY['K3-2-u6-X27','K3-2-u6-X30']::text[],false,'{"seq":10,"concept":"K3-2-u6-C26","difficulty":4,"kind":"mc","stem":"의견을 제시하는 글을 고쳐 쓸 때 살펴볼 것을 바르게 모은 것은 무엇인가요?","options":[{"t":"문제 상황에 어울리는 의견 · 뒷받침하는 적절한 이유 · 문제 해결에 도움 · 띄어쓰기와 맞춤법","correct":true},{"t":"글의 길이 · 글씨 모양 · 고운 말 · 제목 글자 크기","mis":"K3-2-u6-X27"},{"t":"의견과 이유만 보고 나머지는 볼 필요 없음","mis":"K3-2-u6-X27"},{"t":"흠 개수 · 점수 · 몇 등인지","mis":"K3-2-u6-X30"}],"explanation":["내용 쪽: 의견, 이유, 문제 해결, 어색한 부분을 보아요.","표현 쪽: 띄어쓰기와 맞춤법을 보아요.","글의 길이나 글씨 모양은 고쳐 쓸 거리가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L10_basic#1','kor',3,2,'u6','L10','tb_g3_2_kor_u6_L10_basic','lesson_basic','K3-2-u6-C30',1,'sa','auto','뉴스에서 ‘옐로 카펫’을 만들어 줄이려고 한 것은 어린이의 무엇인가요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u6-C30","difficulty":1,"kind":"sa","stem":"뉴스에서 ‘옐로 카펫’을 만들어 줄이려고 한 것은 어린이의 무엇인가요? 네 글자로 쓰세요.","answer":["교통사고","어린이 교통사고"],"explanation":["학교 앞 횡단보도 부근 벽면을 노랗게 칠했어요.","어린이 교통사고를 줄이려는 제안이었어요.","의견을 내면 여럿의 문제를 해결하는 방법을 찾을 수 있어요."],"asset":{"type":"passage","lines":["(간추림) 어린이 교통사고를 줄이려고 한 시민 단체의 제안으로","학교 앞 횡단보도 부근 벽면에 노란색을 칠한 ‘옐로 카펫’을 만들었다.","(간추림) 눈에 잘 띄는 것만으로도 교통사고 위험을 크게 줄일 수 있다고 한다.","초등학생: 파란불이 켜지면 막 달려갔는데, 한 번 쉬었다 가게 되니까 더 안전해요."],"title":"뉴스 「“교통사고 줄여요”…… 주민들이 만든 옐로 카펫」"},"mis":"K3-2-u6-X31"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L10_basic#2','kor',3,2,'u6','L10','tb_g3_2_kor_u6_L10_basic','lesson_basic','K3-2-u6-C30',1,'mc','auto','『국어』 276쪽 그림 ㉮를 보고 떠올릴 수 있는 우리 학교의 문제 상황은 무엇인가요?',ARRAY['K3-2-u6-X31','K3-2-u6-X32']::text[],false,'{"seq":2,"concept":"K3-2-u6-C30","difficulty":1,"kind":"mc","stem":"『국어』 276쪽 그림 ㉮를 보고 떠올릴 수 있는 우리 학교의 문제 상황은 무엇인가요?","options":[{"t":"학교 환경이 깨끗하지 않다","correct":true},{"t":"복도는 원래 길어서 어쩔 수 없다","mis":"K3-2-u6-X31"},{"t":"쓰레기를 버린 친구의 이름을 알아내 적는다","mis":"K3-2-u6-X32"},{"t":"비가 와서 운동장에 나가지 못한다","mis":"K3-2-u6-X31"}],"explanation":["그림 ㉮는 불청결한 학교 환경을 보여 줘요.","우리가 함께 바꿀 수 있는 문제를 찾아요.","누군가를 탓하는 것은 문제 상황이 아니에요."],"asset":{"type":"passage","lines":["주제: 더 나은 학교를 만들기 위해 학생들이 실천할 수 있는 방법","[그림 ㉮] 불청결한 학교 환경","[그림 ㉯] 친구와 다툼이 있는 상황","[그림 ?] 우리 학급이나 학교의 또 다른 문제 상황"],"title":"문제 파악하기 — 『국어』 276쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L10_basic#3','kor',3,2,'u6','L10','tb_g3_2_kor_u6_L10_basic','lesson_basic','K3-2-u6-C31',1,'mc','auto','『국어』 276쪽 계획하기에서 읽을 사람(우리 반 친구들)과 활용 방법(학급 알림판에 게시)을 미리 정하는 까닭은 무엇인가요?',ARRAY['K3-2-u6-X33','K3-2-u6-X26','K3-2-u6-X02']::text[],false,'{"seq":3,"concept":"K3-2-u6-C31","difficulty":1,"kind":"mc","stem":"『국어』 276쪽 계획하기에서 읽을 사람(우리 반 친구들)과 활용 방법(학급 알림판에 게시)을 미리 정하는 까닭은 무엇인가요?","options":[{"t":"누가 읽고 어디에 쓸지 알아야 그에 맞게 쓸 말을 정할 수 있어서","correct":true},{"t":"누가 읽든 글은 똑같이 쓰면 되어서","mis":"K3-2-u6-X33"},{"t":"글을 길게 쓰려고","mis":"K3-2-u6-X26"},{"t":"알림판 꾸미기 점수를 받으려고","mis":"K3-2-u6-X02"}],"explanation":["쓰기 전에 읽을 사람과 활용 방법을 정해요.","읽을 사람에 따라 쓸 말과 자세한 정도가 달라져요.","쓴 글은 계획한 대로 게시하거나 발표해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L10_basic#4','kor',3,2,'u6','L10','tb_g3_2_kor_u6_L10_basic','lesson_basic','K3-2-u6-C32',1,'ox','auto','의견을 뒷받침하는 타당한 이유가 없으면 의견이 적절한지 알기 어려워요.',ARRAY['K3-2-u6-X20']::text[],false,'{"seq":4,"concept":"K3-2-u6-C32","difficulty":1,"kind":"ox","stem":"의견을 뒷받침하는 타당한 이유가 없으면 의견이 적절한지 알기 어려워요.","answer":"O","reason_options":[{"t":"이유가 있어야 다른 사람도 그 의견에 납득할 수 있기 때문에","correct":true},{"t":"의견만 크게 쓰면 모두가 따라 주기 때문에","mis":"K3-2-u6-X20"}],"mis":"K3-2-u6-X20","explanation":["타당한 이유가 없으면 의견의 적절성이 떨어져요.","이유가 많을수록 의견을 탄탄하게 받쳐 줘요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L10_basic#5','kor',3,2,'u6','L10','tb_g3_2_kor_u6_L10_basic','lesson_basic','K3-2-u6-C32',2,'mc','auto','『국어』 277쪽이에요. 「걸어 다니자는 표지판을 만들어 곳곳에 붙여 놓자.」는 의견을 뒷받침하는 이유로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X23','K3-2-u6-X22','K3-2-u6-X25']::text[],false,'{"seq":5,"concept":"K3-2-u6-C32","difficulty":2,"kind":"mc","stem":"『국어』 277쪽이에요. 「걸어 다니자는 표지판을 만들어 곳곳에 붙여 놓자.」는 의견을 뒷받침하는 이유로 알맞은 것은 무엇인가요?","options":[{"t":"교통 표지판을 보고 차들이 속도를 줄이듯이, 표지판을 보면 뛰지 말아야겠다는 생각이 들기 때문","correct":true},{"t":"내가 우리 반에서 표지판을 가장 잘 그리기 때문","mis":"K3-2-u6-X23"},{"t":"복도가 교실보다 길기 때문","mis":"K3-2-u6-X22"},{"t":"표지판을 붙이면 표지판이 붙어 있게 되기 때문","mis":"K3-2-u6-X25"}],"explanation":["이유는 의견대로 하면 무엇이 좋아지는지 말해요.","표지판이 뛰려던 마음을 멈추게 한다는 것이 의견을 받쳐 줘요.","나만 잘한다는 것, 상관없는 것, 같은 말 되풀이는 이유가 아니에요."],"asset":{"type":"passage","lines":["문제 상황 — 교실 안이나 복도에서 뛰어다니는 학생이 많다.","내 의견 — 걸어 다니자는 표지판을 만들어 교실이나 복도 곳곳에 붙여 놓자.","이유 — 교통 표지판을 보고 차들이 속도를 줄이듯이","뛰려고 하던 학생들도 표지판을 보면 뛰지 말아야겠다는 생각이 들기 때문이다."],"numbered":false,"title":"의견과 이유 떠올리기 — 『국어』 277쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L10_basic#6','kor',3,2,'u6','L10','tb_g3_2_kor_u6_L10_basic','lesson_basic','K3-2-u6-C30',2,'mc','auto','교실이나 복도에서 뛰어다니는 학생이 많다는 문제에 대한 의견으로, 문제를 근본적으로 해결하는 방법을 담은 것은 무엇인가요?',ARRAY['K3-2-u6-X43','K3-2-u6-X32','K3-2-u6-X31']::text[],false,'{"seq":6,"concept":"K3-2-u6-C30","difficulty":2,"kind":"mc","stem":"교실이나 복도에서 뛰어다니는 학생이 많다는 문제에 대한 의견으로, 문제를 근본적으로 해결하는 방법을 담은 것은 무엇인가요?","options":[{"t":"쉬는 시간마다 안전 지킴이가 복도에 서서 걸어 다니도록 알려 주자","correct":true},{"t":"복도에서 뛰지 말자","mis":"K3-2-u6-X43"},{"t":"뛰는 친구의 이름을 칠판에 적자","mis":"K3-2-u6-X32"},{"t":"복도는 원래 넓어서 뛰는 것을 막을 수 없다","mis":"K3-2-u6-X31"}],"explanation":["「……하지 말자」만으로는 문제가 잘 풀리지 않아요.","무엇을 하면 문제가 풀릴지 방법을 내요.","누군가를 탓하거나 포기하는 말은 의견이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L10_basic#7','kor',3,2,'u6','L10','tb_g3_2_kor_u6_L10_basic','lesson_basic','K3-2-u6-C33',2,'match','auto','「뛰지 않는 안전한 학교」의 문장과 글의 짜임을 바르게 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K3-2-u6-C33","difficulty":2,"kind":"match","stem":"「뛰지 않는 안전한 학교」의 문장과 글의 짜임을 바르게 이어 보세요.","pairs":[{"l":"교실 안이나 복도에서 뛰어다니는 학생이 많습니다.","r":"문제 상황"},{"l":"걸어 다니자는 표지판을 만들어 곳곳에 붙여 놓으면 좋겠습니다.","r":"의견"},{"l":"표지판을 만들면서 뛰지 말아야겠다는 다짐도 할 수 있기 때문입니다.","r":"이유"},{"l":"표지판을 만들어 모두가 안전한 학교를 만들고 싶습니다.","r":"맺음"}],"mis":"K3-2-u6-X21","explanation":["처음에 무엇이 문제인지 써요.","「……면 좋겠습니다」는 의견, 「……때문입니다」는 이유예요.","마지막에 바라는 모습으로 맺어요."],"asset":{"type":"passage","lines":["제목: 뛰지 않는 안전한 학교","1 교실 안이나 복도에서 뛰어다니는 학생이 많습니다.","2 (간추림) 뛰어다니면 넘어져 다치거나 다른 학생과 부딪쳐 다치게 할 수 있습니다.","3 걸어 다니자는 표지판을 만들어 곳곳에 붙여 놓으면 좋겠습니다.","4 표지판을 보면 뛰지 말아야겠다는 생각이 들기 때문입니다.","5 또 표지판을 만들면서 뛰지 말아야겠다는 다짐도 할 수 있기 때문입니다.","6 표지판을 만들어 모두가 안전한 학교를 만들고 싶습니다."],"numbered":false,"title":"의견을 제시하는 글 (예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L10_basic#8','kor',3,2,'u6','L10','tb_g3_2_kor_u6_L10_basic','lesson_basic','K3-2-u6-C34',2,'mc','auto','『국어』 278쪽 점검하기에서 자신이 쓴 글을 읽고 스스로 확인할 내용으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X27','K3-2-u6-X02']::text[],false,'{"seq":8,"concept":"K3-2-u6-C34","difficulty":2,"kind":"mc","stem":"『국어』 278쪽 점검하기에서 자신이 쓴 글을 읽고 스스로 확인할 내용으로 알맞은 것은 무엇인가요?","options":[{"t":"글의 내용에 어색한 부분은 없나요?","correct":true},{"t":"글이 한 쪽을 넘었나요?","mis":"K3-2-u6-X27"},{"t":"글씨가 바르게 기울었나요?","mis":"K3-2-u6-X27"},{"t":"친구 글보다 이유가 많나요?","mis":"K3-2-u6-X02"}],"explanation":["점검표에는 네 가지가 있어요.","해결할 수 있는 의견, 적절한 이유, 어색한 부분, 띄어쓰기와 맞춤법이에요.","글의 길이나 친구와의 비교는 없어요."],"asset":{"type":"passage","lines":["문제 상황을 해결할 수 있는 의견을 썼나요?  ○○○","의견을 뒷받침하는 적절한 이유를 썼나요?  ○○○","글의 내용에 어색한 부분은 없나요?  ○○○","띄어쓰기나 맞춤법이 틀린 부분은 없나요?  ○○○"],"title":"자신이 쓴 글을 읽고 스스로 확인하기 — 『국어』 278쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L10_basic#9','kor',3,2,'u6','L10','tb_g3_2_kor_u6_L10_basic','lesson_basic','K3-2-u6-C24',2,'mc','auto','복도에서 뛰는 문제에 대해 한 친구는 표지판을 붙이자고, 다른 친구는 안전 지킴이를 뽑자고 했어요. 두 글에 대한 생각으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X24','K3-2-u6-X27']::text[],false,'{"seq":9,"concept":"K3-2-u6-C24","difficulty":2,"kind":"mc","stem":"복도에서 뛰는 문제에 대해 한 친구는 표지판을 붙이자고, 다른 친구는 안전 지킴이를 뽑자고 했어요. 두 글에 대한 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"두 글 모두 이유가 의견을 뒷받침하므로 의견이 달라도 둘 다 알맞을 수 있다","correct":true},{"t":"먼저 쓴 표지판 글만 맞는 의견이다","mis":"K3-2-u6-X24"},{"t":"의견이 다르니 둘 가운데 하나는 틀린 글이다","mis":"K3-2-u6-X24"},{"t":"안전 지킴이 글이 더 길어서 더 좋은 글이다","mis":"K3-2-u6-X27"}],"explanation":["같은 문제 상황에도 의견은 여러 가지가 나올 수 있어요.","어느 의견인지보다 이유가 의견을 받쳐 주는지가 중요해요.","여러 의견을 모아 가장 효과적인 것을 찾을 수도 있어요."],"asset":{"type":"passage","lines":["(간추림) 복도에서 뛰는 학생과 부딪쳐 무릎을 다친 적이 있다. 뛰어다니면 위험하다.","안전 지킴이를 뽑아 쉬는 시간이나 점심시간에 활동하도록 하면 좋겠습니다.","(간추림) 지킴이가 경고를 주면 뛰는 학생과 안전사고가 줄어든다.","(간추림) 지킴이가 서 있는 것만으로도 뛰면 안 된다는 점을 떠올리게 된다."],"title":"같은 문제 상황에 대한 다른 의견 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L10_basic#10','kor',3,2,'u6','L10','tb_g3_2_kor_u6_L10_basic','lesson_basic','K3-2-u6-C33',3,'essay','teacher','『국어』 276쪽 그림 ㉯(친구와 다툼이 있는 상황)를 보고 떠올린 문제 상황으로 의견을 제시하는 글을 계획하세요. 문제 상황, 내 의견, 그렇게 생각한 이유를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u6-C33","difficulty":3,"kind":"essay","stem":"『국어』 276쪽 그림 ㉯(친구와 다툼이 있는 상황)를 보고 떠올린 문제 상황으로 의견을 제시하는 글을 계획하세요. 문제 상황, 내 의견, 그렇게 생각한 이유를 쓰세요.","answer_guide":{"answer":"예: 문제 상황 — 쉬는 시간에 작은 일로 다투는 친구들이 많다. 내 의견 — 학급 회의에서 「마음 나누기 시간」을 정해 서운한 일을 차례로 말하자. 이유 — 서운한 마음을 쌓아 두지 않고 말하면 다툼이 커지기 전에 풀 수 있기 때문이다.","scoring_points":["그림 ㉯와 이어지는 문제 상황을 썼는가","문제를 풀 수 있는 의견을 썼는가","의견을 뒷받침하는 이유를 썼는가"]},"explanation":["그림을 보고 우리 반에서 비슷한 경험을 떠올려요.","「……하지 말자」보다 무엇을 하자는 해결책을 내요.","의견대로 하면 무엇이 좋아지는지 이유로 써요."],"asset":{"type":"passage","lines":["주제: 더 나은 학교를 만들기 위해 학생들이 실천할 수 있는 방법","[그림 ㉮] 불청결한 학교 환경","[그림 ㉯] 친구와 다툼이 있는 상황","[그림 ?] 우리 학급이나 학교의 또 다른 문제 상황"],"title":"문제 파악하기 — 『국어』 276쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L10_challenge#1','kor',3,2,'u6','L10','tb_g3_2_kor_u6_L10_challenge','lesson_challenge','K3-2-u6-C34',2,'mc','auto','『국어활동』 86~87쪽 글이에요. 의견을 뒷받침하는 적절한 이유를 모두 고른 것은 무엇인가요?',ARRAY['K3-2-u6-X22']::text[],false,'{"seq":1,"concept":"K3-2-u6-C34","difficulty":2,"kind":"mc","stem":"『국어활동』 86~87쪽 글이에요. 의견을 뒷받침하는 적절한 이유를 모두 고른 것은 무엇인가요?","options":[{"t":"㉮, ㉯","correct":true},{"t":"㉮, ㉯, ㉰","mis":"K3-2-u6-X22"},{"t":"㉰","mis":"K3-2-u6-X22"},{"t":"㉯, ㉰","mis":"K3-2-u6-X22"}],"explanation":["㉮ 시력, ㉯ 꼭 해야 할 일은 사용 시간을 정하자는 의견을 받쳐 줘요.","㉰ 「도움을 주기 때문」은 오히려 의견과 맞지 않아요.","의견과 관련 없는 이유는 고쳐 써야 해요."],"asset":{"type":"passage","lines":["문제 상황 — 스마트 기기를 지나치게 오래 사용하는 학생이 많다.","의견 — 스마트 기기 사용 시간을 알맞게 정해 스스로 지키자.","이유 ㉮ 스마트 기기를 너무 오래 사용하면 시력이 나빠지기 때문입니다.","이유 ㉯ 스마트 기기에 빠져 숙제나 독서처럼 꼭 해야 하는 일들을 못 할 수도 있기 때문입니다.","이유 ㉰ 스마트 기기는 우리에게 도움을 주기 때문입니다."],"numbered":false,"title":"『국어활동』 87쪽 예시 답안에 실린 문제 상황·의견·이유"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L10_challenge#2','kor',3,2,'u6','L10','tb_g3_2_kor_u6_L10_challenge','lesson_challenge','K3-2-u6-C34',2,'mc','auto','『국어활동』 87쪽 4번이에요. 이 글을 고쳐 쓸 때 낼 수 있는 의견으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X44','K3-2-u6-X27']::text[],false,'{"seq":2,"concept":"K3-2-u6-C34","difficulty":2,"kind":"mc","stem":"『국어활동』 87쪽 4번이에요. 이 글을 고쳐 쓸 때 낼 수 있는 의견으로 알맞은 것은 무엇인가요?","options":[{"t":"의견을 뒷받침하는 적절한 이유를 들지 않았어.","correct":true},{"t":"주제나 문제 상황에 어울리는 의견을 쓰지 않았어.","mis":"K3-2-u6-X44"},{"t":"띄어쓰기나 맞춤법이 틀린 부분이 있어.","mis":"K3-2-u6-X27"}],"explanation":["문제 상황과 의견은 서로 잘 어울려요.","그런데 ㉰는 의견을 뒷받침하지 못하는 이유예요.","그래서 적절한 이유를 들지 않았다는 의견을 내요."],"asset":{"type":"passage","lines":["문제 상황 — 스마트 기기를 지나치게 오래 사용하는 학생이 많다.","의견 — 스마트 기기 사용 시간을 알맞게 정해 스스로 지키자.","이유 ㉮ 스마트 기기를 너무 오래 사용하면 시력이 나빠지기 때문입니다.","이유 ㉯ 스마트 기기에 빠져 숙제나 독서처럼 꼭 해야 하는 일들을 못 할 수도 있기 때문입니다.","이유 ㉰ 스마트 기기는 우리에게 도움을 주기 때문입니다."],"numbered":false,"title":"『국어활동』 87쪽 예시 답안에 실린 문제 상황·의견·이유"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L10_challenge#3','kor',3,2,'u6','L10','tb_g3_2_kor_u6_L10_challenge','lesson_challenge','K3-2-u6-C32',3,'mc','auto','의견을 뒷받침하는 이유가 잘 떠오르지 않을 때 해 볼 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X20','K3-2-u6-X25','K3-2-u6-X23']::text[],false,'{"seq":3,"concept":"K3-2-u6-C32","difficulty":3,"kind":"mc","stem":"의견을 뒷받침하는 이유가 잘 떠오르지 않을 때 해 볼 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"내 의견대로 하면 어떤 점이 좋아지는지(의견의 장점)를 생각해 본다","correct":true},{"t":"이유 없이 의견만 크게 쓴다","mis":"K3-2-u6-X20"},{"t":"같은 이유를 말만 바꾸어 여러 번 쓴다","mis":"K3-2-u6-X25"},{"t":"내가 잘하는 것을 이유로 쓴다","mis":"K3-2-u6-X23"}],"explanation":["의견에 따른 장점을 떠올리면 이유가 보여요.","생각그물을 그려 생각을 넓혀도 좋아요.","이유가 많을수록 의견을 탄탄하게 받쳐 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L10_challenge#4','kor',3,2,'u6','L10','tb_g3_2_kor_u6_L10_challenge','lesson_challenge','K3-2-u6-C34',3,'mc','auto','의견을 제시하는 글을 고쳐 쓰는 것에 대해 바르게 말한 것은 무엇인가요?',ARRAY['K3-2-u6-X45','K3-2-u6-X28']::text[],false,'{"seq":4,"concept":"K3-2-u6-C34","difficulty":3,"kind":"mc","stem":"의견을 제시하는 글을 고쳐 쓰는 것에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"고쳐 쓰기는 글을 쓰는 동안 언제든 할 수 있고, 이유를 더하거나 쓴 내용을 빼도 된다","correct":true},{"t":"다 쓴 뒤 점검표를 본 다음 한 번만 고친다","mis":"K3-2-u6-X45"},{"t":"이미 쓴 문장은 빼면 안 되고 덧붙이기만 한다","mis":"K3-2-u6-X45"},{"t":"어색한 이유는 지우기만 하고 다른 이유는 쓰지 않는다","mis":"K3-2-u6-X28"}],"explanation":["고쳐 쓰기는 꼭 점검한 뒤에만 하는 것이 아니에요.","이유를 더해도, 쓴 내용을 빼도 괜찮아요.","글의 흐름이 전체적으로 잘 이어지게 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L10_challenge#5','kor',3,2,'u6','L10','tb_g3_2_kor_u6_L10_challenge','lesson_challenge','K3-2-u6-C24',3,'mc','auto','문제 상황마다 나온 여러 의견 가운데 가장 효과적인 의견을 고르려고 해요. 따져 볼 것을 바르게 모은 것은 무엇인가요?',ARRAY['K3-2-u6-X24','K3-2-u6-X27','K3-2-u6-X43']::text[],false,'{"seq":5,"concept":"K3-2-u6-C24","difficulty":3,"kind":"mc","stem":"문제 상황마다 나온 여러 의견 가운데 가장 효과적인 의견을 고르려고 해요. 따져 볼 것을 바르게 모은 것은 무엇인가요?","options":[{"t":"문제 상황을 잘 해결할 수 있는가 · 적절한 이유로 뒷받침했는가 · 실천 가능한가","correct":true},{"t":"누가 가장 먼저 냈는가 · 반에서 인기 있는 친구의 의견인가","mis":"K3-2-u6-X24"},{"t":"글씨가 예쁜가 · 글이 긴가","mis":"K3-2-u6-X27"},{"t":"하지 말자는 말이 들어 있는가","mis":"K3-2-u6-X43"}],"explanation":["여러 의견 가운데 하나를 고를 때에도 이유로 재요.","문제를 잘 해결하고, 실천할 수 있어야 해요.","고른 의견은 실천하고 결과를 함께 나누어요."],"asset":{"type":"passage","lines":["● 문제 상황을 잘 해결할 수 있는가?","● 적절한 이유를 들어 의견을 뒷받침했는가?","● 실천 가능한가?"],"title":"문제 상황을 해결하는 데 가장 효과적인 의견 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L10_challenge#6','kor',3,2,'u6','L10','tb_g3_2_kor_u6_L10_challenge','lesson_challenge','K3-2-u6-C30',3,'error','auto','「더 나은 학교」를 주제로 의견을 제시하는 글을 쓸 문제 상황을 골랐어요. 알맞지 않은 것은 무엇인가요?',ARRAY['K3-2-u6-X31','K3-2-u6-X32']::text[],false,'{"seq":6,"concept":"K3-2-u6-C30","difficulty":3,"kind":"error","stem":"「더 나은 학교」를 주제로 의견을 제시하는 글을 쓸 문제 상황을 골랐어요. 알맞지 않은 것은 무엇인가요?","options":[{"t":"어제 비가 와서 운동장이 젖었던 일","correct":true,"mis_target":"K3-2-u6-X31"},{"t":"쓰레기를 쓰레기통에 버리지 않아서 교실 환경이 더러워지는 일","mis":"K3-2-u6-X31"},{"t":"교실 안이나 복도에서 뛰어다니는 학생이 많은 일","mis":"K3-2-u6-X32"}],"explanation":["지난 날씨는 우리가 바꿀 수 없는 일이에요.","의견을 제시하는 글은 우리가 함께 바꿀 수 있는 문제를 골라요.","쓰레기, 뛰어다니기는 실천으로 해결할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L10_challenge#7','kor',3,2,'u6','L10','tb_g3_2_kor_u6_L10_challenge','lesson_challenge','K3-2-u6-C34',3,'mc','auto','붙임쪽지에 쓴 글을 친구들과 돌려 읽고 글 아래에 고쳐야 할 부분을 써 주어요. 써 줄 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X02','K3-2-u6-X30','K3-2-u6-X27']::text[],false,'{"seq":7,"concept":"K3-2-u6-C34","difficulty":3,"kind":"mc","stem":"붙임쪽지에 쓴 글을 친구들과 돌려 읽고 글 아래에 고쳐야 할 부분을 써 주어요. 써 줄 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“이유가 의견과 잘 이어져. 문단을 나누어 쓰면 더 읽기 쉬울 것 같아.”","correct":true},{"t":"“0점”","mis":"K3-2-u6-X02"},{"t":"“틀린 곳이 세 군데나 있어.”","mis":"K3-2-u6-X30"},{"t":"“글씨를 더 크게 써.”","mis":"K3-2-u6-X27"}],"explanation":["친구의 고쳐쓰기에 도움이 되는 말을 써 줘요.","잘된 점과 고치면 좋을 점을 함께 써요.","문단을 나누면 전하려는 내용이 더 잘 전달돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L10_challenge#8','kor',3,2,'u6','L10','tb_g3_2_kor_u6_L10_challenge','lesson_challenge','K3-2-u6-C24',4,'essay','teacher','「쓰레기를 쓰레기통에 버리지 않아서 교실 환경이 더러워진다.」는 문제 상황에 대해 서로 다른 의견 두 가지를 쓰고, 각 의견을 뒷받침하는 이유를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u6-C24","difficulty":4,"kind":"essay","stem":"「쓰레기를 쓰레기통에 버리지 않아서 교실 환경이 더러워진다.」는 문제 상황에 대해 서로 다른 의견 두 가지를 쓰고, 각 의견을 뒷받침하는 이유를 쓰세요.","answer_guide":{"answer":"예: 의견 1 — 쓰레기통을 친구들이 자주 지나다니는 곳으로 옮기자. 이유 — 쓰레기통이 가까우면 귀찮아하지 않고 바로 버리게 되기 때문이다. 의견 2 — 쓰레기를 잘 버리자는 표어를 만들어 붙이자. 이유 — 표어를 볼 때마다 쓰레기를 쓰레기통에 버려야겠다는 생각이 들기 때문이다.","scoring_points":["문제 상황에 어울리는 의견 두 가지를 썼는가","두 의견이 서로 다른가","각 의견을 뒷받침하는 이유를 썼는가"]},"explanation":["같은 문제 상황에도 의견은 여러 가지예요.","의견마다 그것을 받쳐 주는 이유가 있어야 해요.","여러 의견을 모으면 더 좋은 해결책을 찾을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L10_challenge#9','kor',3,2,'u6','L10','tb_g3_2_kor_u6_L10_challenge','lesson_challenge','K3-2-u6-C34',4,'essay','teacher','『국어활동』 86~87쪽 글의 이유 ㉰ 「스마트 기기는 우리에게 도움을 주기 때문입니다.」를 의견을 뒷받침하는 이유로 고쳐 쓰고, 왜 그렇게 고쳤는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u6-C34","difficulty":4,"kind":"essay","stem":"『국어활동』 86~87쪽 글의 이유 ㉰ 「스마트 기기는 우리에게 도움을 주기 때문입니다.」를 의견을 뒷받침하는 이유로 고쳐 쓰고, 왜 그렇게 고쳤는지 쓰세요.","answer_guide":{"answer":"예: 사용 시간을 정해 두면 그 시간 안에 꼭 필요한 일만 하게 되어 스마트 기기를 더 알차게 쓸 수 있기 때문입니다. — 처음 이유는 스마트 기기를 오래 써도 된다는 뜻으로 읽혀 의견과 맞지 않아서, 사용 시간을 정하면 좋아지는 점으로 바꾸었다.","scoring_points":["㉰를 의견과 이어지는 이유로 고쳐 썼는가","처음 이유가 왜 알맞지 않은지 썼는가","고친 이유가 사용 시간을 정하자는 의견을 받쳐 주는가"]},"explanation":["이어지지 않는 이유를 찾아요.","지우기만 하지 않고 받쳐 주는 이유로 바꾸어요.","고친 까닭도 함께 써요."],"asset":{"type":"passage","lines":["문제 상황 — 스마트 기기를 지나치게 오래 사용하는 학생이 많다.","의견 — 스마트 기기 사용 시간을 알맞게 정해 스스로 지키자.","이유 ㉮ 스마트 기기를 너무 오래 사용하면 시력이 나빠지기 때문입니다.","이유 ㉯ 스마트 기기에 빠져 숙제나 독서처럼 꼭 해야 하는 일들을 못 할 수도 있기 때문입니다.","이유 ㉰ 스마트 기기는 우리에게 도움을 주기 때문입니다."],"numbered":false,"title":"『국어활동』 87쪽 예시 답안에 실린 문제 상황·의견·이유"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L10_challenge#10','kor',3,2,'u6','L10','tb_g3_2_kor_u6_L10_challenge','lesson_challenge','K3-2-u6-C31',4,'mc','auto','쓴 글을 1학년 동생들이 읽을 수 있게 복도에 붙이기로 했어요. 고쳐 쓸 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X33','K3-2-u6-X26','K3-2-u6-X32']::text[],false,'{"seq":10,"concept":"K3-2-u6-C31","difficulty":4,"kind":"mc","stem":"쓴 글을 1학년 동생들이 읽을 수 있게 복도에 붙이기로 했어요. 고쳐 쓸 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"어려운 낱말은 쉬운 말로 바꾸고 문장을 짧게 고쳐 쓴다","correct":true},{"t":"읽을 사람이 바뀌어도 쓴 글을 그대로 붙인다","mis":"K3-2-u6-X33"},{"t":"더 길고 어려운 말로 바꾸어 쓴다","mis":"K3-2-u6-X26"},{"t":"동생들 가운데 뛰는 아이의 이름을 적는다","mis":"K3-2-u6-X32"}],"explanation":["읽을 사람이 바뀌면 쓸 말도 달라져요.","동생들이 알아듣기 쉬운 말로 바꾸어요.","누군가를 탓하는 내용은 넣지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L12_basic#1','kor',3,2,'u6','L12','tb_g3_2_kor_u6_L12_basic','lesson_basic','K3-2-u6-C35',1,'mc','auto','『국어』 280쪽처럼 의견을 제시하는 손 팻말을 만들어요. 의견과 이유를 함께 담은 팻말은 무엇인가요?',ARRAY['K3-2-u6-X34','K3-2-u6-X35','K3-2-u6-X32']::text[],false,'{"seq":1,"concept":"K3-2-u6-C35","difficulty":1,"kind":"mc","stem":"『국어』 280쪽처럼 의견을 제시하는 손 팻말을 만들어요. 의견과 이유를 함께 담은 팻말은 무엇인가요?","options":[{"t":"고운 말을 사용합시다. 나쁜 말을 쓰면 기분이 상하기 때문입니다.","correct":true},{"t":"고운 말!","mis":"K3-2-u6-X34"},{"t":"나쁜 말을 쓰면 기분이 상하고, 친구가 속상하고, 사이가 나빠지고, 교실 분위기도 나빠집니다.","mis":"K3-2-u6-X35"},{"t":"○○○ 나쁜 말 금지","mis":"K3-2-u6-X32"}],"explanation":["팻말에도 의견과 이유가 함께 있어야 해요.","의견만 쓰면 명령처럼 보이고, 이유만 길면 무엇을 하자는지 안 보여요.","누군가의 이름을 적어 탓하지 않아요."],"asset":{"type":"passage","lines":["팻말 ㉮ 쓰레기는 쓰레기통에 버립시다. 교실이 더러우면 건강에 좋지 않습니다.","팻말 ㉯ 고운 말을 사용합시다. 나쁜 말을 쓰면 기분이 상하기 때문입니다.","팻말 ㉰ 교실에서 뛰지 맙시다. 다른 친구와 부딪쳐 다칠 수 있기 때문입니다."],"numbered":false,"title":"의견을 제시하는 손 팻말 — 『국어』 280쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L12_basic#2','kor',3,2,'u6','L12','tb_g3_2_kor_u6_L12_basic','lesson_basic','K3-2-u6-C38',1,'mc','auto','『국어』 284쪽 기초 다지기예요. 「금방 (갈게, 갈께).」에서 바르게 쓴 낱말은 무엇인가요?',ARRAY['K3-2-u6-X38','K3-2-u6-X39']::text[],false,'{"seq":2,"concept":"K3-2-u6-C38","difficulty":1,"kind":"mc","stem":"『국어』 284쪽 기초 다지기예요. 「금방 (갈게, 갈께).」에서 바르게 쓴 낱말은 무엇인가요?","options":[{"t":"갈게","correct":true},{"t":"갈께","mis":"K3-2-u6-X38"},{"t":"갈가","mis":"K3-2-u6-X39"}],"explanation":["「갈게」는 [갈께]로 소리 나요.","하지만 약속하는 말은 소리 나는 대로 쓰지 않아요.","그래서 「갈게」로 써요."],"asset":{"type":"passage","lines":["금방 (갈게, 갈께).","일찍 (일어날걸, 일어날껄).","무엇을 (먹을가, 먹을까)?","왜 (늦을고, 늦을꼬)?"],"title":"기초 다지기 1 — 『국어』 284쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L12_basic#3','kor',3,2,'u6','L12','tb_g3_2_kor_u6_L12_basic','lesson_basic','K3-2-u6-C39',1,'mc','auto','「무엇을 (먹을가, 먹을까)?」에서 바르게 쓴 낱말은 무엇인가요?',ARRAY['K3-2-u6-X39']::text[],false,'{"seq":3,"concept":"K3-2-u6-C39","difficulty":1,"kind":"mc","stem":"「무엇을 (먹을가, 먹을까)?」에서 바르게 쓴 낱말은 무엇인가요?","options":[{"t":"먹을까","correct":true},{"t":"먹을가","mis":"K3-2-u6-X39"},{"t":"먹을게","mis":"K3-2-u6-X39"}],"explanation":["묻는 말에서는 「까」를 소리 나는 대로 써요.","「먹을가」로 쓰지 않아요.","「먹을게」는 약속하는 말이라 뜻이 달라져요."],"asset":{"type":"passage","lines":["금방 (갈게, 갈께).","일찍 (일어날걸, 일어날껄).","무엇을 (먹을가, 먹을까)?","왜 (늦을고, 늦을꼬)?"],"title":"기초 다지기 1 — 『국어』 284쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L12_basic#4','kor',3,2,'u6','L12','tb_g3_2_kor_u6_L12_basic','lesson_basic','K3-2-u6-C41',1,'mc','auto','『국어』 285쪽 글씨 쓰기 낱말 가운데 ㅝ(ㅜ+ㅓ)가 들어 있는 낱말은 무엇인가요?',ARRAY['K3-2-u6-X41']::text[],false,'{"seq":4,"concept":"K3-2-u6-C41","difficulty":1,"kind":"mc","stem":"『국어』 285쪽 글씨 쓰기 낱말 가운데 ㅝ(ㅜ+ㅓ)가 들어 있는 낱말은 무엇인가요?","options":[{"t":"궁궐","correct":true},{"t":"훼방","mis":"K3-2-u6-X41"},{"t":"뒷길","mis":"K3-2-u6-X41"},{"t":"바위","mis":"K3-2-u6-X41"}],"explanation":["「궐」에는 ㅜ와 ㅓ를 합친 ㅝ가 들어 있어요.","「훼」는 ㅞ, 「뒷」과 「위」는 ㅟ예요.","모음자의 모양에 주의하며 바르게 써요."],"asset":{"type":"passage","lines":["워낙 · 권리 · 궁궐 · 훼방 · 뒷길 · 귀여워하다","바위 위에 올라가니 뭐가 보이니?","궤짝 위에 귀여운 고양이가 낮잠을 자고 있다."],"title":"글씨 쓰기 — 『국어』 285쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L12_basic#5','kor',3,2,'u6','L12','tb_g3_2_kor_u6_L12_basic','lesson_basic','K3-2-u6-C36',2,'mc','auto','『국어』 281쪽 「만약 이랬더라면?」 역할놀이를 하는 차례로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X11','K3-2-u6-X36']::text[],false,'{"seq":5,"concept":"K3-2-u6-C36","difficulty":2,"kind":"mc","stem":"『국어』 281쪽 「만약 이랬더라면?」 역할놀이를 하는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"감동을 느낀 장면 떠올리기 → 인물의 말과 행동 바꾸기 → 이어질 장면 대본 쓰기 → 연습하고 발표하기","correct":true},{"t":"대본 쓰기 → 장면 떠올리기 → 발표하기 → 말과 행동 바꾸기","mis":"K3-2-u6-X11"},{"t":"작품 제목 바꾸기 → 등장인물 수 늘리기 → 발표하기","mis":"K3-2-u6-X36"},{"t":"발표하기 → 대본 쓰기 → 장면 떠올리기 → 말과 행동 바꾸기","mis":"K3-2-u6-X11"}],"explanation":["먼저 재미나 감동을 느낀 장면을 떠올려요.","그 장면 속 인물의 말과 행동을 더하거나 바꾸어요.","이어질 장면을 상상해 대본을 쓰고 연습해 발표해요."],"asset":{"type":"passage","lines":["1 자신이 본 작품에서 재미나 감동을 느낀 장면 떠올리기","2 장면 속 인물의 말과 행동을 추가하거나 바꾸기","3 이어질 장면을 상상해서 역할놀이 대본 쓰기","4 친구들과 역할놀이를 연습하고 발표하기"],"numbered":false,"title":"이런 활동 어때요 2 ‘만약 이랬더라면?’ 역할놀이 — 『국어』 281쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L12_basic#6','kor',3,2,'u6','L12','tb_g3_2_kor_u6_L12_basic','lesson_basic','K3-2-u6-C37',2,'mc','auto','우리 반 추천 (만화) 영화 한 줄 평 놀이를 해요. 한 줄 평으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X37','K3-2-u6-X06','K3-2-u6-X07']::text[],false,'{"seq":6,"concept":"K3-2-u6-C37","difficulty":2,"kind":"mc","stem":"우리 반 추천 (만화) 영화 한 줄 평 놀이를 해요. 한 줄 평으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「건전지 엄마」 — 위험 앞에서도 아이들부터 구하는 모습에 나도 용기가 생겼다.","correct":true},{"t":"「건전지 엄마」 — 별 다섯 개","mis":"K3-2-u6-X37"},{"t":"「건전지 엄마」 — 건전지 엄마가 비상벨을 울렸다.","mis":"K3-2-u6-X06"},{"t":"「건전지 엄마」 — 그냥 좋음","mis":"K3-2-u6-X07"}],"explanation":["한 줄 평에는 느낀 곳과 마음을 함께 담아요.","「나도 미운 오리 새끼처럼 백조가 될 날이 오면 좋겠다.」처럼요.","점수만, 줄거리만, 느낌만으로는 감상이 전해지지 않아요."],"asset":{"type":"passage","lines":["① 자신이 재미나 감동을 느끼며 감상한 작품의 포스터를 꾸민다.","② 제목과 한 줄 평을 남긴다.","③ 사물함 문이나 알림판에 붙여서 공유한다.","④ 그 작품을 본 사람은 한 줄 평에 공감할 경우 모양 붙임딱지를 붙여 준다.","한 줄 평 예: 나도 미운 오리 새끼처럼 백조가 될 날이 오면 좋겠다."],"numbered":false,"title":"우리 반 추천 (만화) 영화 한 줄 평 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L12_basic#7','kor',3,2,'u6','L12','tb_g3_2_kor_u6_L12_basic','lesson_basic','K3-2-u6-C40',2,'mc','auto','『국어』 284쪽 낱말 잇기예요. 「건전지」의 끝 글자로 시작하는 낱말은 무엇인가요?',ARRAY['K3-2-u6-X40']::text[],false,'{"seq":7,"concept":"K3-2-u6-C40","difficulty":2,"kind":"mc","stem":"『국어』 284쪽 낱말 잇기예요. 「건전지」의 끝 글자로 시작하는 낱말은 무엇인가요?","options":[{"t":"지역","correct":true},{"t":"건강","mis":"K3-2-u6-X40"},{"t":"전기","mis":"K3-2-u6-X40"}],"explanation":["「건전지」의 끝 글자는 「지」예요.","「지」로 시작하는 낱말은 「지역」이에요.","「건강」은 첫 글자 「건」으로 시작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L12_basic#8','kor',3,2,'u6','L12','tb_g3_2_kor_u6_L12_basic','lesson_basic','K3-2-u6-C21',2,'mc','auto','의견과 이유 카드 놀이에서 1모둠이 쓴 문장 가운데 이유를 나타낸 카드는 무엇인가요?',ARRAY['K3-2-u6-X21']::text[],false,'{"seq":8,"concept":"K3-2-u6-C21","difficulty":2,"kind":"mc","stem":"의견과 이유 카드 놀이에서 1모둠이 쓴 문장 가운데 이유를 나타낸 카드는 무엇인가요?","options":[{"t":"급식은 영양소가 풍부한 식사이기 때문이다.","correct":true},{"t":"급식 시간을 더 늘려야 한다.","mis":"K3-2-u6-X21"},{"t":"점심시간은 매우 중요하다.","mis":"K3-2-u6-X21"},{"t":"점심시간에는 운동장에 나가서 놀아야 한다.","mis":"K3-2-u6-X21"}],"explanation":["「……때문이다」로 끝나는 문장은 이유예요.","「……해야 한다」, 「……중요하다」는 생각을 나타낸 의견이에요.","카드를 골라 의견과 이유로 짧은 글을 구성해요."],"asset":{"type":"passage","lines":["1모둠 · 점심시간은 매우 중요하다.","1모둠 · 급식은 영양소가 풍부한 식사이기 때문이다.","1모둠 · 급식 시간을 더 늘려야 한다.","1모둠 · 놀기 위해서 식사를 너무 빨리하면 안 되기 때문이다.","2모둠 · 점심시간에는 운동장에 나가서 놀아야 한다.","2모둠 · 요즘 초등학생들은 야외 활동 시간이 부족하기 때문이다.","2모둠 · 점심시간을 더 늘려야 한다.","2모둠 · 식사를 소화하는 것도 다음 수업 시간에 좋기 때문이다."],"numbered":false,"title":"의견과 이유 카드 놀이 — 주제: 점심시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L12_basic#9','kor',3,2,'u6','L12','tb_g3_2_kor_u6_L12_basic','lesson_basic','K3-2-u6-C35',2,'mc','auto','『국어』 280쪽 손 팻말 만들기에서 여러 가지 모양의 손 팻말을 다 만든 뒤에 할 일은 무엇인가요?',ARRAY['K3-2-u6-X32','K3-2-u6-X02','K3-2-u6-X34']::text[],false,'{"seq":9,"concept":"K3-2-u6-C35","difficulty":2,"kind":"mc","stem":"『국어』 280쪽 손 팻말 만들기에서 여러 가지 모양의 손 팻말을 다 만든 뒤에 할 일은 무엇인가요?","options":[{"t":"완성한 손 팻말로 친구들과 함께 알림 활동을 한다","correct":true},{"t":"팻말에 친구 이름을 적어 붙인다","mis":"K3-2-u6-X32"},{"t":"팻말마다 점수를 매긴다","mis":"K3-2-u6-X02"},{"t":"팻말의 이유를 지우고 의견만 남긴다","mis":"K3-2-u6-X34"}],"explanation":["1 의견 생각하기 → 2 의견과 이유 쓰기 → 3 팻말 만들기예요.","4 완성한 팻말로 친구들과 알림 활동을 해요.","팻말은 알림 활동에 쓰여요."],"asset":{"type":"passage","lines":["1 아름답고 즐거운 교실을 만들기 위해 어떤 의견을 제시하면 좋을지 생각해 보기","2 자신의 의견과 그렇게 생각한 이유 써 보기","3 여러 가지 모양의 손 팻말로 만들어 보기","4 완성한 손 팻말로 친구들과 함께 알림 활동 해 보기"],"numbered":false,"title":"이런 활동 어때요 1 — 『국어』 280쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L12_basic#10','kor',3,2,'u6','L12','tb_g3_2_kor_u6_L12_basic','lesson_basic','K3-2-u6-C35',3,'essay','teacher','아름답고 즐거운 교실을 만들기 위한 손 팻말을 하나 만들려고 해요. 팻말에 쓸 의견과 이유를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u6-C35","difficulty":3,"kind":"essay","stem":"아름답고 즐거운 교실을 만들기 위한 손 팻말을 하나 만들려고 해요. 팻말에 쓸 의견과 이유를 쓰세요.","answer_guide":{"answer":"예: 의견 — 친구가 말할 때 끝까지 들어 줍시다. 이유 — 끝까지 들어 주면 친구가 존중받는다고 느끼기 때문입니다.","scoring_points":["아름답고 즐거운 교실과 이어지는 의견을 썼는가","「……합시다」처럼 의견이 한눈에 보이게 썼는가","의견을 뒷받침하는 이유를 썼는가"]},"explanation":["아름답고 즐거운 교실의 모습을 먼저 떠올려요.","의견을 짧고 분명하게 써요.","이유를 한 줄 붙여요."],"asset":{"type":"passage","lines":["1 아름답고 즐거운 교실을 만들기 위해 어떤 의견을 제시하면 좋을지 생각해 보기","2 자신의 의견과 그렇게 생각한 이유 써 보기","3 여러 가지 모양의 손 팻말로 만들어 보기","4 완성한 손 팻말로 친구들과 함께 알림 활동 해 보기"],"numbered":false,"title":"이런 활동 어때요 1 — 『국어』 280쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L12_challenge#1','kor',3,2,'u6','L12','tb_g3_2_kor_u6_L12_challenge','lesson_challenge','K3-2-u6-C38',2,'mc','auto','「일찍 (일어날걸, 일어날껄).」에서 바르게 쓴 낱말은 무엇인가요?',ARRAY['K3-2-u6-X38','K3-2-u6-X39']::text[],false,'{"seq":1,"concept":"K3-2-u6-C38","difficulty":2,"kind":"mc","stem":"「일찍 (일어날걸, 일어날껄).」에서 바르게 쓴 낱말은 무엇인가요?","options":[{"t":"일어날걸","correct":true},{"t":"일어날껄","mis":"K3-2-u6-X38"},{"t":"일어날까","mis":"K3-2-u6-X39"}],"explanation":["「일어날걸」은 [이러날껄]로 소리 나요.","되돌아보는 말은 소리 나는 대로 쓰지 않아요.","그래서 「일어날걸」로 써요."],"asset":{"type":"passage","lines":["금방 (갈게, 갈께).","일찍 (일어날걸, 일어날껄).","무엇을 (먹을가, 먹을까)?","왜 (늦을고, 늦을꼬)?"],"title":"기초 다지기 1 — 『국어』 284쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L12_challenge#2','kor',3,2,'u6','L12','tb_g3_2_kor_u6_L12_challenge','lesson_challenge','K3-2-u6-C39',2,'mc','auto','「왜 (늦을고, 늦을꼬)?」에서 바르게 쓴 낱말은 무엇인가요?',ARRAY['K3-2-u6-X39','K3-2-u6-X38']::text[],false,'{"seq":2,"concept":"K3-2-u6-C39","difficulty":2,"kind":"mc","stem":"「왜 (늦을고, 늦을꼬)?」에서 바르게 쓴 낱말은 무엇인가요?","options":[{"t":"늦을꼬","correct":true},{"t":"늦을고","mis":"K3-2-u6-X39"},{"t":"늦을께","mis":"K3-2-u6-X38"}],"explanation":["묻는 말이에요.","묻는 말에서는 「꼬」를 소리 나는 대로 써요.","그래서 「늦을꼬」로 써요."],"asset":{"type":"passage","lines":["금방 (갈게, 갈께).","일찍 (일어날걸, 일어날껄).","무엇을 (먹을가, 먹을까)?","왜 (늦을고, 늦을꼬)?"],"title":"기초 다지기 1 — 『국어』 284쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L12_challenge#3','kor',3,2,'u6','L12','tb_g3_2_kor_u6_L12_challenge','lesson_challenge','K3-2-u6-C39',3,'mc','auto','『국어』 284쪽에서 배운 규칙이에요. 소리 나는 대로 쓰는 것은 무엇인가요?',ARRAY['K3-2-u6-X38','K3-2-u6-X39']::text[],false,'{"seq":3,"concept":"K3-2-u6-C39","difficulty":3,"kind":"mc","stem":"『국어』 284쪽에서 배운 규칙이에요. 소리 나는 대로 쓰는 것은 무엇인가요?","options":[{"t":"묻는 말 「먹을까」, 「늦을꼬」의 「까」와 「꼬」","correct":true},{"t":"약속하는 말 「갈게」의 「게」","mis":"K3-2-u6-X38"},{"t":"되돌아보는 말 「일어날걸」의 「걸」","mis":"K3-2-u6-X38"},{"t":"「ㄹ」 뒤에 오는 모든 소리","mis":"K3-2-u6-X39"}],"explanation":["「갈게」, 「일어날걸」은 된소리로 나도 그대로 써요.","묻는 말 「먹을까」, 「늦을꼬」는 소리 나는 대로 써요.","말의 뜻(약속·되돌아봄·물음)을 먼저 보아요."],"asset":{"type":"passage","lines":["금방 (갈게, 갈께).","일찍 (일어날걸, 일어날껄).","무엇을 (먹을가, 먹을까)?","왜 (늦을고, 늦을꼬)?"],"title":"기초 다지기 1 — 『국어』 284쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L12_challenge#4','kor',3,2,'u6','L12','tb_g3_2_kor_u6_L12_challenge','lesson_challenge','K3-2-u6-C41',3,'error','auto','글씨 쓰기 낱말을 살펴보고 친구들이 한 말이에요. 알맞지 않은 말은 무엇인가요?',ARRAY['K3-2-u6-X41']::text[],false,'{"seq":4,"concept":"K3-2-u6-C41","difficulty":3,"kind":"error","stem":"글씨 쓰기 낱말을 살펴보고 친구들이 한 말이에요. 알맞지 않은 말은 무엇인가요?","options":[{"t":"“「훼방」의 「훼」는 ㅜ와 ㅓ를 합쳐 써.”","correct":true,"mis_target":"K3-2-u6-X41"},{"t":"“「권리」의 「권」에는 ㅝ가 들어 있어.”","mis":"K3-2-u6-X41"},{"t":"“「귀여워하다」의 「귀」에는 ㅟ가 들어 있어.”","mis":"K3-2-u6-X41"}],"explanation":["「훼」에는 ㅜ와 ㅔ를 합친 ㅞ가 들어 있어요.","ㅝ는 ㅜ+ㅓ, ㅟ는 ㅜ+ㅣ예요.","「궤짝」의 「궤」도 ㅞ예요."],"asset":{"type":"passage","lines":["워낙 · 권리 · 궁궐 · 훼방 · 뒷길 · 귀여워하다","바위 위에 올라가니 뭐가 보이니?","궤짝 위에 귀여운 고양이가 낮잠을 자고 있다."],"title":"글씨 쓰기 — 『국어』 285쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L12_challenge#5','kor',3,2,'u6','L12','tb_g3_2_kor_u6_L12_challenge','lesson_challenge','K3-2-u6-C36',3,'mc','auto','「만약 이랬더라면?」 역할놀이에서 장면 속 인물의 말과 행동을 바꾼 예로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X36']::text[],false,'{"seq":5,"concept":"K3-2-u6-C36","difficulty":3,"kind":"mc","stem":"「만약 이랬더라면?」 역할놀이에서 장면 속 인물의 말과 행동을 바꾼 예로 가장 알맞은 것은 무엇인가요?","options":[{"t":"신비가 과자를 나누어 줄 때 마리와 기동이가 “고마워!”라고 말했더라면 하고 바꾸어 본다","correct":true},{"t":"드라마 제목을 다른 이름으로 바꾼다","mis":"K3-2-u6-X36"},{"t":"드라마 길이를 두 배로 늘린다","mis":"K3-2-u6-X36"},{"t":"인물 이름을 모두 내 이름으로 바꾼다","mis":"K3-2-u6-X36"}],"explanation":["재미나 감동을 느낀 장면을 골라요.","그 장면 속 인물의 말과 행동을 더하거나 바꾸어요.","그러면 이어질 장면이 어떻게 달라질지 상상할 수 있어요."],"asset":{"type":"passage","lines":["1 자신이 본 작품에서 재미나 감동을 느낀 장면 떠올리기","2 장면 속 인물의 말과 행동을 추가하거나 바꾸기","3 이어질 장면을 상상해서 역할놀이 대본 쓰기","4 친구들과 역할놀이를 연습하고 발표하기"],"numbered":false,"title":"이런 활동 어때요 2 ‘만약 이랬더라면?’ 역할놀이 — 『국어』 281쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L12_challenge#6','kor',3,2,'u6','L12','tb_g3_2_kor_u6_L12_challenge','lesson_challenge','K3-2-u6-C37',3,'mc','auto','한 줄 평 놀이 ④에서 그 작품을 본 사람이 한 줄 평에 공감할 때 하는 일은 무엇인가요?',ARRAY['K3-2-u6-X37','K3-2-u6-X03','K3-2-u6-X06']::text[],false,'{"seq":6,"concept":"K3-2-u6-C37","difficulty":3,"kind":"mc","stem":"한 줄 평 놀이 ④에서 그 작품을 본 사람이 한 줄 평에 공감할 때 하는 일은 무엇인가요?","options":[{"t":"모양 붙임딱지를 붙여 준다","correct":true},{"t":"한 줄 평 옆에 점수를 크게 적는다","mis":"K3-2-u6-X37"},{"t":"내 감상과 다르면 틀렸다고 적는다","mis":"K3-2-u6-X03"},{"t":"줄거리를 길게 덧붙여 쓴다","mis":"K3-2-u6-X06"}],"explanation":["포스터와 한 줄 평을 알림판에 붙여 함께 보아요.","공감하면 모양 붙임딱지를 붙여 줘요.","서로 감상한 작품의 재미나 감동을 나누는 놀이예요."],"asset":{"type":"passage","lines":["① 자신이 재미나 감동을 느끼며 감상한 작품의 포스터를 꾸민다.","② 제목과 한 줄 평을 남긴다.","③ 사물함 문이나 알림판에 붙여서 공유한다.","④ 그 작품을 본 사람은 한 줄 평에 공감할 경우 모양 붙임딱지를 붙여 준다.","한 줄 평 예: 나도 미운 오리 새끼처럼 백조가 될 날이 오면 좋겠다."],"numbered":false,"title":"우리 반 추천 (만화) 영화 한 줄 평 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L12_challenge#7','kor',3,2,'u6','L12','tb_g3_2_kor_u6_L12_challenge','lesson_challenge','K3-2-u6-C21',3,'mc','auto','의견과 이유 카드로 구성한 짧은 글이에요. 이 글의 의견은 무엇인가요?',ARRAY['K3-2-u6-X21']::text[],false,'{"seq":7,"concept":"K3-2-u6-C21","difficulty":3,"kind":"mc","stem":"의견과 이유 카드로 구성한 짧은 글이에요. 이 글의 의견은 무엇인가요?","options":[{"t":"점심시간은 매우 중요하다.","correct":true},{"t":"급식은 영양소가 풍부한 식사이기 때문이다.","mis":"K3-2-u6-X21"},{"t":"그리고 운동장에 나가서 놀아야 하기 때문이다.","mis":"K3-2-u6-X21"}],"explanation":["첫 문장이 글쓴이의 생각(의견)이에요.","뒤의 두 문장은 「……때문이다」로 끝나는 이유예요.","2모둠이 의견으로 쓴 「운동장에 나가서 놀아야 한다」를 이유로 바꾸어 썼어요."],"asset":{"type":"passage","lines":["점심시간은 매우 중요하다.","급식은 영양소가 풍부한 식사이기 때문이다.","그리고 운동장에 나가서 놀아야 하기 때문이다."],"title":"카드를 골라 구성한 짧은 글 (예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L12_challenge#8','kor',3,2,'u6','L12','tb_g3_2_kor_u6_L12_challenge','lesson_challenge','K3-2-u6-C36',4,'essay','teacher','「레오의 특별한 꿈」, 「건전지 엄마」, 「신통방통 니 맘 내 맘 계산기」 가운데 하나에서 재미나 감동을 느낀 장면을 골라, 인물의 말이나 행동을 바꾸고 이어질 장면의 대본을 두세 마디 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u6-C36","difficulty":4,"kind":"essay","stem":"「레오의 특별한 꿈」, 「건전지 엄마」, 「신통방통 니 맘 내 맘 계산기」 가운데 하나에서 재미나 감동을 느낀 장면을 골라, 인물의 말이나 행동을 바꾸고 이어질 장면의 대본을 두세 마디 쓰세요.","answer_guide":{"answer":"예: 작품 — 「신통방통 니 맘 내 맘 계산기」. 바꾼 장면 — 과자를 받은 마리가 “고마워, 신비야!”라고 말한다. 대본 — 신비: “맛있게 먹어. 내일 또 가져올게.” 기동: “그럼 내일은 내가 치킨을 나눠 줄게!” 신비: (웃으며) “우리 모두 단짝이다!”","scoring_points":["재미나 감동을 느낀 장면을 골랐는가","인물의 말이나 행동을 바꾸거나 더했는가","이어질 장면을 대본으로 썼는가"]},"explanation":["마음이 움직인 장면을 골라요.","인물의 말과 행동을 바꾸어 보아요.","이어질 장면을 상상해 역할놀이 대본을 써요."],"asset":{"type":"passage","lines":["1 자신이 본 작품에서 재미나 감동을 느낀 장면 떠올리기","2 장면 속 인물의 말과 행동을 추가하거나 바꾸기","3 이어질 장면을 상상해서 역할놀이 대본 쓰기","4 친구들과 역할놀이를 연습하고 발표하기"],"numbered":false,"title":"이런 활동 어때요 2 ‘만약 이랬더라면?’ 역할놀이 — 『국어』 281쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L12_challenge#9','kor',3,2,'u6','L12','tb_g3_2_kor_u6_L12_challenge','lesson_challenge','K3-2-u6-C37',4,'essay','teacher','자신이 재미나 감동을 느끼며 감상한 (만화) 영화나 드라마를 하나 골라 한 줄 평을 쓰고, 그렇게 쓴 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u6-C37","difficulty":4,"kind":"essay","stem":"자신이 재미나 감동을 느끼며 감상한 (만화) 영화나 드라마를 하나 골라 한 줄 평을 쓰고, 그렇게 쓴 까닭을 쓰세요.","answer_guide":{"answer":"예: 「건전지 엄마」 — 말 한마디 없어도 아이들을 지키려는 마음이 다 보였다. 까닭 — 대사가 없는데도 위험을 무릅쓰고 나서는 표정과 몸짓만으로 건전지 엄마의 다급하고 용감한 마음이 느껴져 감동했기 때문이다.","scoring_points":["작품 제목을 썼는가","느낀 곳과 마음을 담은 한 줄 평을 썼는가","그렇게 쓴 까닭을 썼는가"]},"explanation":["한 줄 평은 짧지만 느낀 곳과 마음이 보여야 해요.","점수나 줄거리만 쓰지 않아요.","까닭을 들으면 친구도 공감할 수 있어요."],"asset":{"type":"passage","lines":["① 자신이 재미나 감동을 느끼며 감상한 작품의 포스터를 꾸민다.","② 제목과 한 줄 평을 남긴다.","③ 사물함 문이나 알림판에 붙여서 공유한다.","④ 그 작품을 본 사람은 한 줄 평에 공감할 경우 모양 붙임딱지를 붙여 준다.","한 줄 평 예: 나도 미운 오리 새끼처럼 백조가 될 날이 오면 좋겠다."],"numbered":false,"title":"우리 반 추천 (만화) 영화 한 줄 평 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_L12_challenge#10','kor',3,2,'u6','L12','tb_g3_2_kor_u6_L12_challenge','lesson_challenge','K3-2-u6-C40',4,'mc','auto','「건전지」의 첫 글자로 시작하는 낱말과 끝 글자로 시작하는 낱말을 바르게 짝지은 것은 무엇인가요?',ARRAY['K3-2-u6-X40']::text[],false,'{"seq":10,"concept":"K3-2-u6-C40","difficulty":4,"kind":"mc","stem":"「건전지」의 첫 글자로 시작하는 낱말과 끝 글자로 시작하는 낱말을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"건강 · 지역","correct":true},{"t":"전기 · 지구","mis":"K3-2-u6-X40"},{"t":"건강 · 전화","mis":"K3-2-u6-X40"},{"t":"지우개 · 건물","mis":"K3-2-u6-X40"}],"explanation":["첫 글자는 「건」, 끝 글자는 「지」예요.","「건」으로 시작하는 「건강」, 「지」로 시작하는 「지역」이에요.","가운데 글자 「전」으로 잇지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_a#1','kor',3,2,'u6','','tb_g3_2_kor_u6_review_a','unit_review','K3-2-u6-C1',1,'mc','auto','6단원 「감상과 표현의 즐거움」에서 배운 두 가지를 바르게 고른 것은 무엇인가요?',ARRAY['K3-2-u6-X01','K3-2-u6-X47','K3-2-u6-X02']::text[],false,'{"seq":1,"concept":"K3-2-u6-C1","difficulty":1,"kind":"mc","stem":"6단원 「감상과 표현의 즐거움」에서 배운 두 가지를 바르게 고른 것은 무엇인가요?","options":[{"t":"재미나 감동을 느끼며 작품 감상하기 · 의견을 제시하는 글 쓰기","correct":true},{"t":"시 외우기 · 받아쓰기","mis":"K3-2-u6-X01"},{"t":"국어사전 찾기 · 발표하기","mis":"K3-2-u6-X47"},{"t":"줄거리 외우기 · 작품에 점수 매기기","mis":"K3-2-u6-X02"}],"explanation":["소단원 1은 재미나 감동을 느끼며 작품을 감상하는 공부예요.","소단원 2는 의견을 제시하는 글을 쓰는 공부예요.","감상은 받아들이는 일, 의견 글은 내 생각과 이유를 내놓는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_a#2','kor',3,2,'u6','','tb_g3_2_kor_u6_review_a','unit_review','K3-2-u6-C4',1,'mc','auto','「레오의 특별한 꿈」을 두고 세 친구가 서로 다른 장면을 말했어요. 이에 대한 생각으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X03','K3-2-u6-X05','K3-2-u6-X13']::text[],false,'{"seq":2,"concept":"K3-2-u6-C4","difficulty":1,"kind":"mc","stem":"「레오의 특별한 꿈」을 두고 세 친구가 서로 다른 장면을 말했어요. 이에 대한 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"세 친구 모두 작품 속 장면을 근거로 말한 제 감상이다","correct":true},{"t":"감동적이라고 한 친구만 옳고 나머지는 틀렸다","mis":"K3-2-u6-X03"},{"t":"한 친구만 작품을 제대로 읽었다","mis":"K3-2-u6-X05"},{"t":"작품마다 감동할 장면은 하나뿐이다","mis":"K3-2-u6-X13"}],"explanation":["세 친구는 안쓰러운 장면, 재미있는 장면, 감동적인 장면을 말했어요.","모두 작품 안에 있는 장면이에요.","느낀 부분이 달라도 모두 제 감상이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"1학기 때 교과서에서 읽은 「레오의 특별한 꿈」이 어때?"},{"who":"친구 2","text":"가짜 ‘델’을 달고 있다고 친구들에게 놀림받은 레오가 무척 안쓰러웠어. 나도 친구들에게 놀림받았을 때 속상했거든."},{"who":"친구 3","text":"신비한 능력이 없어도 좋으니까 ‘델’ 모양만이라도 만들어 달라고 마법사에게 조르는 레오의 모습이 조금은 재미있게 느껴졌어. 부모님께 물건을 사 달라고 부탁하는 내 모습 같았거든."},{"who":"친구 1","text":"그랬구나. 나는 레오가 진짜 꿈에 대해 생각하자 진짜 ‘델’이 생긴 장면이 감동적이었어. 나도 꿈을 이루기 위해 열심히 노력해야겠다고 생각했어."},{"who":"친구 2","text":"같은 작품을 보고도 재미나 감동을 느낀 부분이 다를 수 있구나."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_a#3','kor',3,2,'u6','','tb_g3_2_kor_u6_review_a','unit_review','K3-2-u6-C11',1,'mc','auto','하준이는 「달려가는 건전지 엄마의 표정을 보고 다급한 상황이 실감 났어.」라고 했어요. 하준이가 쓴 감상 방법은 무엇인가요?',ARRAY['K3-2-u6-X12','K3-2-u6-X01']::text[],false,'{"seq":3,"concept":"K3-2-u6-C11","difficulty":1,"kind":"mc","stem":"하준이는 「달려가는 건전지 엄마의 표정을 보고 다급한 상황이 실감 났어.」라고 했어요. 하준이가 쓴 감상 방법은 무엇인가요?","options":[{"t":"인물의 실감 나는 표정이나 말투에 주의하며 보기","correct":true},{"t":"배경 음악이나 효과음에 집중하며 보기","mis":"K3-2-u6-X12"},{"t":"주제나 교훈을 떠올리며 보기","mis":"K3-2-u6-X12"},{"t":"줄거리를 외우며 보기","mis":"K3-2-u6-X01"}],"explanation":["하준이는 인물의 표정을 보았어요.","표정에서 다급한 상황을 실감했어요.","감상 방법은 여러 가지예요."],"asset":{"type":"speech","turns":[{"who":"하준","text":"아이들을 구하려고 달려가는 건전지 엄마의 표정을 보고 다급한 상황이 실감 났어."},{"who":"예서","text":"유치원 아이들이 낮잠 잘 때 평화로운 음악이 흐르다가 갑자기 멈춰서 무슨 일이 생길 것만 같았어."},{"who":"시윤","text":"아이들을 구한 건전지 엄마처럼 나도 용기 있게 행동하고 싶어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_a#4','kor',3,2,'u6','','tb_g3_2_kor_u6_review_a','unit_review','K3-2-u6-C43',1,'mc','auto','신비가 니 맘 내 맘 계산기로 마음을 확인한 사람은 누구누구인가요?',ARRAY['K3-2-u6-X11']::text[],false,'{"seq":4,"concept":"K3-2-u6-C43","difficulty":1,"kind":"mc","stem":"신비가 니 맘 내 맘 계산기로 마음을 확인한 사람은 누구누구인가요?","options":[{"t":"마리, 기동이, 아빠","correct":true},{"t":"용용이 혼자","mis":"K3-2-u6-X11"},{"t":"슈퍼에 온 손님들","mis":"K3-2-u6-X11"},{"t":"선생님과 교장 선생님","mis":"K3-2-u6-X11"}],"explanation":["신비는 계산기로 친구들과 가족의 마음을 들여다보았어요.","마리, 기동이, 아빠의 마음이에요.","그리고 그들의 진심을 깨달았어요."],"asset":{"type":"passage","lines":["등장인물 — 신비, 용용이(살아남은 단 하나의 공룡), 아빠, 마리, 기동","(간추림) 신비는 주변 사람들의 행동을 자기중심적으로 생각해","친구들의 마음을 오해했다.","(간추림) 용용이가 마법으로 ‘니 맘 내 맘 계산기’를 주었다.","(간추림) 신비는 계산기로 친구들과 가족의 진심을 깨닫고 반성했다."],"title":"「신통방통 니 맘 내 맘 계산기」 간추린 줄거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_a#5','kor',3,2,'u6','','tb_g3_2_kor_u6_review_a','unit_review','K3-2-u6-C19',1,'mc','auto','다음 가운데 드라마에서 있었던 일(사실)을 쓴 문장은 무엇인가요?',ARRAY['K3-2-u6-X19']::text[],false,'{"seq":5,"concept":"K3-2-u6-C19","difficulty":1,"kind":"mc","stem":"다음 가운데 드라마에서 있었던 일(사실)을 쓴 문장은 무엇인가요?","options":[{"t":"마리는 신비에게 화장실을 양보해 주었습니다.","correct":true},{"t":"신비처럼 친구들의 마음을 이해해 주어야 합니다.","mis":"K3-2-u6-X19"},{"t":"우리 모두 서로 배려하면 좋겠습니다.","mis":"K3-2-u6-X19"},{"t":"다투기 전에 상대의 처지를 생각해 보자.","mis":"K3-2-u6-X19"}],"explanation":["있었던 일을 그대로 쓴 것이 사실이에요.","「……해야 합니다」, 「……면 좋겠습니다」, 「……하자」는 의견이에요.","사실과 의견을 가려 읽어요."],"asset":{"type":"passage","lines":["㉮ 신비는 친구들에게 과자를 나누어 주었습니다.","㉯ 마리는 신비에게 화장실을 양보해 주었습니다.","㉰ 신비는 니 맘 내 맘 계산기로 친구들의 마음을 들여다보았습니다.","㉱ 신비처럼 다른 친구들의 마음을 이해해 주어야 합니다."],"numbered":false,"title":"드라마를 보고 쓴 네 문장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_a#6','kor',3,2,'u6','','tb_g3_2_kor_u6_review_a','unit_review','K3-2-u6-C20',1,'mc','auto','의견을 제시하는 글에 써야 할 것을 바르게 모은 것은 무엇인가요?',ARRAY['K3-2-u6-X27','K3-2-u6-X20','K3-2-u6-X47']::text[],false,'{"seq":6,"concept":"K3-2-u6-C20","difficulty":1,"kind":"mc","stem":"의견을 제시하는 글에 써야 할 것을 바르게 모은 것은 무엇인가요?","options":[{"t":"문제 상황, 자신의 의견, 그렇게 생각한 이유","correct":true},{"t":"제목과 그림만","mis":"K3-2-u6-X27"},{"t":"의견만","mis":"K3-2-u6-X20"},{"t":"줄거리와 느낌","mis":"K3-2-u6-X47"}],"explanation":["무엇이 문제인지 써요.","어떻게 하면 좋을지 의견을 써요.","왜 그렇게 생각하는지 이유를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_a#7','kor',3,2,'u6','','tb_g3_2_kor_u6_review_a','unit_review','K3-2-u6-C26',1,'mc','auto','의견을 제시하는 글을 고쳐 쓸 때 확인할 것은 무엇인가요?',ARRAY['K3-2-u6-X27','K3-2-u6-X26']::text[],false,'{"seq":7,"concept":"K3-2-u6-C26","difficulty":1,"kind":"mc","stem":"의견을 제시하는 글을 고쳐 쓸 때 확인할 것은 무엇인가요?","options":[{"t":"의견을 뒷받침하는 적절한 이유를 썼는지","correct":true},{"t":"글이 몇 쪽인지","mis":"K3-2-u6-X27"},{"t":"글씨를 진하게 썼는지","mis":"K3-2-u6-X27"},{"t":"어려운 낱말이 많은지","mis":"K3-2-u6-X26"}],"explanation":["의견, 이유, 문제 해결을 살펴봐요.","내용이 어색한 곳, 띄어쓰기와 맞춤법도 보아요.","글의 길이나 글씨는 고쳐 쓸 거리가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_a#8','kor',3,2,'u6','','tb_g3_2_kor_u6_review_a','unit_review','K3-2-u6-C38',1,'mc','auto','「내일은 학교에 일찍 (갈게, 갈께).」에서 바르게 쓴 낱말은 무엇인가요?',ARRAY['K3-2-u6-X38','K3-2-u6-X39']::text[],false,'{"seq":8,"concept":"K3-2-u6-C38","difficulty":1,"kind":"mc","stem":"「내일은 학교에 일찍 (갈게, 갈께).」에서 바르게 쓴 낱말은 무엇인가요?","options":[{"t":"갈게","correct":true},{"t":"갈께","mis":"K3-2-u6-X38"},{"t":"갈가","mis":"K3-2-u6-X39"}],"explanation":["약속하는 말이에요.","[갈께]로 소리 나도 「갈게」로 써요.","소리 나는 대로 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_a#9','kor',3,2,'u6','','tb_g3_2_kor_u6_review_a','unit_review','K3-2-u6-C12',2,'mc','auto','『국어활동』 85쪽이에요. 단우가 재미있었다고 한 부분은 무엇인가요?',ARRAY['K3-2-u6-X11','K3-2-u6-X04']::text[],false,'{"seq":9,"concept":"K3-2-u6-C12","difficulty":2,"kind":"mc","stem":"『국어활동』 85쪽이에요. 단우가 재미있었다고 한 부분은 무엇인가요?","options":[{"t":"눈을 맞은 친구들이 집에 가는 것을 눈 세상을 데리고 간다고 표현한 것","correct":true},{"t":"눈이 펑펑 내린다고 표현한 부분","mis":"K3-2-u6-X11"},{"t":"눈을 맞은 친구들을 눈사람으로 표현한 것","mis":"K3-2-u6-X11"},{"t":"시에 없는 눈싸움 장면","mis":"K3-2-u6-X04"}],"explanation":["정운이는 「펑펑」, 유연이는 「눈사람」을 재미있어했어요.","단우는 「눈 세상 데리고 간다」를 재미있어했어요.","세 친구가 느낀 부분이 모두 달라요."],"asset":{"type":"speech","turns":[{"who":"정운","text":"눈이 (    ) 내린다고 표현한 부분이 재미있었어."},{"who":"유연","text":"눈을 맞은 친구들을 (    )(으)로 표현한 것이 재미있었어."},{"who":"단우","text":"눈을 맞은 친구들이 집에 가는 것을 (    )을/를 데리고 간다고 표현한 것이 재미있었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_a#10','kor',3,2,'u6','','tb_g3_2_kor_u6_review_a','unit_review','K3-2-u6-C42',2,'mc','auto','건전지 엄마가 있는 힘껏 비상벨을 울린 까닭은 무엇인가요?',ARRAY['K3-2-u6-X10','K3-2-u6-X11','K3-2-u6-X04']::text[],false,'{"seq":10,"concept":"K3-2-u6-C42","difficulty":2,"kind":"mc","stem":"건전지 엄마가 있는 힘껏 비상벨을 울린 까닭은 무엇인가요?","options":[{"t":"잠든 아이들을 깨워 불이 난 곳에서 무사히 대피하게 하려고","correct":true},{"t":"아이들과 놀고 싶어서","mis":"K3-2-u6-X10"},{"t":"비상벨이 고장 났는지 알아보려고","mis":"K3-2-u6-X11"},{"t":"건전지를 바꾸려고","mis":"K3-2-u6-X04"}],"explanation":["건전지 엄마는 타는 냄새를 느꼈어요.","잠든 아이들이 위험했어요.","비상벨을 듣고 아이들은 무사히 대피했어요."],"asset":{"type":"passage","lines":["① 어린이집에서 낮잠 시간에 아이들이 모두 잠들었습니다.","② 건전지 엄마는 타는 냄새가 나는 것을 느꼈습니다.","③ 건전지 엄마는 위험을 무릅쓰고 아이들을 구하려고 나섰습니다.","④ 건전지 엄마는 있는 힘껏 비상벨을 울렸습니다.","⑤ 비상벨을 들은 아이들은 무사히 대피하고,","   건전지 엄마도 집에 와서 행복하게 잠들었습니다."],"numbered":false,"title":"「건전지 엄마」 장면을 보고 요약하여 말하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_a#11','kor',3,2,'u6','','tb_g3_2_kor_u6_review_a','unit_review','K3-2-u6-C14',2,'mc','auto','기동이는 「인심 썼다. 자! 먼저 먹어.」라며 치킨을 신비에게 양보했어요. 이 말과 행동에서 알 수 있는 것은 무엇인가요?',ARRAY['K3-2-u6-X10','K3-2-u6-X15','K3-2-u6-X46']::text[],false,'{"seq":11,"concept":"K3-2-u6-C14","difficulty":2,"kind":"mc","stem":"기동이는 「인심 썼다. 자! 먼저 먹어.」라며 치킨을 신비에게 양보했어요. 이 말과 행동에서 알 수 있는 것은 무엇인가요?","options":[{"t":"친구 신비를 배려하는 마음","correct":true},{"t":"치킨을 싫어하는 마음","mis":"K3-2-u6-X10"},{"t":"드라마에 적혀 있지 않아 알 수 없다","mis":"K3-2-u6-X15"},{"t":"신비를 놀리려는 마음","mis":"K3-2-u6-X46"}],"explanation":["맛있는 치킨을 친구에게 먼저 주었어요.","그 행동에서 배려심을 느낄 수 있어요.","소중히 여기는 것은 말과 행동에서 읽어요."],"asset":{"type":"speech","turns":[{"who":"신비","text":"뭐야? 별로 안 고마운 거야?"},{"who":"기동","text":"인심 썼다. 자! 먼저 먹어."},{"who":"아빠","text":"아빠는 신비가 먹는 것만 봐도 배가 불러요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_a#12','kor',3,2,'u6','','tb_g3_2_kor_u6_review_a','unit_review','K3-2-u6-C21',2,'mc','auto','「건강하고 행복한 급식 시간」에서 글쓴이의 의견은 무엇인가요?',ARRAY['K3-2-u6-X21','K3-2-u6-X19']::text[],false,'{"seq":12,"concept":"K3-2-u6-C21","difficulty":2,"kind":"mc","stem":"「건강하고 행복한 급식 시간」에서 글쓴이의 의견은 무엇인가요?","options":[{"t":"음식을 골고루 먹어야 한다","correct":true},{"t":"급식 시간에 편식을 하는 친구들이 있다","mis":"K3-2-u6-X21"},{"t":"우리 몸에 필요한 영양소를 얻을 수 있다","mis":"K3-2-u6-X21"},{"t":"김치볶음밥을 맛있게 먹었다","mis":"K3-2-u6-X19"}],"explanation":["「……라고 생각합니다」가 붙은 문장을 찾아요.","편식 친구들은 문제 상황, 영양소는 이유예요.","김치볶음밥은 이유를 받쳐 주는 경험이에요."],"asset":{"type":"passage","lines":["급식 시간에 편식을 하는 친구들이 종종 있습니다.","하지만 저는 음식을 골고루 먹어야 한다고 생각합니다.","첫째, 음식을 골고루 먹어야 우리 몸에 필요한 여러 영양소를 얻을 수 있습니다.","(간추림) 근육에는 고기·생선·콩, 힘에는 곡물, 몸의 조절에는 과일·채소.","둘째, 자신이 경험해 보지 못한 다양한 음식을 즐길 수 있습니다.","(간추림) 김치를 싫어했는데 김치볶음밥을 먹은 뒤 김치를 좋아하게 되었다.","음식을 골고루 먹으면서 건강하고 행복한 급식 시간을 만들어 봅시다."],"title":"「건강하고 행복한 급식 시간」 — 『국어』 270쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_a#13','kor',3,2,'u6','','tb_g3_2_kor_u6_review_a','unit_review','K3-2-u6-C23',2,'blank','auto','『국어』 271쪽 의견과 이유가 적절한지 알아보는 방법이에요. ㉡에 알맞은 낱말은 무엇인가요?',ARRAY['K3-2-u6-X22']::text[],false,'{"seq":13,"concept":"K3-2-u6-C23","difficulty":2,"kind":"blank","stem":"『국어』 271쪽 의견과 이유가 적절한지 알아보는 방법이에요. ㉡에 알맞은 낱말은 무엇인가요?","options":[{"t":"다양","correct":true},{"t":"뒷받침","mis":"K3-2-u6-X22"},{"t":"도움","mis":"K3-2-u6-X22"}],"explanation":["다양한 이유를 중복되지 않게 제시해야 해요.","㉠ 뒷받침 · ㉡ 다양 · ㉢ 도움이에요.","같은 이유를 되풀이하면 이유가 늘지 않아요."],"asset":{"type":"passage","lines":["● 주제나 문제 상황에 어울리는 의견을 내야 합니다.","● 의견을 (  ㉠  )하는 적절한 이유를 들어야 합니다.","● (  ㉡  )한 이유를 중복되지 않게 제시해야 합니다.","● 의견은 문제 해결에 (  ㉢  )이/가 되는 것이어야 합니다.","보기: 다양 · 도움 · 뒷받침"],"title":"의견과 이유가 적절한지 알아보는 방법 — 『국어』 271쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_a#14','kor',3,2,'u6','','tb_g3_2_kor_u6_review_a','unit_review','K3-2-u6-C22',2,'mc','auto','『국어활동』 86~87쪽 글의 문제 상황은 무엇인가요?',ARRAY['K3-2-u6-X21','K3-2-u6-X31']::text[],false,'{"seq":14,"concept":"K3-2-u6-C22","difficulty":2,"kind":"mc","stem":"『국어활동』 86~87쪽 글의 문제 상황은 무엇인가요?","options":[{"t":"스마트 기기를 지나치게 오래 사용하는 학생이 많다","correct":true},{"t":"스마트 기기 사용 시간을 알맞게 정해 스스로 지키자","mis":"K3-2-u6-X21"},{"t":"스마트 기기를 오래 쓰면 시력이 나빠진다","mis":"K3-2-u6-X21"},{"t":"스마트 기기는 원래 재미있어서 어쩔 수 없다","mis":"K3-2-u6-X31"}],"explanation":["글에서 무엇이 문제인지 먼저 찾아요.","「정해 스스로 지키자」는 의견이에요.","「시력이 나빠진다」는 이유예요."],"asset":{"type":"passage","lines":["문제 상황 — 스마트 기기를 지나치게 오래 사용하는 학생이 많다.","의견 — 스마트 기기 사용 시간을 알맞게 정해 스스로 지키자.","이유 ㉮ 스마트 기기를 너무 오래 사용하면 시력이 나빠지기 때문입니다.","이유 ㉯ 스마트 기기에 빠져 숙제나 독서처럼 꼭 해야 하는 일들을 못 할 수도 있기 때문입니다.","이유 ㉰ 스마트 기기는 우리에게 도움을 주기 때문입니다."],"numbered":false,"title":"『국어활동』 87쪽 예시 답안에 실린 문제 상황·의견·이유"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_a#15','kor',3,2,'u6','','tb_g3_2_kor_u6_review_a','unit_review','K3-2-u6-C35',2,'mc','auto','『국어』 280쪽 팻말 ㉰에서 의견을 나타낸 부분은 무엇인가요?',ARRAY['K3-2-u6-X35','K3-2-u6-X11']::text[],false,'{"seq":15,"concept":"K3-2-u6-C35","difficulty":2,"kind":"mc","stem":"『국어』 280쪽 팻말 ㉰에서 의견을 나타낸 부분은 무엇인가요?","options":[{"t":"교실에서 뛰지 맙시다.","correct":true},{"t":"다른 친구와 부딪쳐 다칠 수 있기 때문입니다.","mis":"K3-2-u6-X35"},{"t":"교실이 더러우면 건강에 좋지 않습니다.","mis":"K3-2-u6-X11"}],"explanation":["「……맙시다」는 무엇을 하자는(하지 말자는) 생각이에요.","「……때문입니다」는 그 이유예요.","팻말에도 의견과 이유를 함께 담아요."],"asset":{"type":"passage","lines":["팻말 ㉮ 쓰레기는 쓰레기통에 버립시다. 교실이 더러우면 건강에 좋지 않습니다.","팻말 ㉯ 고운 말을 사용합시다. 나쁜 말을 쓰면 기분이 상하기 때문입니다.","팻말 ㉰ 교실에서 뛰지 맙시다. 다른 친구와 부딪쳐 다칠 수 있기 때문입니다."],"numbered":false,"title":"의견을 제시하는 손 팻말 — 『국어』 280쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_a#16','kor',3,2,'u6','','tb_g3_2_kor_u6_review_a','unit_review','K3-2-u6-C30',2,'mc','auto','『국어』 276쪽 그림 ㉯를 보고 떠올릴 수 있는 문제 상황은 무엇인가요?',ARRAY['K3-2-u6-X32','K3-2-u6-X31','K3-2-u6-X11']::text[],false,'{"seq":16,"concept":"K3-2-u6-C30","difficulty":2,"kind":"mc","stem":"『국어』 276쪽 그림 ㉯를 보고 떠올릴 수 있는 문제 상황은 무엇인가요?","options":[{"t":"친구들끼리 다투는 일이 자주 생긴다","correct":true},{"t":"다툰 친구의 이름을 적어 알린다","mis":"K3-2-u6-X32"},{"t":"친구끼리 다투는 것은 어쩔 수 없다","mis":"K3-2-u6-X31"},{"t":"친구들이 함께 청소를 한다","mis":"K3-2-u6-X11"}],"explanation":["그림 ㉯는 친구와 다툼이 있는 상황이에요.","우리가 함께 바꿀 수 있는 문제로 바꾸어 말해요.","누군가를 탓하거나 포기하는 말은 문제 상황이 아니에요."],"asset":{"type":"passage","lines":["주제: 더 나은 학교를 만들기 위해 학생들이 실천할 수 있는 방법","[그림 ㉮] 불청결한 학교 환경","[그림 ㉯] 친구와 다툼이 있는 상황","[그림 ?] 우리 학급이나 학교의 또 다른 문제 상황"],"title":"문제 파악하기 — 『국어』 276쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_a#17','kor',3,2,'u6','','tb_g3_2_kor_u6_review_a','unit_review','K3-2-u6-C23',3,'mc','auto','『국어』 283쪽 스스로 확인하기예요. 의견을 제시하는 글을 쓸 때 주의할 점으로 알맞은 것을 모두 고른 것은 무엇인가요?',ARRAY['K3-2-u6-X25','K3-2-u6-X29']::text[],false,'{"seq":17,"concept":"K3-2-u6-C23","difficulty":3,"kind":"mc","stem":"『국어』 283쪽 스스로 확인하기예요. 의견을 제시하는 글을 쓸 때 주의할 점으로 알맞은 것을 모두 고른 것은 무엇인가요?","options":[{"t":"㉮, ㉯, ㉱","correct":true},{"t":"㉮, ㉯, ㉰, ㉱","mis":"K3-2-u6-X25"},{"t":"㉰, ㉱","mis":"K3-2-u6-X25"},{"t":"㉮, ㉯","mis":"K3-2-u6-X29"}],"explanation":["어울리는 의견(㉮)과 뒷받침하는 이유(㉯)를 써요.","고쳐 쓸 부분이 있는지 확인하고 고쳐 써요(㉱).","같은 이유를 여러 번 제시하는 것(㉰)은 피해요."],"asset":{"type":"passage","lines":["㉮ 주제나 문제 상황에 어울리는 의견을 쓴다.","㉯ 의견을 뒷받침하는 적절한 이유를 쓴다.","㉰ 같은 이유를 여러 번 제시한다.","㉱ 고쳐 쓸 부분이 있는지 확인하고 알맞게 고쳐 쓴다."],"numbered":false,"title":"스스로 확인하기 — 『국어』 283쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_a#18','kor',3,2,'u6','','tb_g3_2_kor_u6_review_a','unit_review','K3-2-u6-C2',3,'mc','auto','「작품을 감상하고 느낀 재미나 감동 표현하기」를 마친 뒤 스스로 확인할 내용으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X01','K3-2-u6-X02','K3-2-u6-X14']::text[],false,'{"seq":18,"concept":"K3-2-u6-C2","difficulty":3,"kind":"mc","stem":"「작품을 감상하고 느낀 재미나 감동 표현하기」를 마친 뒤 스스로 확인할 내용으로 알맞은 것은 무엇인가요?","options":[{"t":"재미나 감동을 느낀 부분이 드러나도록 잘 표현했나요?","correct":true},{"t":"줄거리를 빠짐없이 외웠나요?","mis":"K3-2-u6-X01"},{"t":"작품에 몇 점을 주었나요?","mis":"K3-2-u6-X02"},{"t":"친구와 같은 장면을 골랐나요?","mis":"K3-2-u6-X14"}],"explanation":["작품을 즐겁게 감상했는지 확인해요.","재미나 감동을 느끼며 감상했는지 확인해요.","느낀 부분이 드러나게 표현했는지 확인해요."],"asset":{"type":"passage","lines":["1 자신이 인상 깊게 본 드라마나 만화 영화의 제목을 써 봅시다.","2 재미나 감동을 느낀 부분을 골라 글로 쓰고 장면을 그림으로 나타내 봅시다.","3 드라마나 만화 영화를 즐겁게 감상했나요?  ○○○","  재미나 감동을 느끼며 감상했나요?  ○○○","  재미나 감동을 느낀 부분이 드러나도록 잘 표현했나요?  ○○○"],"numbered":false,"title":"작품을 감상하고 느낀 재미나 감동 표현하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_a#19','kor',3,2,'u6','','tb_g3_2_kor_u6_review_a','unit_review','K3-2-u6-C27',3,'mc','auto','「뛰지 않는 안전한 학교」에 「또 내가 표지판을 가장 잘 만들기 때문입니다.」라는 문장을 덧붙였어요. 어떻게 하면 좋을까요?',ARRAY['K3-2-u6-X23','K3-2-u6-X28','K3-2-u6-X29']::text[],false,'{"seq":19,"concept":"K3-2-u6-C27","difficulty":3,"kind":"mc","stem":"「뛰지 않는 안전한 학교」에 「또 내가 표지판을 가장 잘 만들기 때문입니다.」라는 문장을 덧붙였어요. 어떻게 하면 좋을까요?","options":[{"t":"나만 잘한다는 것이라 의견을 뒷받침하지 못하므로 다른 이유로 바꾼다","correct":true},{"t":"이유가 셋이 되어 더 좋은 글이 되었다","mis":"K3-2-u6-X23"},{"t":"그 문장을 지우기만 하고 끝낸다","mis":"K3-2-u6-X28"},{"t":"이 글은 고칠 곳이 생겼으니 못 쓴 글이다","mis":"K3-2-u6-X29"}],"explanation":["이유는 의견대로 하면 무엇이 좋아지는지 말해야 해요.","내가 잘 만든다는 것은 모두에게 좋은 점이 아니에요.","받쳐 주는 이유로 바꾸어 써요."],"asset":{"type":"passage","lines":["제목: 뛰지 않는 안전한 학교","1 교실 안이나 복도에서 뛰어다니는 학생이 많습니다.","2 (간추림) 뛰어다니면 넘어져 다치거나 다른 학생과 부딪쳐 다치게 할 수 있습니다.","3 걸어 다니자는 표지판을 만들어 곳곳에 붙여 놓으면 좋겠습니다.","4 표지판을 보면 뛰지 말아야겠다는 생각이 들기 때문입니다.","5 또 표지판을 만들면서 뛰지 말아야겠다는 다짐도 할 수 있기 때문입니다.","6 표지판을 만들어 모두가 안전한 학교를 만들고 싶습니다."],"numbered":false,"title":"의견을 제시하는 글 (예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_a#20','kor',3,2,'u6','','tb_g3_2_kor_u6_review_a','unit_review','K3-2-u6-C24',3,'mc','auto','「뛰지 않는 안전한 학교」와 안전 지킴이 글의 같은 점은 무엇인가요?',ARRAY['K3-2-u6-X24','K3-2-u6-X21','K3-2-u6-X20']::text[],false,'{"seq":20,"concept":"K3-2-u6-C24","difficulty":3,"kind":"mc","stem":"「뛰지 않는 안전한 학교」와 안전 지킴이 글의 같은 점은 무엇인가요?","options":[{"t":"같은 문제 상황(교실이나 복도에서 뛰어다니기)을 해결하려는 글이다","correct":true},{"t":"두 글의 의견이 똑같다","mis":"K3-2-u6-X24"},{"t":"두 글 모두 문제 상황이 없다","mis":"K3-2-u6-X21"},{"t":"두 글 모두 이유가 없다","mis":"K3-2-u6-X20"}],"explanation":["두 글은 같은 문제 상황을 다루어요.","하나는 표지판, 하나는 안전 지킴이를 의견으로 냈어요.","같은 문제에도 의견은 여러 가지가 나올 수 있어요."],"asset":{"type":"passage","lines":["(간추림) 복도에서 뛰는 학생과 부딪쳐 무릎을 다친 적이 있다. 뛰어다니면 위험하다.","안전 지킴이를 뽑아 쉬는 시간이나 점심시간에 활동하도록 하면 좋겠습니다.","(간추림) 지킴이가 경고를 주면 뛰는 학생과 안전사고가 줄어든다.","(간추림) 지킴이가 서 있는 것만으로도 뛰면 안 된다는 점을 떠올리게 된다."],"title":"같은 문제 상황에 대한 다른 의견 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_a#21','kor',3,2,'u6','','tb_g3_2_kor_u6_review_a','unit_review','K3-2-u6-C18',3,'mc','auto','「동생과 싸웠을 때 엄마가 나를 더 혼내셔서 속상했는데, 밤에 침대로 와서 안아 주셔서 오해가 풀렸다.」는 경험과 드라마의 공통점은 무엇인가요?',ARRAY['K3-2-u6-X16','K3-2-u6-X18','K3-2-u6-X46']::text[],false,'{"seq":21,"concept":"K3-2-u6-C18","difficulty":3,"kind":"mc","stem":"「동생과 싸웠을 때 엄마가 나를 더 혼내셔서 속상했는데, 밤에 침대로 와서 안아 주셔서 오해가 풀렸다.」는 경험과 드라마의 공통점은 무엇인가요?","options":[{"t":"처음에는 상대의 마음을 몰라 서운했지만 알고 나니 오해가 풀렸다","correct":true},{"t":"누가 잘못했는지 가려서 사과를 받았다","mis":"K3-2-u6-X16"},{"t":"속상한 일은 끝까지 말하지 않는 것이 좋다","mis":"K3-2-u6-X18"},{"t":"엄마는 나를 미워해서 혼냈다","mis":"K3-2-u6-X46"}],"explanation":["신비도 친구들의 마음을 몰라 서운해했어요.","상대의 진심을 알고 나서 오해가 풀렸어요.","드라마와 비슷한 경험을 나누면 인물의 마음이 더 잘 이해돼요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"동생과 싸웠을 때 엄마가 나를 더 혼내셔서 속상했는데, 그날 밤에 침대로 와서 안아 주셔서 오해가 풀렸어."},{"who":"친구 2","text":"두 친구가 나에게 안 들리게 귓속말을 해서 속상했는데, 알고 보니 내 생일 선물을 준비하는 것이어서 오히려 미안했어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_a#22','kor',3,2,'u6','','tb_g3_2_kor_u6_review_a','unit_review','K3-2-u6-C29',3,'mc','auto','친구와 글을 바꾸어 읽고 고쳐야 할 부분을 말할 때 지킬 점으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X30','K3-2-u6-X02','K3-2-u6-X27']::text[],false,'{"seq":22,"concept":"K3-2-u6-C29","difficulty":3,"kind":"mc","stem":"친구와 글을 바꾸어 읽고 고쳐야 할 부분을 말할 때 지킬 점으로 알맞은 것은 무엇인가요?","options":[{"t":"고쳐 쓰면 좋을 부분과 그렇게 생각한 이유만 간단명료하게 말한다","correct":true},{"t":"흠을 빠짐없이 찾아 모두 말한다","mis":"K3-2-u6-X30"},{"t":"점수를 매겨 알려 준다","mis":"K3-2-u6-X02"},{"t":"글씨 모양만 말해 준다","mis":"K3-2-u6-X27"}],"explanation":["다른 사람의 글을 비난하거나 무시하지 않아요.","고칠 부분과 이유를 분명하게 말해요.","점검표를 바탕으로 말하면 도움이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_a#23','kor',3,2,'u6','','tb_g3_2_kor_u6_review_a','unit_review','K3-2-u6-C7',4,'essay','teacher','인상 깊게 본 드라마나 만화 영화의 제목을 쓰고, 재미나 감동을 느낀 부분을 골라 그 까닭과 함께 쓰세요. 그 장면을 그림으로 나타낸다면 어떻게 그릴지도 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-2-u6-C7","difficulty":4,"kind":"essay","stem":"인상 깊게 본 드라마나 만화 영화의 제목을 쓰고, 재미나 감동을 느낀 부분을 골라 그 까닭과 함께 쓰세요. 그 장면을 그림으로 나타낸다면 어떻게 그릴지도 쓰세요.","answer_guide":{"answer":"예: 제목 — 「건전지 엄마」. 건전지 엄마가 위험을 무릅쓰고 아이들을 구하러 나서는 장면이 감동적이었다. 무서울 텐데도 아이들을 먼저 생각하는 모습이 우리 엄마 같았기 때문이다. 그림 — 땀을 흘리며 아이들에게 가는 건전지 엄마와 잠든 아이들을 그리겠다.","scoring_points":["드라마나 만화 영화의 제목을 썼는가","재미나 감동을 느낀 부분과 까닭을 썼는가","그 장면을 그림으로 어떻게 나타낼지 썼는가"]},"explanation":["인상 깊게 본 작품을 떠올려요.","느낀 부분과 까닭을 글로 써요.","장면은 그림으로도 나타내요."],"asset":{"type":"passage","lines":["1 자신이 인상 깊게 본 드라마나 만화 영화의 제목을 써 봅시다.","2 재미나 감동을 느낀 부분을 골라 글로 쓰고 장면을 그림으로 나타내 봅시다.","3 드라마나 만화 영화를 즐겁게 감상했나요?  ○○○","  재미나 감동을 느끼며 감상했나요?  ○○○","  재미나 감동을 느낀 부분이 드러나도록 잘 표현했나요?  ○○○"],"numbered":false,"title":"작품을 감상하고 느낀 재미나 감동 표현하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_a#24','kor',3,2,'u6','','tb_g3_2_kor_u6_review_a','unit_review','K3-2-u6-C20',4,'essay','teacher','「학교 화단 공간을 줄이고, 놀이 공간을 만들어야 하는가?」에 대한 자신의 의견과 그렇게 생각하는 이유를 제시하는 글을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u6-C20","difficulty":4,"kind":"essay","stem":"「학교 화단 공간을 줄이고, 놀이 공간을 만들어야 하는가?」에 대한 자신의 의견과 그렇게 생각하는 이유를 제시하는 글을 쓰세요.","answer_guide":{"answer":"예: 저는 학교 화단 공간을 줄이고 놀이 공간을 만들면 좋겠다고 생각합니다. 첫째, 쉬는 시간에 놀 곳이 부족해서 복도에서 뛰다가 다치는 친구들이 있기 때문입니다. 둘째, 밖에서 마음껏 뛰어놀면 체력도 기르고 친구와도 더 친해질 수 있기 때문입니다. 화단의 꽃은 교실 화분으로 옮겨 함께 기르면 좋겠습니다.","scoring_points":["주제에 대한 자신의 의견을 분명하게 썼는가","의견을 뒷받침하는 이유를 썼는가","문단의 첫머리를 들여 쓰고 띄어쓰기와 맞춤법을 지켰는가"]},"explanation":["먼저 내 의견을 정해요.","의견을 받쳐 주는 이유를 두 가지 써요.","다 쓰면 스스로 확인하고 고쳐 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_a#25','kor',3,2,'u6','','tb_g3_2_kor_u6_review_a','unit_review','K3-2-u6-C36',4,'essay','teacher','「레오의 특별한 꿈」에서 재미나 감동을 느낀 장면을 골라 「만약 이랬더라면?」 하고 인물의 말이나 행동을 바꾸어 쓰고, 이어질 장면을 상상해 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u6-C36","difficulty":4,"kind":"essay","stem":"「레오의 특별한 꿈」에서 재미나 감동을 느낀 장면을 골라 「만약 이랬더라면?」 하고 인물의 말이나 행동을 바꾸어 쓰고, 이어질 장면을 상상해 쓰세요.","answer_guide":{"answer":"예: 장면 — 친구들이 레오의 델이 가짜라고 놀리는 장면. 바꾼 행동 — 한 친구가 「델이 없어도 너는 우리 친구야.」라고 말한다. 이어질 장면 — 레오는 용기를 내어 가짜 델을 떼고, 친구들과 함께 자기의 진짜 꿈이 무엇인지 이야기를 나눈다.","scoring_points":["재미나 감동을 느낀 장면을 골랐는가","인물의 말이나 행동을 바꾸었는가","이어질 장면을 상상해 썼는가"]},"explanation":["마음이 움직인 장면을 골라요.","인물의 말과 행동을 더하거나 바꾸어요.","이어질 장면은 역할놀이 대본으로도 쓸 수 있어요."],"asset":{"type":"passage","lines":["(간추림) 꿈 마을 사람들 머리에는 저마다의 꿈이 담긴 ‘델’이 있지만 레오에게는 없었다.","(간추림) 마법사는 델 모양은 만들 수 있지만 능력은 만들 수 없다고 했다.","(간추림) 친구들은 레오 머리 위의 델이 가짜라는 것을 알아차렸다.","(간추림) 레오가 가짜 델을 스스로 없애고 진짜 꿈을 생각하자 진짜 델이 생겨났다."],"title":"「레오의 특별한 꿈」 간추린 줄거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_b#1','kor',3,2,'u6','','tb_g3_2_kor_u6_review_b','unit_review','K3-2-u6-C1',1,'ox','auto','윤솔이가 쓰려는 글은 영화를 보고 느낀 재미나 감동을 표현하는 글이에요.',ARRAY['K3-2-u6-X47']::text[],false,'{"seq":1,"concept":"K3-2-u6-C1","difficulty":1,"kind":"ox","stem":"윤솔이가 쓰려는 글은 영화를 보고 느낀 재미나 감동을 표현하는 글이에요.","answer":"X","reason_options":[{"t":"윤솔이는 한글을 바르게 사용하자는 의견을 제시하는 글을 쓰려고 하기 때문에","correct":true},{"t":"감동받은 영화를 보고 쓰는 글은 모두 감상을 표현하는 글이기 때문에","mis":"K3-2-u6-X47"}],"mis":"K3-2-u6-X47","explanation":["윤솔이는 영화에 감동받은 것은 맞다고 했어요.","하지만 한글 사용에 대한 자기 의견을 쓰겠다고 했어요.","그래서 X예요."],"asset":{"type":"speech","turns":[{"who":"지수","text":"윤솔아, 뭐 해?"},{"who":"윤솔","text":"세종 대왕님께서 만드신 한글과 관련 있는 영화를 봤는데 영화를 보고 나서 쓰고 싶은 게 떠올랐어."},{"who":"지수","text":"영화를 보고 느낀 재미나 감동을 글로 쓰는 거야?"},{"who":"윤솔","text":"아니. 백성을 사랑하는 마음으로 만드신 한글에 감동받은 건 맞지만, 한글 사용에 대한 내 의견을 제시하는 글을 쓸 거야."},{"who":"윤솔","text":"소중한 한글을 바르게 사용하자는 의견이야. 요즘 우리가 사용하는 말에 외국어나 바람직하지 않은 말이 많은 것 같아."},{"who":"지수","text":"좋은 생각이다! 작품을 감상한 뒤에 자신의 의견을 제시하는 글을 쓸 수도 있구나."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_b#2','kor',3,2,'u6','','tb_g3_2_kor_u6_review_b','unit_review','K3-2-u6-C3',1,'mc','auto','친구 3은 마법사에게 ‘델’ 모양만이라도 만들어 달라고 조르는 레오의 모습에서 무엇을 느꼈나요?',ARRAY['K3-2-u6-X08','K3-2-u6-X07']::text[],false,'{"seq":2,"concept":"K3-2-u6-C3","difficulty":1,"kind":"mc","stem":"친구 3은 마법사에게 ‘델’ 모양만이라도 만들어 달라고 조르는 레오의 모습에서 무엇을 느꼈나요?","options":[{"t":"재미","correct":true},{"t":"슬픔","mis":"K3-2-u6-X08"},{"t":"아무 느낌도 없음","mis":"K3-2-u6-X07"}],"explanation":["친구 3은 「조금은 재미있게 느껴졌어.」라고 했어요.","부모님께 조르는 자기 모습 같았기 때문이에요.","한 작품 안에 재미와 감동이 함께 있어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"1학기 때 교과서에서 읽은 「레오의 특별한 꿈」이 어때?"},{"who":"친구 2","text":"가짜 ‘델’을 달고 있다고 친구들에게 놀림받은 레오가 무척 안쓰러웠어. 나도 친구들에게 놀림받았을 때 속상했거든."},{"who":"친구 3","text":"신비한 능력이 없어도 좋으니까 ‘델’ 모양만이라도 만들어 달라고 마법사에게 조르는 레오의 모습이 조금은 재미있게 느껴졌어. 부모님께 물건을 사 달라고 부탁하는 내 모습 같았거든."},{"who":"친구 1","text":"그랬구나. 나는 레오가 진짜 꿈에 대해 생각하자 진짜 ‘델’이 생긴 장면이 감동적이었어. 나도 꿈을 이루기 위해 열심히 노력해야겠다고 생각했어."},{"who":"친구 2","text":"같은 작품을 보고도 재미나 감동을 느낀 부분이 다를 수 있구나."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_b#3','kor',3,2,'u6','','tb_g3_2_kor_u6_review_b','unit_review','K3-2-u6-C11',1,'mc','auto','예서는 「평화로운 음악이 갑자기 멈춰서 무슨 일이 생길 것만 같았어.」라고 했어요. 예서가 쓴 감상 방법은 무엇인가요?',ARRAY['K3-2-u6-X12','K3-2-u6-X42']::text[],false,'{"seq":3,"concept":"K3-2-u6-C11","difficulty":1,"kind":"mc","stem":"예서는 「평화로운 음악이 갑자기 멈춰서 무슨 일이 생길 것만 같았어.」라고 했어요. 예서가 쓴 감상 방법은 무엇인가요?","options":[{"t":"배경 음악이나 효과음에 집중하며 보기","correct":true},{"t":"인물의 표정이나 말투에 주의하며 보기","mis":"K3-2-u6-X12"},{"t":"주제나 교훈을 떠올리며 보기","mis":"K3-2-u6-X12"},{"t":"소리는 상관없으니 그림만 보기","mis":"K3-2-u6-X42"}],"explanation":["예서는 음악이 멈추는 것을 알아챘어요.","배경 음악과 효과음은 분위기를 생생하게 해 줘요.","만화 영화의 소리도 감상 거리예요."],"asset":{"type":"speech","turns":[{"who":"하준","text":"아이들을 구하려고 달려가는 건전지 엄마의 표정을 보고 다급한 상황이 실감 났어."},{"who":"예서","text":"유치원 아이들이 낮잠 잘 때 평화로운 음악이 흐르다가 갑자기 멈춰서 무슨 일이 생길 것만 같았어."},{"who":"시윤","text":"아이들을 구한 건전지 엄마처럼 나도 용기 있게 행동하고 싶어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_b#4','kor',3,2,'u6','','tb_g3_2_kor_u6_review_b','unit_review','K3-2-u6-C43',1,'mc','auto','「단짝」의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X11']::text[],false,'{"seq":4,"concept":"K3-2-u6-C43","difficulty":1,"kind":"mc","stem":"「단짝」의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"서로 뜻이 맞거나 매우 친해 늘 함께 어울리는 친구","correct":true},{"t":"신발의 바닥 밑에 붙이는 가죽이나 고무 따위의 조각","mis":"K3-2-u6-X11"},{"t":"매우 대견하고 칭찬해 줄 만하다","mis":"K3-2-u6-X11"}],"explanation":["드라마에 나온 낱말이에요.","「나는 단짝인 민재와 매일 축구를 한다.」처럼 써요.","나머지는 「밑창」, 「신통방통하다」의 뜻이에요."],"asset":{"type":"passage","lines":["보기: 신통방통하다 · 밑창 · 단짝","㉮ 서로 뜻이 맞거나 매우 친해 늘 함께 어울리는 친구.","㉯ 신발의 바닥 밑에 붙이는 가죽이나 고무 따위의 조각.","㉰ 매우 대견하고 칭찬해 줄 만하다."],"numbered":false,"title":"낱말 알기 — 『국어』 265쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_b#5','kor',3,2,'u6','','tb_g3_2_kor_u6_review_b','unit_review','K3-2-u6-C19',1,'mc','auto','다음 가운데 의견을 나타낸 문장은 무엇인가요?',ARRAY['K3-2-u6-X19']::text[],false,'{"seq":5,"concept":"K3-2-u6-C19","difficulty":1,"kind":"mc","stem":"다음 가운데 의견을 나타낸 문장은 무엇인가요?","options":[{"t":"복도에서는 걸어 다니면 좋겠다.","correct":true},{"t":"어제 복도에서 친구와 부딪쳤다.","mis":"K3-2-u6-X19"},{"t":"우리 학교 복도는 길다.","mis":"K3-2-u6-X19"},{"t":"복도 끝에 화장실이 있다.","mis":"K3-2-u6-X19"}],"explanation":["「……면 좋겠다」는 의견을 나타내는 표현이에요.","의견에는 글쓴이의 생각이 담겨요.","나머지는 있었던 일이나 사실이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_b#6','kor',3,2,'u6','','tb_g3_2_kor_u6_review_b','unit_review','K3-2-u6-C20',1,'match','auto','「건강하고 행복한 급식 시간」의 문장과 하는 일을 바르게 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"K3-2-u6-C20","difficulty":1,"kind":"match","stem":"「건강하고 행복한 급식 시간」의 문장과 하는 일을 바르게 이어 보세요.","pairs":[{"l":"급식 시간에 편식을 하는 친구들이 종종 있습니다.","r":"문제 상황"},{"l":"저는 음식을 골고루 먹어야 한다고 생각합니다.","r":"의견"},{"l":"다양한 음식을 즐길 수 있습니다.","r":"이유"}],"mis":"K3-2-u6-X21","explanation":["첫 문장은 무엇이 문제인지 알려 줘요.","「……라고 생각합니다」는 의견이에요.","「첫째」, 「둘째」 뒤는 이유예요."],"asset":{"type":"passage","lines":["급식 시간에 편식을 하는 친구들이 종종 있습니다.","하지만 저는 음식을 골고루 먹어야 한다고 생각합니다.","첫째, 음식을 골고루 먹어야 우리 몸에 필요한 여러 영양소를 얻을 수 있습니다.","(간추림) 근육에는 고기·생선·콩, 힘에는 곡물, 몸의 조절에는 과일·채소.","둘째, 자신이 경험해 보지 못한 다양한 음식을 즐길 수 있습니다.","(간추림) 김치를 싫어했는데 김치볶음밥을 먹은 뒤 김치를 좋아하게 되었다.","음식을 골고루 먹으면서 건강하고 행복한 급식 시간을 만들어 봅시다."],"title":"「건강하고 행복한 급식 시간」 — 『국어』 270쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_b#7','kor',3,2,'u6','','tb_g3_2_kor_u6_review_b','unit_review','K3-2-u6-C26',1,'blank','auto','『국어』 274쪽 1번이에요. ㉡에 알맞은 낱말은 무엇인가요?',ARRAY['K3-2-u6-X27']::text[],false,'{"seq":7,"concept":"K3-2-u6-C26","difficulty":1,"kind":"blank","stem":"『국어』 274쪽 1번이에요. ㉡에 알맞은 낱말은 무엇인가요?","options":[{"t":"적절","correct":true},{"t":"글씨","mis":"K3-2-u6-X27"},{"t":"길이","mis":"K3-2-u6-X27"}],"explanation":["의견을 뒷받침하는 적절한 이유를 썼는지 확인해요.","㉠ 문제 상황 · ㉡ 적절 · ㉢ 문제 해결이에요.","이 세 가지에 내용과 표현도 함께 살펴봐요."],"asset":{"type":"passage","lines":["● 주제나 (    ㉠    )에 어울리는 의견을 썼는지 확인한다.","● 의견을 뒷받침하는 (    ㉡    )한 이유를 썼는지 확인한다.","● 의견과 그 이유가 (    ㉢    )에 도움이 되는지 살펴본다.","보기: 적절 · 문제 해결 · 문제 상황","※ 글의 내용에 어색한 부분, 띄어쓰기나 맞춤법이 틀린 부분도 살펴본다."],"title":"의견을 제시하는 글을 고쳐 쓰는 방법 — 『국어』 274쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_b#8','kor',3,2,'u6','','tb_g3_2_kor_u6_review_b','unit_review','K3-2-u6-C39',1,'mc','auto','「쉬는 시간에 우리 같이 (놀까, 놀가)?」에서 바르게 쓴 낱말은 무엇인가요?',ARRAY['K3-2-u6-X39','K3-2-u6-X38']::text[],false,'{"seq":8,"concept":"K3-2-u6-C39","difficulty":1,"kind":"mc","stem":"「쉬는 시간에 우리 같이 (놀까, 놀가)?」에서 바르게 쓴 낱말은 무엇인가요?","options":[{"t":"놀까","correct":true},{"t":"놀가","mis":"K3-2-u6-X39"},{"t":"놀께","mis":"K3-2-u6-X38"}],"explanation":["묻는 말이에요.","묻는 말의 「까」는 소리 나는 대로 써요.","그래서 「놀까」로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_b#9','kor',3,2,'u6','','tb_g3_2_kor_u6_review_b','unit_review','K3-2-u6-C12',2,'ox','auto','「눈사람 넷」을 읽은 세 친구가 서로 다른 부분에서 재미를 느꼈으니, 두 친구는 시를 잘못 읽은 것이에요.',ARRAY['K3-2-u6-X13']::text[],false,'{"seq":9,"concept":"K3-2-u6-C12","difficulty":2,"kind":"ox","stem":"「눈사람 넷」을 읽은 세 친구가 서로 다른 부분에서 재미를 느꼈으니, 두 친구는 시를 잘못 읽은 것이에요.","answer":"X","reason_options":[{"t":"한 시 안에도 재미를 느낄 수 있는 부분이 여러 곳이고, 세 친구 모두 시 안의 표현을 들었기 때문에","correct":true},{"t":"시마다 재미있는 곳은 한 곳뿐이기 때문에","mis":"K3-2-u6-X13"}],"mis":"K3-2-u6-X13","explanation":["사람마다 재미나 감동을 느끼는 부분이 달라요.","세 친구는 모두 시 속 표현을 근거로 말했어요.","그래서 X예요."],"asset":{"type":"speech","turns":[{"who":"정운","text":"눈이 (    ) 내린다고 표현한 부분이 재미있었어."},{"who":"유연","text":"눈을 맞은 친구들을 (    )(으)로 표현한 것이 재미있었어."},{"who":"단우","text":"눈을 맞은 친구들이 집에 가는 것을 (    )을/를 데리고 간다고 표현한 것이 재미있었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_b#10','kor',3,2,'u6','','tb_g3_2_kor_u6_review_b','unit_review','K3-2-u6-C42',2,'mc','auto','「건전지 엄마」의 마지막 장면은 무엇인가요?',ARRAY['K3-2-u6-X11']::text[],false,'{"seq":10,"concept":"K3-2-u6-C42","difficulty":2,"kind":"mc","stem":"「건전지 엄마」의 마지막 장면은 무엇인가요?","options":[{"t":"아이들은 무사히 대피하고 건전지 엄마도 집에 와서 행복하게 잠들었다","correct":true},{"t":"건전지 엄마가 타는 냄새를 느꼈다","mis":"K3-2-u6-X11"},{"t":"아이들이 낮잠을 자기 시작했다","mis":"K3-2-u6-X11"},{"t":"건전지 엄마가 있는 힘껏 비상벨을 울렸다","mis":"K3-2-u6-X11"}],"explanation":["사건은 낮잠 → 타는 냄새 → 나섬 → 비상벨 차례예요.","맨 끝에 아이들이 대피하고 건전지 엄마도 잠들어요.","차례대로 늘어놓으면 이야기를 요약할 수 있어요."],"asset":{"type":"passage","lines":["① 어린이집에서 낮잠 시간에 아이들이 모두 잠들었습니다.","② 건전지 엄마는 타는 냄새가 나는 것을 느꼈습니다.","③ 건전지 엄마는 위험을 무릅쓰고 아이들을 구하려고 나섰습니다.","④ 건전지 엄마는 있는 힘껏 비상벨을 울렸습니다.","⑤ 비상벨을 들은 아이들은 무사히 대피하고,","   건전지 엄마도 집에 와서 행복하게 잠들었습니다."],"numbered":false,"title":"「건전지 엄마」 장면을 보고 요약하여 말하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_b#11','kor',3,2,'u6','','tb_g3_2_kor_u6_review_b','unit_review','K3-2-u6-C17',2,'mc','auto','뜨거운 의자 놀이에서 신비 역할을 맡은 친구에게 할 질문으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X17']::text[],false,'{"seq":11,"concept":"K3-2-u6-C17","difficulty":2,"kind":"mc","stem":"뜨거운 의자 놀이에서 신비 역할을 맡은 친구에게 할 질문으로 알맞은 것은 무엇인가요?","options":[{"t":"“상대의 처지를 보고 난 뒤에 마음이 어떻게 변했나요?”","correct":true},{"t":"“신비 역할을 한 배우는 어느 학교에 다니나요?”","mis":"K3-2-u6-X17"},{"t":"“드라마는 몇 분짜리인가요?”","mis":"K3-2-u6-X17"},{"t":"“드라마를 찍은 슈퍼는 어디에 있나요?”","mis":"K3-2-u6-X17"}],"explanation":["인물이 드라마 속에서 답할 수 있는 질문을 해요.","인물의 마음이 어떻게 변했는지 물어요.","「친구들에게 서운했던 점이 무엇인가요?」도 좋은 질문이에요."],"asset":{"type":"passage","lines":["① 교실 앞에 의자 하나를 놓는다.","② 드라마에 나오는 인물 가운데에서 한 명을 정한다.","③ 한 친구가 정한 인물이 되어 의자에 앉는다.","④ 다른 친구들은 그 인물에게 궁금한 점을 묻는다.","⑤ 의자에 앉은 친구는 그 인물이 되어 대답한다."],"numbered":false,"title":"인물에게 묻고 답하기(뜨거운 의자) — 『국어』 266쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_b#12','kor',3,2,'u6','','tb_g3_2_kor_u6_review_b','unit_review','K3-2-u6-C21',2,'mc','auto','「건강하고 행복한 급식 시간」에서 둘째 이유를 받쳐 주려고 글쓴이가 든 경험은 무엇인가요?',ARRAY['K3-2-u6-X11','K3-2-u6-X22','K3-2-u6-X04']::text[],false,'{"seq":12,"concept":"K3-2-u6-C21","difficulty":2,"kind":"mc","stem":"「건강하고 행복한 급식 시간」에서 둘째 이유를 받쳐 주려고 글쓴이가 든 경험은 무엇인가요?","options":[{"t":"김치를 싫어했는데 김치볶음밥을 먹은 뒤 김치를 좋아하게 되었다","correct":true},{"t":"급식실에서 친구와 다투었다","mis":"K3-2-u6-X11"},{"t":"좋아하는 반찬만 골라 먹었더니 키가 컸다","mis":"K3-2-u6-X22"},{"t":"급식을 먹지 않고 운동장에 나갔다","mis":"K3-2-u6-X04"}],"explanation":["둘째 이유는 다양한 음식을 즐길 수 있다는 것이에요.","요리 방법에 따라 싫어하던 재료도 입맛에 맞을 수 있어요.","김치볶음밥 경험이 그 이유를 받쳐 줘요."],"asset":{"type":"passage","lines":["급식 시간에 편식을 하는 친구들이 종종 있습니다.","하지만 저는 음식을 골고루 먹어야 한다고 생각합니다.","첫째, 음식을 골고루 먹어야 우리 몸에 필요한 여러 영양소를 얻을 수 있습니다.","(간추림) 근육에는 고기·생선·콩, 힘에는 곡물, 몸의 조절에는 과일·채소.","둘째, 자신이 경험해 보지 못한 다양한 음식을 즐길 수 있습니다.","(간추림) 김치를 싫어했는데 김치볶음밥을 먹은 뒤 김치를 좋아하게 되었다.","음식을 골고루 먹으면서 건강하고 행복한 급식 시간을 만들어 봅시다."],"title":"「건강하고 행복한 급식 시간」 — 『국어』 270쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_b#13','kor',3,2,'u6','','tb_g3_2_kor_u6_review_b','unit_review','K3-2-u6-C23',2,'blank','auto','『국어』 271쪽 의견과 이유가 적절한지 알아보는 방법이에요. ㉢에 알맞은 낱말은 무엇인가요?',ARRAY['K3-2-u6-X25','K3-2-u6-X22']::text[],false,'{"seq":13,"concept":"K3-2-u6-C23","difficulty":2,"kind":"blank","stem":"『국어』 271쪽 의견과 이유가 적절한지 알아보는 방법이에요. ㉢에 알맞은 낱말은 무엇인가요?","options":[{"t":"도움","correct":true},{"t":"다양","mis":"K3-2-u6-X25"},{"t":"뒷받침","mis":"K3-2-u6-X22"}],"explanation":["의견은 문제 해결에 도움이 되는 것이어야 해요.","㉠ 뒷받침 · ㉡ 다양 · ㉢ 도움이에요.","의견을 제시하는 글은 문제를 해결하려고 써요."],"asset":{"type":"passage","lines":["● 주제나 문제 상황에 어울리는 의견을 내야 합니다.","● 의견을 (  ㉠  )하는 적절한 이유를 들어야 합니다.","● (  ㉡  )한 이유를 중복되지 않게 제시해야 합니다.","● 의견은 문제 해결에 (  ㉢  )이/가 되는 것이어야 합니다.","보기: 다양 · 도움 · 뒷받침"],"title":"의견과 이유가 적절한지 알아보는 방법 — 『국어』 271쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_b#14','kor',3,2,'u6','','tb_g3_2_kor_u6_review_b','unit_review','K3-2-u6-C22',2,'mc','auto','『국어활동』 86~87쪽 글의 이유 ㉰가 적절하지 않은 까닭은 무엇인가요?',ARRAY['K3-2-u6-X27','K3-2-u6-X24','K3-2-u6-X25']::text[],false,'{"seq":14,"concept":"K3-2-u6-C22","difficulty":2,"kind":"mc","stem":"『국어활동』 86~87쪽 글의 이유 ㉰가 적절하지 않은 까닭은 무엇인가요?","options":[{"t":"사용 시간을 정하자는 의견을 받쳐 주지 못하고 오히려 오래 써도 된다는 뜻으로 읽히기 때문","correct":true},{"t":"문장이 너무 짧기 때문","mis":"K3-2-u6-X27"},{"t":"스마트 기기를 좋아하는 사람도 있으니 정답 의견이 없기 때문","mis":"K3-2-u6-X24"},{"t":"㉮와 같은 말을 되풀이했기 때문","mis":"K3-2-u6-X25"}],"explanation":["이유는 의견과 이어져야 해요.","「도움을 주기 때문」은 사용 시간을 줄이자는 의견과 맞지 않아요.","그래서 의견을 뒷받침하는 이유로 고쳐 써야 해요."],"asset":{"type":"passage","lines":["문제 상황 — 스마트 기기를 지나치게 오래 사용하는 학생이 많다.","의견 — 스마트 기기 사용 시간을 알맞게 정해 스스로 지키자.","이유 ㉮ 스마트 기기를 너무 오래 사용하면 시력이 나빠지기 때문입니다.","이유 ㉯ 스마트 기기에 빠져 숙제나 독서처럼 꼭 해야 하는 일들을 못 할 수도 있기 때문입니다.","이유 ㉰ 스마트 기기는 우리에게 도움을 주기 때문입니다."],"numbered":false,"title":"『국어활동』 87쪽 예시 답안에 실린 문제 상황·의견·이유"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_b#15','kor',3,2,'u6','','tb_g3_2_kor_u6_review_b','unit_review','K3-2-u6-C35',2,'mc','auto','『국어』 280쪽 팻말 ㉮에서 이유를 나타낸 부분은 무엇인가요?',ARRAY['K3-2-u6-X34','K3-2-u6-X11']::text[],false,'{"seq":15,"concept":"K3-2-u6-C35","difficulty":2,"kind":"mc","stem":"『국어』 280쪽 팻말 ㉮에서 이유를 나타낸 부분은 무엇인가요?","options":[{"t":"교실이 더러우면 건강에 좋지 않습니다.","correct":true},{"t":"쓰레기는 쓰레기통에 버립시다.","mis":"K3-2-u6-X34"},{"t":"나쁜 말을 쓰면 기분이 상하기 때문입니다.","mis":"K3-2-u6-X11"}],"explanation":["팻말 ㉮의 의견은 「쓰레기는 쓰레기통에 버립시다.」예요.","그 뒤 문장이 왜 그래야 하는지 알려 주는 이유예요.","의견만 있으면 명령처럼 느껴져요."],"asset":{"type":"passage","lines":["팻말 ㉮ 쓰레기는 쓰레기통에 버립시다. 교실이 더러우면 건강에 좋지 않습니다.","팻말 ㉯ 고운 말을 사용합시다. 나쁜 말을 쓰면 기분이 상하기 때문입니다.","팻말 ㉰ 교실에서 뛰지 맙시다. 다른 친구와 부딪쳐 다칠 수 있기 때문입니다."],"numbered":false,"title":"의견을 제시하는 손 팻말 — 『국어』 280쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_b#16','kor',3,2,'u6','','tb_g3_2_kor_u6_review_b','unit_review','K3-2-u6-C31',2,'mc','auto','『국어』 276쪽 계획하기예요. 읽을 사람이 우리 반 친구들일 때 쓴 글을 활용하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X33','K3-2-u6-X02','K3-2-u6-X32']::text[],false,'{"seq":16,"concept":"K3-2-u6-C31","difficulty":2,"kind":"mc","stem":"『국어』 276쪽 계획하기예요. 읽을 사람이 우리 반 친구들일 때 쓴 글을 활용하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"학급 알림판에 게시하거나 친구들 앞에서 발표한다","correct":true},{"t":"아무도 보지 않게 서랍에 넣어 둔다","mis":"K3-2-u6-X33"},{"t":"선생님께 점수만 받고 버린다","mis":"K3-2-u6-X02"},{"t":"잘못한 친구의 집에 보낸다","mis":"K3-2-u6-X32"}],"explanation":["읽을 사람이 볼 수 있는 곳에 활용해요.","알림판에 붙이거나 발표해요.","고쳐 쓰기 전과 후를 비교해 잘한 점을 칭찬해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_b#17','kor',3,2,'u6','','tb_g3_2_kor_u6_review_b','unit_review','K3-2-u6-C23',3,'mc','auto','『국어』 283쪽 스스로 확인하기에서 ㉰ 「같은 이유를 여러 번 제시한다.」를 색칠하지 않는 까닭은 무엇인가요?',ARRAY['K3-2-u6-X25','K3-2-u6-X20','K3-2-u6-X45']::text[],false,'{"seq":17,"concept":"K3-2-u6-C23","difficulty":3,"kind":"mc","stem":"『국어』 283쪽 스스로 확인하기에서 ㉰ 「같은 이유를 여러 번 제시한다.」를 색칠하지 않는 까닭은 무엇인가요?","options":[{"t":"같은 이유를 되풀이하면 이유가 늘지 않고 글만 길어지기 때문","correct":true},{"t":"같은 이유를 여러 번 쓸수록 의견이 튼튼해지기 때문","mis":"K3-2-u6-X25"},{"t":"이유는 하나도 쓰지 않는 것이 좋기 때문","mis":"K3-2-u6-X20"},{"t":"고쳐 쓰기를 하면 안 되기 때문","mis":"K3-2-u6-X45"}],"explanation":["이유는 다양하게, 겹치지 않게 써요.","같은 이유를 말만 바꾸어 쓰면 하나의 이유예요.","그래서 주의할 점이 아니에요."],"asset":{"type":"passage","lines":["㉮ 주제나 문제 상황에 어울리는 의견을 쓴다.","㉯ 의견을 뒷받침하는 적절한 이유를 쓴다.","㉰ 같은 이유를 여러 번 제시한다.","㉱ 고쳐 쓸 부분이 있는지 확인하고 알맞게 고쳐 쓴다."],"numbered":false,"title":"스스로 확인하기 — 『국어』 283쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_b#18','kor',3,2,'u6','','tb_g3_2_kor_u6_review_b','unit_review','K3-2-u6-C6',3,'mc','auto','인상 깊게 본 드라마나 만화 영화에서 재미나 감동을 느낀 부분을 글로 쓰려고 해요. 글에 담을 내용으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X06','K3-2-u6-X02','K3-2-u6-X04']::text[],false,'{"seq":18,"concept":"K3-2-u6-C6","difficulty":3,"kind":"mc","stem":"인상 깊게 본 드라마나 만화 영화에서 재미나 감동을 느낀 부분을 글로 쓰려고 해요. 글에 담을 내용으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"그 장면에서 어떤 마음이 들었는지와 그 까닭","correct":true},{"t":"처음부터 끝까지의 줄거리","mis":"K3-2-u6-X06"},{"t":"작품에 준 별의 개수","mis":"K3-2-u6-X02"},{"t":"작품에 나오지 않는 장면","mis":"K3-2-u6-X04"}],"explanation":["재미나 감동을 느낀 장면을 골라요.","그 장면에서 든 마음과 까닭을 써요.","장면은 그림으로도 나타내요."],"asset":{"type":"passage","lines":["1 자신이 인상 깊게 본 드라마나 만화 영화의 제목을 써 봅시다.","2 재미나 감동을 느낀 부분을 골라 글로 쓰고 장면을 그림으로 나타내 봅시다.","3 드라마나 만화 영화를 즐겁게 감상했나요?  ○○○","  재미나 감동을 느끼며 감상했나요?  ○○○","  재미나 감동을 느낀 부분이 드러나도록 잘 표현했나요?  ○○○"],"numbered":false,"title":"작품을 감상하고 느낀 재미나 감동 표현하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_b#19','kor',3,2,'u6','','tb_g3_2_kor_u6_review_b','unit_review','K3-2-u6-C26',3,'mc','auto','「체력을 기르기 위해 보드게임을 하자」의 두 이유(두뇌 발달, 친구와 친해짐)에 대한 생각으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X44','K3-2-u6-X25','K3-2-u6-X24']::text[],false,'{"seq":19,"concept":"K3-2-u6-C26","difficulty":3,"kind":"mc","stem":"「체력을 기르기 위해 보드게임을 하자」의 두 이유(두뇌 발달, 친구와 친해짐)에 대한 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"보드게임의 좋은 점이기는 하지만 체력을 기르자는 문제 상황과는 관련이 없다","correct":true},{"t":"이유가 그럴듯하니 의견도 알맞다","mis":"K3-2-u6-X44"},{"t":"두 이유는 같은 말을 되풀이한 것이다","mis":"K3-2-u6-X25"},{"t":"보드게임을 좋아하는 친구도 있으니 맞는 의견이다","mis":"K3-2-u6-X24"}],"explanation":["먼저 문제 상황을 다시 읽어요.","체력 문제에 보드게임은 어울리지 않아요.","이유가 그럴듯해도 의견이 문제를 풀지 못하면 고쳐야 해요."],"asset":{"type":"passage","lines":["제목: 체력을 기르기 위해 보드게임을 하자","(간추림) 운동량이 부족해서 체력이 떨어지는 학생이 많다.","(간추림) 그래서 우리 반에 보드게임을 가져와서 함께 놀아야 한다.","(간추림) 첫째, 보드게임을 하면 두뇌 발달에 도움이 된다.","(간추림) 둘째, 보드게임을 하면 친구들과 더 친해질 수 있다."],"numbered":false,"title":"문제 상황과 어울리지 않는 의견을 제시한 글 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_b#20','kor',3,2,'u6','','tb_g3_2_kor_u6_review_b','unit_review','K3-2-u6-C24',3,'mc','auto','안전 지킴이 글에서 의견을 뒷받침하는 이유로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X23','K3-2-u6-X22','K3-2-u6-X25']::text[],false,'{"seq":20,"concept":"K3-2-u6-C24","difficulty":3,"kind":"mc","stem":"안전 지킴이 글에서 의견을 뒷받침하는 이유로 알맞은 것은 무엇인가요?","options":[{"t":"지킴이가 경고를 주면 뛰는 학생이 줄어 안전사고도 줄어들기 때문","correct":true},{"t":"내가 지킴이를 가장 잘할 것 같기 때문","mis":"K3-2-u6-X23"},{"t":"복도가 교실보다 넓기 때문","mis":"K3-2-u6-X22"},{"t":"안전 지킴이는 안전을 지키기 때문","mis":"K3-2-u6-X25"}],"explanation":["의견대로 하면 무엇이 좋아지는지 찾아요.","경고를 주면 뛰는 학생이 줄어요.","지킴이가 서 있는 것만으로도 뛰면 안 된다는 것을 떠올려요."],"asset":{"type":"passage","lines":["(간추림) 복도에서 뛰는 학생과 부딪쳐 무릎을 다친 적이 있다. 뛰어다니면 위험하다.","안전 지킴이를 뽑아 쉬는 시간이나 점심시간에 활동하도록 하면 좋겠습니다.","(간추림) 지킴이가 경고를 주면 뛰는 학생과 안전사고가 줄어든다.","(간추림) 지킴이가 서 있는 것만으로도 뛰면 안 된다는 점을 떠올리게 된다."],"title":"같은 문제 상황에 대한 다른 의견 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_b#21','kor',3,2,'u6','','tb_g3_2_kor_u6_review_b','unit_review','K3-2-u6-C16',3,'mc','auto','공익 광고 「우리 개는 순한데」가 내세우는 가치로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X16','K3-2-u6-X46','K3-2-u6-X04']::text[],false,'{"seq":21,"concept":"K3-2-u6-C16","difficulty":3,"kind":"mc","stem":"공익 광고 「우리 개는 순한데」가 내세우는 가치로 알맞은 것은 무엇인가요?","options":[{"t":"공공질서를 지키며 서로의 처지를 배려하자","correct":true},{"t":"반려견 주인의 마음만 중요하다","mis":"K3-2-u6-X16"},{"t":"내가 무섭지 않으면 남도 무섭지 않다","mis":"K3-2-u6-X46"},{"t":"호랑이를 반려동물로 키우자","mis":"K3-2-u6-X04"}],"explanation":["반려견과 외출할 때 목줄을 하자는 광고예요.","반려동물을 좋아하는 사람도, 좋아하지 않는 사람도 있어요.","서로의 처지를 배려해야 해요."],"asset":{"type":"passage","lines":["[공익 광고] 반려견과 외출할 때 목줄을 착용해야 한다는 공익 광고","광고에서는 강아지를 호랑이로 표현했다."],"title":"공익 광고 「우리 개는 순한데」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_b#22','kor',3,2,'u6','','tb_g3_2_kor_u6_review_b','unit_review','K3-2-u6-C28',3,'mc','auto','『국어』 275쪽 5번에서 고쳐 쓰면 좋은 점 가운데 읽는 사람을 생각한 말은 무엇인가요?',ARRAY['K3-2-u6-X29','K3-2-u6-X27','K3-2-u6-X30']::text[],false,'{"seq":22,"concept":"K3-2-u6-C28","difficulty":3,"kind":"mc","stem":"『국어』 275쪽 5번에서 고쳐 쓰면 좋은 점 가운데 읽는 사람을 생각한 말은 무엇인가요?","options":[{"t":"읽는 사람의 처지에서 내가 제시한 의견이 효과적으로 표현되었는지 확인할 수 있다","correct":true},{"t":"고칠 곳이 있었으니 처음 글은 못 쓴 글이다","mis":"K3-2-u6-X29"},{"t":"글을 길게 늘릴 수 있다","mis":"K3-2-u6-X27"},{"t":"친구 글의 흠을 찾을 수 있다","mis":"K3-2-u6-X30"}],"explanation":["친구 1은 읽는 사람의 처지를 말했어요.","친구 2는 설득력, 친구 3은 문제 해결을 말했어요.","고쳐 쓰면 내 의견이 더 잘 전해져요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"읽는 사람의 처지에서 내가 제시한 의견이 효과적으로 표현되었는지 확인할 수 있어."},{"who":"친구 2","text":"잘못된 의견이나 이유를 고치면 내 의견을 더 설득력 있게 제시할 수 있어."},{"who":"친구 3","text":"문제 상황을 잘 해결할 수 있는 의견과 이유인지 다시 한번 확인할 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_b#23','kor',3,2,'u6','','tb_g3_2_kor_u6_review_b','unit_review','K3-2-u6-C11',4,'essay','teacher','만화 영화나 드라마를 볼 때 쓸 수 있는 감상 방법 두 가지를 쓰고, 각 방법으로 감상했을 때 느낄 수 있는 재미나 감동을 「건전지 엄마」나 「신통방통 니 맘 내 맘 계산기」에서 찾아 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-2-u6-C11","difficulty":4,"kind":"essay","stem":"만화 영화나 드라마를 볼 때 쓸 수 있는 감상 방법 두 가지를 쓰고, 각 방법으로 감상했을 때 느낄 수 있는 재미나 감동을 「건전지 엄마」나 「신통방통 니 맘 내 맘 계산기」에서 찾아 쓰세요.","answer_guide":{"answer":"예: 방법 1 — 배경 음악이나 효과음에 집중하며 보기: 신비가 아빠의 마음을 깨달을 때 흐르는 음악 때문에 감동이 더 잘 느껴졌다. 방법 2 — 인물의 표정이나 말투에 주의하며 보기: 달려가는 건전지 엄마의 표정에서 다급한 상황이 실감 났다.","scoring_points":["감상 방법 두 가지를 썼는가","각 방법으로 느낀 재미나 감동을 썼는가","작품 속 장면을 근거로 들었는가"]},"explanation":["표정·말투, 음악·효과음, 주제·교훈 가운데 골라요.","방법마다 느낀 장면을 찾아요.","감상 방법이 다르면 느끼는 것도 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_b#24','kor',3,2,'u6','','tb_g3_2_kor_u6_review_b','unit_review','K3-2-u6-C33',4,'essay','teacher','「더 나은 학교」를 주제로 우리 학급이나 학교의 문제 상황을 하나 골라(교과서에 나온 것 말고), 문제 상황 · 의견 · 이유 두 가지 · 맺음이 드러나게 의견을 제시하는 글을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u6-C33","difficulty":4,"kind":"essay","stem":"「더 나은 학교」를 주제로 우리 학급이나 학교의 문제 상황을 하나 골라(교과서에 나온 것 말고), 문제 상황 · 의견 · 이유 두 가지 · 맺음이 드러나게 의견을 제시하는 글을 쓰세요.","answer_guide":{"answer":"예: 비가 오는 날이면 교실 바닥이 젖어 미끄럽습니다. 그래서 교실 문 앞에 발판을 깔면 좋겠습니다. 첫째, 신발 바닥의 물기가 닦여 넘어지는 일이 줄기 때문입니다. 둘째, 청소할 때 바닥을 닦기 쉬워지기 때문입니다. 발판으로 모두가 안전한 교실을 만들고 싶습니다.","scoring_points":["우리가 함께 바꿀 수 있는 문제 상황을 골랐는가","의견과 겹치지 않는 이유 두 가지를 썼는가","맺음으로 글을 마무리했는가"]},"explanation":["우리가 실천으로 바꿀 수 있는 문제를 골라요.","이유는 겹치지 않게 두 가지 써요.","마지막에 바라는 모습으로 맺어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_b#25','kor',3,2,'u6','','tb_g3_2_kor_u6_review_b','unit_review','K3-2-u6-C1',4,'essay','teacher','『국어』 283쪽 「생활 속으로」처럼, 이 단원에서 공부한 내용 가운데 작품을 감상할 때 실천할 것과 의견을 말하거나 쓸 때 실천할 것을 하나씩 쓰고 어떻게 실천할지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u6-C1","difficulty":4,"kind":"essay","stem":"『국어』 283쪽 「생활 속으로」처럼, 이 단원에서 공부한 내용 가운데 작품을 감상할 때 실천할 것과 의견을 말하거나 쓸 때 실천할 것을 하나씩 쓰고 어떻게 실천할지 쓰세요.","answer_guide":{"answer":"예: 작품을 감상할 때 — 드라마를 볼 때 인물의 표정과 행동, 배경 음악까지 살피며 재미나 감동을 느낀 장면을 가족과 이야기하겠다. 의견을 쓸 때 — 학급 회의에서 의견을 낼 때 꼭 이유를 함께 말하고, 글로 쓸 때는 스스로 확인한 뒤 고쳐 쓰겠다.","scoring_points":["작품을 감상할 때 실천할 것을 썼는가","의견을 말하거나 쓸 때 실천할 것을 썼는가","어떻게 실천할지 구체적으로 썼는가"]},"explanation":["감상할 때 쓸 방법을 떠올려요.","의견을 낼 때 이유를 함께 말해요.","언제, 어떻게 할지 구체적으로 써요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"영화를 볼 때 인물의 표정이나 행동을 살피면서 재미나 감동을 느끼도록 감상할 거야."},{"who":"친구 2","text":"내 의견을 발표할 때 이유를 들어서 말할 거야."},{"who":"친구 3","text":"의견을 제시하는 글을 쓴 뒤 스스로 확인하고 고쳐 써 볼 거야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_c#1','kor',3,2,'u6','','tb_g3_2_kor_u6_review_c','unit_review','K3-2-u6-C1',1,'mc','auto','다음 가운데 의견을 제시하는 글에 어울리는 문장은 무엇인가요?',ARRAY['K3-2-u6-X47']::text[],false,'{"seq":1,"concept":"K3-2-u6-C1","difficulty":1,"kind":"mc","stem":"다음 가운데 의견을 제시하는 글에 어울리는 문장은 무엇인가요?","options":[{"t":"우리가 쓰는 말에 외국어가 많으니 소중한 한글을 바르게 쓰자.","correct":true},{"t":"영화에서 세종 대왕님이 백성을 걱정하는 장면에 가슴이 뭉클했다.","mis":"K3-2-u6-X47"},{"t":"한글을 만드는 장면에서 흐르던 음악이 오래 기억에 남는다.","mis":"K3-2-u6-X47"},{"t":"영화를 보고 나니 나도 모르게 눈물이 났다.","mis":"K3-2-u6-X47"}],"explanation":["의견을 제시하는 글에는 무엇을 하자는 생각이 담겨요.","「바르게 쓰자」는 문제 상황에 대한 의견이에요.","나머지는 작품을 보고 느낀 감동을 표현한 문장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_c#2','kor',3,2,'u6','','tb_g3_2_kor_u6_review_c','unit_review','K3-2-u6-C6',1,'mc','auto','작품을 보고 감상을 말할 때 알맞은 방법은 무엇인가요?',ARRAY['K3-2-u6-X06','K3-2-u6-X07','K3-2-u6-X02']::text[],false,'{"seq":2,"concept":"K3-2-u6-C6","difficulty":1,"kind":"mc","stem":"작품을 보고 감상을 말할 때 알맞은 방법은 무엇인가요?","options":[{"t":"어느 장면에서 어떤 마음이 들었는지 이어 말한다","correct":true},{"t":"줄거리만 처음부터 끝까지 말한다","mis":"K3-2-u6-X06"},{"t":"「그냥 좋았어.」라고만 말한다","mis":"K3-2-u6-X07"},{"t":"별 몇 개인지만 말한다","mis":"K3-2-u6-X02"}],"explanation":["어느 장면에서 + 어떤 마음이 들었는지 말해요.","그렇게 느낀 까닭도 붙이면 더 좋아요.","줄거리, 느낌, 점수만으로는 감상이 드러나지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_c#3','kor',3,2,'u6','','tb_g3_2_kor_u6_review_c','unit_review','K3-2-u6-C11',1,'mc','auto','시윤이는 「건전지 엄마처럼 나도 용기 있게 행동하고 싶어.」라고 했어요. 시윤이가 쓴 감상 방법은 무엇인가요?',ARRAY['K3-2-u6-X12','K3-2-u6-X13']::text[],false,'{"seq":3,"concept":"K3-2-u6-C11","difficulty":1,"kind":"mc","stem":"시윤이는 「건전지 엄마처럼 나도 용기 있게 행동하고 싶어.」라고 했어요. 시윤이가 쓴 감상 방법은 무엇인가요?","options":[{"t":"이야기의 주제나 인물에게서 얻을 수 있는 교훈을 떠올리며 보기","correct":true},{"t":"인물의 표정이나 말투에 주의하며 보기","mis":"K3-2-u6-X12"},{"t":"배경 음악이나 효과음에 집중하며 보기","mis":"K3-2-u6-X12"},{"t":"정해진 감동 장면 하나만 찾기","mis":"K3-2-u6-X13"}],"explanation":["시윤이는 건전지 엄마에게서 배울 점을 떠올렸어요.","용기 있게 행동하고 싶다는 마음이 생겼어요.","주제나 교훈을 떠올리는 것도 감상 방법이에요."],"asset":{"type":"speech","turns":[{"who":"하준","text":"아이들을 구하려고 달려가는 건전지 엄마의 표정을 보고 다급한 상황이 실감 났어."},{"who":"예서","text":"유치원 아이들이 낮잠 잘 때 평화로운 음악이 흐르다가 갑자기 멈춰서 무슨 일이 생길 것만 같았어."},{"who":"시윤","text":"아이들을 구한 건전지 엄마처럼 나도 용기 있게 행동하고 싶어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_c#4','kor',3,2,'u6','','tb_g3_2_kor_u6_review_c','unit_review','K3-2-u6-C43',1,'blank','auto','드라마에 나온 낱말로 문장을 만들었어요. 빈칸에 알맞은 낱말은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_c#5','kor',3,2,'u6','','tb_g3_2_kor_u6_review_c','unit_review','K3-2-u6-C19',1,'ox','auto','「신비는 친구들에게 과자를 나누어 주었습니다.」는 글쓴이의 의견을 나타낸 문장이에요.',ARRAY['K3-2-u6-X19']::text[],false,'{"seq":5,"concept":"K3-2-u6-C19","difficulty":1,"kind":"ox","stem":"「신비는 친구들에게 과자를 나누어 주었습니다.」는 글쓴이의 의견을 나타낸 문장이에요.","answer":"X","reason_options":[{"t":"드라마에서 실제로 있었던 일을 그대로 쓴 사실이기 때문에","correct":true},{"t":"드라마를 보고 쓴 문장은 모두 의견이기 때문에","mis":"K3-2-u6-X19"}],"mis":"K3-2-u6-X19","explanation":["신비가 과자를 나누어 준 것은 드라마에서 있었던 일이에요.","쓴 사람의 생각이 담기지 않았어요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉮ 신비는 친구들에게 과자를 나누어 주었습니다.","㉯ 마리는 신비에게 화장실을 양보해 주었습니다.","㉰ 신비는 니 맘 내 맘 계산기로 친구들의 마음을 들여다보았습니다.","㉱ 신비처럼 다른 친구들의 마음을 이해해 주어야 합니다."],"numbered":false,"title":"드라마를 보고 쓴 네 문장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_c#6','kor',3,2,'u6','','tb_g3_2_kor_u6_review_c','unit_review','K3-2-u6-C20',1,'mc','auto','의견을 제시하는 글에서 「왜냐하면 …… 때문이다.」로 쓴 문장은 무엇을 나타내나요?',ARRAY['K3-2-u6-X21']::text[],false,'{"seq":6,"concept":"K3-2-u6-C20","difficulty":1,"kind":"mc","stem":"의견을 제시하는 글에서 「왜냐하면 …… 때문이다.」로 쓴 문장은 무엇을 나타내나요?","options":[{"t":"그렇게 생각한 이유","correct":true},{"t":"자신의 의견","mis":"K3-2-u6-X21"},{"t":"문제 상황","mis":"K3-2-u6-X21"}],"explanation":["「왜냐하면」은 까닭을 말할 때 써요.","문장 끝 「때문이다」도 이유를 나타내요.","「첫째」, 「둘째」, 「또」로 이유를 이어 쓰기도 해요."],"asset":{"type":"passage","lines":["(간추림) 국어 시간에 드라마를 보았다. 신비는 친구들이 마음을 몰라주어 서운해했다.","1 신비가 경험한 것처럼 우리 주변에도 상대의 마음을 모른 채","  오해해 상대와 갈등을 겪는 일이 많다.","2 다른 사람의 마음을 잘 이해하기 위해서는 그 사람의 처지에서","  생각해 보는 연습이 필요하다고 생각한다.","3 왜냐하면 같은 일을 겪어도 사람마다 느끼는 마음이나 생각이 다를 수 있기 때문이다.","(간추림) 상대의 마음도 헤아려 주면 갈등이 줄어든다. 다투기 전에 상대의 처지를 생각해 보자."],"numbered":false,"title":"「다른 사람의 마음 이해하기」 — 『국어』 268쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_c#7','kor',3,2,'u6','','tb_g3_2_kor_u6_review_c','unit_review','K3-2-u6-C26',1,'ox','auto','고쳐 쓸 때에는 글의 내용뿐 아니라 띄어쓰기나 맞춤법도 살펴봐요.',ARRAY['K3-2-u6-X27']::text[],false,'{"seq":7,"concept":"K3-2-u6-C26","difficulty":1,"kind":"ox","stem":"고쳐 쓸 때에는 글의 내용뿐 아니라 띄어쓰기나 맞춤법도 살펴봐요.","answer":"O","reason_options":[{"t":"띄어쓰기와 맞춤법을 바르게 하면 전하려는 내용을 더 잘 전달할 수 있기 때문에","correct":true},{"t":"내용만 좋으면 맞춤법은 상관없기 때문에","mis":"K3-2-u6-X27"}],"mis":"K3-2-u6-X27","explanation":["문단을 구분하고 맞춤법, 띄어쓰기를 바르게 해요.","그러면 읽는 사람에게 내용이 더 잘 전달돼요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_c#8','kor',3,2,'u6','','tb_g3_2_kor_u6_review_c','unit_review','K3-2-u6-C41',1,'mc','auto','ㅞ(ㅜ+ㅔ)가 들어 있는 낱말은 무엇인가요?',ARRAY['K3-2-u6-X41']::text[],false,'{"seq":8,"concept":"K3-2-u6-C41","difficulty":1,"kind":"mc","stem":"ㅞ(ㅜ+ㅔ)가 들어 있는 낱말은 무엇인가요?","options":[{"t":"훼방","correct":true},{"t":"권리","mis":"K3-2-u6-X41"},{"t":"뒷길","mis":"K3-2-u6-X41"},{"t":"워낙","mis":"K3-2-u6-X41"}],"explanation":["「훼」에는 ㅜ와 ㅔ를 합친 ㅞ가 있어요.","「권」, 「워」에는 ㅝ, 「뒷」에는 ㅟ가 있어요.","모음자의 모양을 살피며 써요."],"asset":{"type":"passage","lines":["워낙 · 권리 · 궁궐 · 훼방 · 뒷길 · 귀여워하다","바위 위에 올라가니 뭐가 보이니?","궤짝 위에 귀여운 고양이가 낮잠을 자고 있다."],"title":"글씨 쓰기 — 『국어』 285쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_c#9','kor',3,2,'u6','','tb_g3_2_kor_u6_review_c','unit_review','K3-2-u6-C12',2,'blank','auto','『국어활동』 85쪽이에요. 유연이가 말한 빈칸에 알맞은 말은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_c#10','kor',3,2,'u6','','tb_g3_2_kor_u6_review_c','unit_review','K3-2-u6-C9',2,'mc','auto','[장면 1] 첫 장면에서 교과서에 미리 적혀 있는 건전지 엄마의 생각이나 마음은 무엇인가요?',ARRAY['K3-2-u6-X10']::text[],false,'{"seq":10,"concept":"K3-2-u6-C9","difficulty":2,"kind":"mc","stem":"[장면 1] 첫 장면에서 교과서에 미리 적혀 있는 건전지 엄마의 생각이나 마음은 무엇인가요?","options":[{"t":"“아이들에게 도움이 되도록 열심히 일해야지.”","correct":true},{"t":"“얘들아, 제발 일어나!”","mis":"K3-2-u6-X10"},{"t":"“여기서 포기할 수 없어.”","mis":"K3-2-u6-X10"},{"t":"“일하기 싫다. 그만 쉬어야지.”","mis":"K3-2-u6-X10"}],"explanation":["아직 위험한 일이 일어나기 전이에요.","교과서 표의 첫 칸에 예로 적혀 있어요.","「제발 일어나!」는 비상벨을 울릴 때의 마음이에요."],"asset":{"type":"passage","lines":["[장면 1] 첫 장면 → “아이들에게 도움이 되도록 열심히 일해야지.” (교과서에 적힌 예)","[장면 2] 위험을 무릅쓰고 아이들을 구하려고 나선 건전지 엄마","[장면 3] 있는 힘껏 비상벨을 울리는 건전지 엄마","[장면 4] 집에 와서 아기 건전지들을 안아 주고 행복하게 잠든 건전지 엄마"],"numbered":false,"title":"인물의 표정이나 행동 → 인물의 생각이나 마음 (『국어』 262쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_c#11','kor',3,2,'u6','','tb_g3_2_kor_u6_review_c','unit_review','K3-2-u6-C14',2,'mc','auto','마리가 화장실에서 신비에게 자리를 양보한 행동에서 알 수 있는 마리의 마음은 무엇인가요?',ARRAY['K3-2-u6-X10','K3-2-u6-X15','K3-2-u6-X46']::text[],false,'{"seq":11,"concept":"K3-2-u6-C14","difficulty":2,"kind":"mc","stem":"마리가 화장실에서 신비에게 자리를 양보한 행동에서 알 수 있는 마리의 마음은 무엇인가요?","options":[{"t":"친구를 생각하는 마음","correct":true},{"t":"신비를 귀찮아하는 마음","mis":"K3-2-u6-X10"},{"t":"행동만 보고는 마음을 알 수 없다","mis":"K3-2-u6-X15"},{"t":"신비에게 서운한 마음","mis":"K3-2-u6-X46"}],"explanation":["자리를 양보하는 것은 친구를 위하는 행동이에요.","말이 없어도 행동에서 마음을 알 수 있어요.","그래도 과자를 받았을 때 고맙다고 말했으면 더 좋았겠다고 생각할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_c#12','kor',3,2,'u6','','tb_g3_2_kor_u6_review_c','unit_review','K3-2-u6-C21',2,'sa','auto','「건강하고 행복한 급식 시간」에서 몸을 움직이는 힘을 얻기 위해 필요하다고 한 음식 종류는 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"K3-2-u6-C21","difficulty":2,"kind":"sa","stem":"「건강하고 행복한 급식 시간」에서 몸을 움직이는 힘을 얻기 위해 필요하다고 한 음식 종류는 무엇인가요? 두 글자로 쓰세요.","answer":["곡물","곡물 종류"],"explanation":["근육을 만드는 데에는 고기, 생선, 콩이 필요해요.","몸을 움직이는 힘에는 곡물이, 몸의 기능 조절에는 과일과 채소가 필요해요.","그래서 골고루 먹어야 한다는 이유가 돼요."],"asset":{"type":"passage","lines":["급식 시간에 편식을 하는 친구들이 종종 있습니다.","하지만 저는 음식을 골고루 먹어야 한다고 생각합니다.","첫째, 음식을 골고루 먹어야 우리 몸에 필요한 여러 영양소를 얻을 수 있습니다.","(간추림) 근육에는 고기·생선·콩, 힘에는 곡물, 몸의 조절에는 과일·채소.","둘째, 자신이 경험해 보지 못한 다양한 음식을 즐길 수 있습니다.","(간추림) 김치를 싫어했는데 김치볶음밥을 먹은 뒤 김치를 좋아하게 되었다.","음식을 골고루 먹으면서 건강하고 행복한 급식 시간을 만들어 봅시다."],"title":"「건강하고 행복한 급식 시간」 — 『국어』 270쪽"},"mis":"K3-2-u6-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_c#13','kor',3,2,'u6','','tb_g3_2_kor_u6_review_c','unit_review','K3-2-u6-C23',2,'mc','auto','의견과 이유가 적절한지 알아보는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X25','K3-2-u6-X27','K3-2-u6-X24']::text[],false,'{"seq":13,"concept":"K3-2-u6-C23","difficulty":2,"kind":"mc","stem":"의견과 이유가 적절한지 알아보는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"의견은 문제 해결에 도움이 되는 것이어야 한다","correct":true},{"t":"이유는 많이 겹칠수록 좋다","mis":"K3-2-u6-X25"},{"t":"글은 길어야 한다","mis":"K3-2-u6-X27"},{"t":"먼저 낸 의견이 옳다","mis":"K3-2-u6-X24"}],"explanation":["문제 상황에 어울리는 의견인지 보아요.","뒷받침하는 이유, 겹치지 않는 이유인지 보아요.","문제 해결에 도움이 되는지도 보아요."],"asset":{"type":"passage","lines":["● 주제나 문제 상황에 어울리는 의견을 내야 합니다.","● 의견을 (  ㉠  )하는 적절한 이유를 들어야 합니다.","● (  ㉡  )한 이유를 중복되지 않게 제시해야 합니다.","● 의견은 문제 해결에 (  ㉢  )이/가 되는 것이어야 합니다.","보기: 다양 · 도움 · 뒷받침"],"title":"의견과 이유가 적절한지 알아보는 방법 — 『국어』 271쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_c#14','kor',3,2,'u6','','tb_g3_2_kor_u6_review_c','unit_review','K3-2-u6-C22',2,'ox','auto','『국어활동』 86~87쪽 글의 이유 ㉮ 「시력이 나빠지기 때문」은 사용 시간을 정하자는 의견을 뒷받침해요.',ARRAY['K3-2-u6-X22']::text[],false,'{"seq":14,"concept":"K3-2-u6-C22","difficulty":2,"kind":"ox","stem":"『국어활동』 86~87쪽 글의 이유 ㉮ 「시력이 나빠지기 때문」은 사용 시간을 정하자는 의견을 뒷받침해요.","answer":"O","reason_options":[{"t":"오래 쓰면 생기는 나쁜 점이라 사용 시간을 정해야 하는 까닭이 되기 때문에","correct":true},{"t":"시력은 의견과 상관없는 몸 이야기이기 때문에","mis":"K3-2-u6-X22"}],"mis":"K3-2-u6-X22","explanation":["스마트 기기를 오래 쓰면 눈이 나빠질 수 있어요.","그래서 사용 시간을 정하자는 의견을 받쳐 줘요.","그래서 O예요."],"asset":{"type":"passage","lines":["문제 상황 — 스마트 기기를 지나치게 오래 사용하는 학생이 많다.","의견 — 스마트 기기 사용 시간을 알맞게 정해 스스로 지키자.","이유 ㉮ 스마트 기기를 너무 오래 사용하면 시력이 나빠지기 때문입니다.","이유 ㉯ 스마트 기기에 빠져 숙제나 독서처럼 꼭 해야 하는 일들을 못 할 수도 있기 때문입니다.","이유 ㉰ 스마트 기기는 우리에게 도움을 주기 때문입니다."],"numbered":false,"title":"『국어활동』 87쪽 예시 답안에 실린 문제 상황·의견·이유"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_c#15','kor',3,2,'u6','','tb_g3_2_kor_u6_review_c','unit_review','K3-2-u6-C37',2,'mc','auto','한 줄 평 「나도 미운 오리 새끼처럼 백조가 될 날이 오면 좋겠다.」에 담긴 것은 무엇인가요?',ARRAY['K3-2-u6-X37','K3-2-u6-X06','K3-2-u6-X04']::text[],false,'{"seq":15,"concept":"K3-2-u6-C37","difficulty":2,"kind":"mc","stem":"한 줄 평 「나도 미운 오리 새끼처럼 백조가 될 날이 오면 좋겠다.」에 담긴 것은 무엇인가요?","options":[{"t":"작품을 보고 든 자신의 바람(마음)","correct":true},{"t":"작품의 점수","mis":"K3-2-u6-X37"},{"t":"작품의 줄거리 전체","mis":"K3-2-u6-X06"},{"t":"작품과 상관없는 일","mis":"K3-2-u6-X04"}],"explanation":["미운 오리 새끼가 백조가 되는 장면을 떠올렸어요.","그 장면을 보고 든 자기 마음을 한 줄로 썼어요.","한 줄 평에는 느낀 곳과 마음이 담겨요."],"asset":{"type":"passage","lines":["① 자신이 재미나 감동을 느끼며 감상한 작품의 포스터를 꾸민다.","② 제목과 한 줄 평을 남긴다.","③ 사물함 문이나 알림판에 붙여서 공유한다.","④ 그 작품을 본 사람은 한 줄 평에 공감할 경우 모양 붙임딱지를 붙여 준다.","한 줄 평 예: 나도 미운 오리 새끼처럼 백조가 될 날이 오면 좋겠다."],"numbered":false,"title":"우리 반 추천 (만화) 영화 한 줄 평 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_c#16','kor',3,2,'u6','','tb_g3_2_kor_u6_review_c','unit_review','K3-2-u6-C30',2,'mc','auto','10~11차시에 ‘옐로 카펫’ 뉴스를 살펴본 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X01','K3-2-u6-X04','K3-2-u6-X31']::text[],false,'{"seq":16,"concept":"K3-2-u6-C30","difficulty":2,"kind":"mc","stem":"10~11차시에 ‘옐로 카펫’ 뉴스를 살펴본 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"의견을 내면 여럿이 겪는 문제를 해결하는 방법을 찾을 수 있음을 알려고","correct":true},{"t":"노란색 이름을 외우려고","mis":"K3-2-u6-X01"},{"t":"뉴스에 나온 사람을 칭찬하려고","mis":"K3-2-u6-X04"},{"t":"교통사고는 어쩔 수 없다는 것을 알려고","mis":"K3-2-u6-X31"}],"explanation":["한 시민 단체의 제안으로 옐로 카펫이 생겼어요.","그 뒤 어린이 교통사고 위험이 줄었어요.","의견을 내면 공공의 문제를 푸는 방법을 찾을 수 있어요."],"asset":{"type":"passage","lines":["(간추림) 어린이 교통사고를 줄이려고 한 시민 단체의 제안으로","학교 앞 횡단보도 부근 벽면에 노란색을 칠한 ‘옐로 카펫’을 만들었다.","(간추림) 눈에 잘 띄는 것만으로도 교통사고 위험을 크게 줄일 수 있다고 한다.","초등학생: 파란불이 켜지면 막 달려갔는데, 한 번 쉬었다 가게 되니까 더 안전해요."],"title":"뉴스 「“교통사고 줄여요”…… 주민들이 만든 옐로 카펫」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_c#17','kor',3,2,'u6','','tb_g3_2_kor_u6_review_c','unit_review','K3-2-u6-C34',3,'error','auto','단원을 마무리하며 친구들이 한 말이에요. 알맞지 않은 말은 무엇인가요?',ARRAY['K3-2-u6-X29','K3-2-u6-X44','K3-2-u6-X22']::text[],false,'{"seq":17,"concept":"K3-2-u6-C34","difficulty":3,"kind":"error","stem":"단원을 마무리하며 친구들이 한 말이에요. 알맞지 않은 말은 무엇인가요?","options":[{"t":"“고쳐 쓸 부분이 있으면 내 글은 못 쓴 글이야.”","correct":true,"mis_target":"K3-2-u6-X29"},{"t":"“주제나 문제 상황에 어울리는 의견인지 확인해야 해.”","mis":"K3-2-u6-X44"},{"t":"“이유가 의견을 뒷받침하는지 살펴봐야 해.”","mis":"K3-2-u6-X22"}],"explanation":["고쳐 쓸 부분을 찾는 것은 글을 다시 읽었다는 뜻이에요.","고치면 글이 더 좋아져요.","고칠 곳이 있다고 못 쓴 글이 아니에요."],"asset":{"type":"passage","lines":["㉮ 주제나 문제 상황에 어울리는 의견을 쓴다.","㉯ 의견을 뒷받침하는 적절한 이유를 쓴다.","㉰ 같은 이유를 여러 번 제시한다.","㉱ 고쳐 쓸 부분이 있는지 확인하고 알맞게 고쳐 쓴다."],"numbered":false,"title":"스스로 확인하기 — 『국어』 283쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_c#18','kor',3,2,'u6','','tb_g3_2_kor_u6_review_c','unit_review','K3-2-u6-C2',3,'mc','auto','느낀 재미나 감동을 글로 표현하기 어려워하는 친구에게 해 줄 수 있는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X01','K3-2-u6-X02','K3-2-u6-X13']::text[],false,'{"seq":18,"concept":"K3-2-u6-C2","difficulty":3,"kind":"mc","stem":"느낀 재미나 감동을 글로 표현하기 어려워하는 친구에게 해 줄 수 있는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"그림으로 나타내게 하고, 그렇게 표현한 까닭을 말로 설명하게 한다","correct":true},{"t":"줄거리를 받아 적게 한다","mis":"K3-2-u6-X01"},{"t":"점수만 매기게 한다","mis":"K3-2-u6-X02"},{"t":"선생님이 정해 준 감동 장면을 그대로 쓰게 한다","mis":"K3-2-u6-X13"}],"explanation":["재미나 감동은 글로도, 그림으로도 표현할 수 있어요.","그림으로 나타낸 뒤 까닭을 말하면 돼요.","정해진 감동 장면은 없어요."],"asset":{"type":"passage","lines":["1 자신이 인상 깊게 본 드라마나 만화 영화의 제목을 써 봅시다.","2 재미나 감동을 느낀 부분을 골라 글로 쓰고 장면을 그림으로 나타내 봅시다.","3 드라마나 만화 영화를 즐겁게 감상했나요?  ○○○","  재미나 감동을 느끼며 감상했나요?  ○○○","  재미나 감동을 느낀 부분이 드러나도록 잘 표현했나요?  ○○○"],"numbered":false,"title":"작품을 감상하고 느낀 재미나 감동 표현하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_c#19','kor',3,2,'u6','','tb_g3_2_kor_u6_review_c','unit_review','K3-2-u6-C27',3,'mc','auto','「체력을 기르기 위해 달리기를 하자」의 3번 줄 「친구들과 함께 달리면 운동 효과가 더 좋아지기 때문이다.」를 어떻게 하면 좋을까요?',ARRAY['K3-2-u6-X28','K3-2-u6-X27','K3-2-u6-X23']::text[],false,'{"seq":19,"concept":"K3-2-u6-C27","difficulty":3,"kind":"mc","stem":"「체력을 기르기 위해 달리기를 하자」의 3번 줄 「친구들과 함께 달리면 운동 효과가 더 좋아지기 때문이다.」를 어떻게 하면 좋을까요?","options":[{"t":"의견을 뒷받침하는 알맞은 이유이므로 그대로 둔다","correct":true},{"t":"이유는 모두 지우는 것이 좋다","mis":"K3-2-u6-X28"},{"t":"문장이 길어서 짧게 고친다","mis":"K3-2-u6-X27"},{"t":"나만 잘한다는 이유라서 바꾼다","mis":"K3-2-u6-X23"}],"explanation":["함께 달리면 힘이 나서 더 열심히 달릴 수 있어요.","함께 달리기를 하자는 의견과 잘 이어져요.","고칠 곳은 5번 줄이에요."],"asset":{"type":"passage","lines":["제목: 체력을 기르기 위해 달리기를 하자","1 요즘 운동량이 부족해서 체력이 약한 어린이가 많다.","2 그래서 체력을 기르기 위해 점심시간에 함께 달리기를 하면 좋겠다.","3 첫째, 친구들과 함께 달리면 운동 효과가 더 좋아지기 때문이다.","4 (간추림) 여럿이 같이 달리면 힘이 나서 더 열심히 달릴 수 있다.","5 둘째, 내가 우리 반에서 달리기를 가장 잘하기 때문이다.","6 (간추림) 기록을 재면 내가 가장 빠르기 때문에 달리기는 항상 자신이 있다.","7 그래서 우리 반 친구들이 다 함께 달리기를 하며 체력을 길렀으면 좋겠다."],"numbered":false,"title":"고쳐 쓸 글 — 『국어』 274쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_c#20','kor',3,2,'u6','','tb_g3_2_kor_u6_review_c','unit_review','K3-2-u6-C24',3,'ox','auto','같은 문제 상황이라도 사람마다 다른 의견이 나올 수 있어요.',ARRAY['K3-2-u6-X24']::text[],false,'{"seq":20,"concept":"K3-2-u6-C24","difficulty":3,"kind":"ox","stem":"같은 문제 상황이라도 사람마다 다른 의견이 나올 수 있어요.","answer":"O","reason_options":[{"t":"복도에서 뛰는 문제에도 표지판, 안전 지킴이처럼 여러 의견이 나왔기 때문에","correct":true},{"t":"한 문제에는 정답 의견이 하나뿐이기 때문에","mis":"K3-2-u6-X24"}],"mis":"K3-2-u6-X24","explanation":["같은 문제 상황에서도 해결 방안은 다양해요.","어느 의견이든 이유가 의견을 받쳐 주는지가 중요해요.","그래서 O예요."],"asset":{"type":"passage","lines":["(간추림) 복도에서 뛰는 학생과 부딪쳐 무릎을 다친 적이 있다. 뛰어다니면 위험하다.","안전 지킴이를 뽑아 쉬는 시간이나 점심시간에 활동하도록 하면 좋겠습니다.","(간추림) 지킴이가 경고를 주면 뛰는 학생과 안전사고가 줄어든다.","(간추림) 지킴이가 서 있는 것만으로도 뛰면 안 된다는 점을 떠올리게 된다."],"title":"같은 문제 상황에 대한 다른 의견 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_c#21','kor',3,2,'u6','','tb_g3_2_kor_u6_review_c','unit_review','K3-2-u6-C14',3,'mc','auto','「다른 사람의 마음을 이해하지 못한다면 어떤 일이 생길까요?」라는 물음에 알맞은 답은 무엇인가요?',ARRAY['K3-2-u6-X15','K3-2-u6-X18','K3-2-u6-X16']::text[],false,'{"seq":21,"concept":"K3-2-u6-C14","difficulty":3,"kind":"mc","stem":"「다른 사람의 마음을 이해하지 못한다면 어떤 일이 생길까요?」라는 물음에 알맞은 답은 무엇인가요?","options":[{"t":"신비처럼 친구들의 마음을 오해할 수 있다","correct":true},{"t":"친구들이 소중히 여기는 것이 저절로 드러난다","mis":"K3-2-u6-X15"},{"t":"서운한 일을 덮어 두면 다 해결된다","mis":"K3-2-u6-X18"},{"t":"누가 옳은지 금방 가릴 수 있다","mis":"K3-2-u6-X16"}],"explanation":["신비는 친구들의 처지를 생각하지 못했어요.","그래서 친구들이 고마워하지 않는다고 오해했어요.","상대의 처지에서 생각하면 오해를 줄일 수 있어요."],"asset":{"type":"passage","lines":["등장인물 — 신비, 용용이(살아남은 단 하나의 공룡), 아빠, 마리, 기동","(간추림) 신비는 주변 사람들의 행동을 자기중심적으로 생각해","친구들의 마음을 오해했다.","(간추림) 용용이가 마법으로 ‘니 맘 내 맘 계산기’를 주었다.","(간추림) 신비는 계산기로 친구들과 가족의 진심을 깨닫고 반성했다."],"title":"「신통방통 니 맘 내 맘 계산기」 간추린 줄거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_c#22','kor',3,2,'u6','','tb_g3_2_kor_u6_review_c','unit_review','K3-2-u6-C29',3,'error','auto','친구의 글을 읽고 한 말이에요. 알맞지 않은 말은 무엇인가요?',ARRAY['K3-2-u6-X30','K3-2-u6-X29']::text[],false,'{"seq":22,"concept":"K3-2-u6-C29","difficulty":3,"kind":"error","stem":"친구의 글을 읽고 한 말이에요. 알맞지 않은 말은 무엇인가요?","options":[{"t":"“네 글은 틀린 게 많아서 읽기 싫어.”","correct":true,"mis_target":"K3-2-u6-X30"},{"t":"“첫째 이유가 의견과 잘 이어져.”","mis":"K3-2-u6-X30"},{"t":"“둘째 이유는 문제 해결과 관련이 적어 보여서 바꾸면 좋겠어.”","mis":"K3-2-u6-X29"}],"explanation":["잘된 점을 말해 주는 것은 좋아요.","고칠 부분은 이유와 함께 말해요.","비난하거나 무시하는 말은 하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_c#23','kor',3,2,'u6','','tb_g3_2_kor_u6_review_c','unit_review','K3-2-u6-C12',4,'essay','teacher','시 「눈사람 넷」에서 재미나 감동을 느낀 부분을 하나 골라 그 까닭을 쓰고, 그 부분을 읽을 때 떠오르는 장면이나 비슷한 경험을 쓰세요. (『국어활동』 85쪽 예와 다른 까닭으로 써 보세요.)','{}'::text[],false,'{"seq":23,"concept":"K3-2-u6-C12","difficulty":4,"kind":"essay","stem":"시 「눈사람 넷」에서 재미나 감동을 느낀 부분을 하나 골라 그 까닭을 쓰고, 그 부분을 읽을 때 떠오르는 장면이나 비슷한 경험을 쓰세요. (『국어활동』 85쪽 예와 다른 까닭으로 써 보세요.)","answer_guide":{"answer":"예: 「눈 세상 데리고 간다.」가 재미있었다. 몸에 붙은 눈을 털지 않고 그대로 집까지 가는 모습이 떠올라 웃음이 났다. 나도 눈싸움을 하고 집에 들어갔다가 현관에 눈이 잔뜩 떨어져서 엄마랑 웃은 적이 있다.","scoring_points":["시에서 재미나 감동을 느낀 부분을 골랐는가","그 까닭을 썼는가","떠오르는 장면이나 비슷한 경험을 썼는가"]},"explanation":["시를 읽고 떠오르는 장면을 상상해요.","비슷한 내 경험을 떠올려요.","사람마다 느끼는 부분과 까닭은 달라요."],"asset":{"type":"passage","lines":["눈사람 넷, 집에 간다","눈 세상 데리고 간다.","[친구들의 말에서] 눈이 펑펑 내리고, 눈을 맞은 친구들이 집에 간다."],"title":"시 「눈사람 넷」 끝부분 — 『국어활동』 84쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_c#24','kor',3,2,'u6','','tb_g3_2_kor_u6_review_c','unit_review','K3-2-u6-C30',4,'essay','teacher','우리 반이나 학교의 문제 상황을 하나 골라, 「……하지 말자」가 아니라 문제를 근본적으로 해결할 방법을 의견으로 쓰고 그렇게 생각한 이유를 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u6-C30","difficulty":4,"kind":"essay","stem":"우리 반이나 학교의 문제 상황을 하나 골라, 「……하지 말자」가 아니라 문제를 근본적으로 해결할 방법을 의견으로 쓰고 그렇게 생각한 이유를 쓰세요.","answer_guide":{"answer":"예: 문제 상황 — 우유갑을 아무 데나 두어 교실에서 냄새가 난다. 의견 — 우유갑을 헹궈 펼쳐 모으는 상자를 교실 뒤에 두고 당번이 정리하자. 이유 — 버릴 자리가 정해지면 아무 데나 두지 않게 되고, 헹궈 모으면 냄새도 나지 않기 때문이다.","scoring_points":["문제 상황을 썼는가","하지 말자는 말이 아니라 해결 방법을 의견으로 썼는가","의견을 뒷받침하는 이유를 썼는가"]},"explanation":["「……하지 말자」만으로는 문제가 잘 풀리지 않아요.","무엇을 하면 문제가 풀릴지 생각해요.","그 방법이 왜 좋은지 이유를 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_c#25','kor',3,2,'u6','','tb_g3_2_kor_u6_review_c','unit_review','K3-2-u6-C21',4,'essay','teacher','의견과 이유 카드 놀이를 해요. 주제 「점심시간」으로 의견 카드 한 장과 이유 카드 두 장을 직접 쓰고, 세 카드를 이어 짧은 글로 구성하세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u6-C21","difficulty":4,"kind":"essay","stem":"의견과 이유 카드 놀이를 해요. 주제 「점심시간」으로 의견 카드 한 장과 이유 카드 두 장을 직접 쓰고, 세 카드를 이어 짧은 글로 구성하세요.","answer_guide":{"answer":"예: 의견 카드 — 점심시간에 반별로 운동장을 나누어 쓰면 좋겠다. 이유 카드 1 — 한꺼번에 몰리지 않아 부딪쳐 다치는 일이 줄기 때문이다. 이유 카드 2 — 차례가 정해지면 다툼 없이 놀 수 있기 때문이다. 짧은 글 — 점심시간에 반별로 운동장을 나누어 쓰면 좋겠다. 한꺼번에 몰리지 않아 부딪쳐 다치는 일이 줄기 때문이다. 또 차례가 정해지면 다툼 없이 놀 수 있기 때문이다.","scoring_points":["의견 카드를 「……면 좋겠다/……해야 한다」로 썼는가","의견을 뒷받침하는 이유 카드 두 장을 썼는가","세 카드를 이어 짧은 글로 구성했는가"]},"explanation":["의견과 이유를 가려 카드를 써요.","이유는 「……때문이다」로 써요.","카드를 이어 짧은 글을 만들어요."],"asset":{"type":"passage","lines":["1모둠 · 점심시간은 매우 중요하다.","1모둠 · 급식은 영양소가 풍부한 식사이기 때문이다.","1모둠 · 급식 시간을 더 늘려야 한다.","1모둠 · 놀기 위해서 식사를 너무 빨리하면 안 되기 때문이다.","2모둠 · 점심시간에는 운동장에 나가서 놀아야 한다.","2모둠 · 요즘 초등학생들은 야외 활동 시간이 부족하기 때문이다.","2모둠 · 점심시간을 더 늘려야 한다.","2모둠 · 식사를 소화하는 것도 다음 수업 시간에 좋기 때문이다."],"numbered":false,"title":"의견과 이유 카드 놀이 — 주제: 점심시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_d#1','kor',3,2,'u6','','tb_g3_2_kor_u6_review_d','unit_review','K3-2-u6-C1',1,'mc','auto','「영화를 보고 나서 백성을 사랑하는 세종 대왕님의 마음에 가슴이 뭉클했다.」는 어떤 글에 어울리는 문장인가요?',ARRAY['K3-2-u6-X47']::text[],false,'{"seq":1,"concept":"K3-2-u6-C1","difficulty":1,"kind":"mc","stem":"「영화를 보고 나서 백성을 사랑하는 세종 대왕님의 마음에 가슴이 뭉클했다.」는 어떤 글에 어울리는 문장인가요?","options":[{"t":"재미나 감동을 표현하는 글","correct":true},{"t":"의견을 제시하는 글","mis":"K3-2-u6-X47"},{"t":"문제 상황을 알리는 글","mis":"K3-2-u6-X47"}],"explanation":["작품을 보고 느낀 마음이 드러나 있어요.","무엇을 하자는 의견이나 이유는 없어요.","그래서 재미나 감동을 표현하는 글에 어울려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_d#2','kor',3,2,'u6','','tb_g3_2_kor_u6_review_d','unit_review','K3-2-u6-C7',1,'mc','auto','친구 1은 「나도 꿈을 이루기 위해 열심히 노력해야겠다.」라고 했어요. 친구 1은 무엇과 무엇을 이어 감상했나요?',ARRAY['K3-2-u6-X04','K3-2-u6-X01','K3-2-u6-X02']::text[],false,'{"seq":2,"concept":"K3-2-u6-C7","difficulty":1,"kind":"mc","stem":"친구 1은 「나도 꿈을 이루기 위해 열심히 노력해야겠다.」라고 했어요. 친구 1은 무엇과 무엇을 이어 감상했나요?","options":[{"t":"작품 속 장면과 자신의 삶","correct":true},{"t":"작품과 상관없는 다른 이야기","mis":"K3-2-u6-X04"},{"t":"작품의 쪽수와 글자 수","mis":"K3-2-u6-X01"},{"t":"친구들이 매긴 점수","mis":"K3-2-u6-X02"}],"explanation":["진짜 델이 생긴 장면을 보았어요.","자신도 꿈을 이루려고 노력하겠다고 했어요.","작품을 자신의 삶과 이어 보면 감동이 더 커져요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"1학기 때 교과서에서 읽은 「레오의 특별한 꿈」이 어때?"},{"who":"친구 2","text":"가짜 ‘델’을 달고 있다고 친구들에게 놀림받은 레오가 무척 안쓰러웠어. 나도 친구들에게 놀림받았을 때 속상했거든."},{"who":"친구 3","text":"신비한 능력이 없어도 좋으니까 ‘델’ 모양만이라도 만들어 달라고 마법사에게 조르는 레오의 모습이 조금은 재미있게 느껴졌어. 부모님께 물건을 사 달라고 부탁하는 내 모습 같았거든."},{"who":"친구 1","text":"그랬구나. 나는 레오가 진짜 꿈에 대해 생각하자 진짜 ‘델’이 생긴 장면이 감동적이었어. 나도 꿈을 이루기 위해 열심히 노력해야겠다고 생각했어."},{"who":"친구 2","text":"같은 작품을 보고도 재미나 감동을 느낀 부분이 다를 수 있구나."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_d#3','kor',3,2,'u6','','tb_g3_2_kor_u6_review_d','unit_review','K3-2-u6-C11',1,'ox','auto','만화 영화를 감상하는 방법은 인물의 표정을 살피는 것 한 가지뿐이에요.',ARRAY['K3-2-u6-X12']::text[],false,'{"seq":3,"concept":"K3-2-u6-C11","difficulty":1,"kind":"ox","stem":"만화 영화를 감상하는 방법은 인물의 표정을 살피는 것 한 가지뿐이에요.","answer":"X","reason_options":[{"t":"배경 음악·효과음에 집중하거나 주제나 교훈을 떠올리며 보는 방법도 있기 때문에","correct":true},{"t":"표정 말고 다른 것을 보면 잘못 감상한 것이기 때문에","mis":"K3-2-u6-X12"}],"mis":"K3-2-u6-X12","explanation":["하준, 예서, 시윤이는 서로 다른 방법으로 감상했어요.","재미나 감동을 느끼는 방법은 여러 가지예요.","그래서 X예요."],"asset":{"type":"speech","turns":[{"who":"하준","text":"아이들을 구하려고 달려가는 건전지 엄마의 표정을 보고 다급한 상황이 실감 났어."},{"who":"예서","text":"유치원 아이들이 낮잠 잘 때 평화로운 음악이 흐르다가 갑자기 멈춰서 무슨 일이 생길 것만 같았어."},{"who":"시윤","text":"아이들을 구한 건전지 엄마처럼 나도 용기 있게 행동하고 싶어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_d#4','kor',3,2,'u6','','tb_g3_2_kor_u6_review_d','unit_review','K3-2-u6-C43',1,'mc','auto','「신통방통 니 맘 내 맘 계산기」의 내용으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X11','K3-2-u6-X16','K3-2-u6-X04']::text[],false,'{"seq":4,"concept":"K3-2-u6-C43","difficulty":1,"kind":"mc","stem":"「신통방통 니 맘 내 맘 계산기」의 내용으로 알맞은 것은 무엇인가요?","options":[{"t":"자기 마음만 생각해 친구들을 오해했던 신비가 계산기로 진심을 깨닫고 반성한다","correct":true},{"t":"신비가 계산기로 수학 시험에서 1등을 한다","mis":"K3-2-u6-X11"},{"t":"친구들이 잘못해서 신비에게 사과한다","mis":"K3-2-u6-X16"},{"t":"용용이가 공룡 나라로 돌아간다","mis":"K3-2-u6-X04"}],"explanation":["신비는 친구들이 고마워하지 않는다고 서운해했어요.","용용이가 준 계산기로 친구들과 아빠의 진심을 알았어요.","신비는 오해를 깨닫고 반성했어요."],"asset":{"type":"passage","lines":["등장인물 — 신비, 용용이(살아남은 단 하나의 공룡), 아빠, 마리, 기동","(간추림) 신비는 주변 사람들의 행동을 자기중심적으로 생각해","친구들의 마음을 오해했다.","(간추림) 용용이가 마법으로 ‘니 맘 내 맘 계산기’를 주었다.","(간추림) 신비는 계산기로 친구들과 가족의 진심을 깨닫고 반성했다."],"title":"「신통방통 니 맘 내 맘 계산기」 간추린 줄거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_d#5','kor',3,2,'u6','','tb_g3_2_kor_u6_review_d','unit_review','K3-2-u6-C19',1,'blank','auto','빈칸에 들어갈 말을 차례대로 바르게 짝지은 것은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_d#6','kor',3,2,'u6','','tb_g3_2_kor_u6_review_d','unit_review','K3-2-u6-C20',1,'ox','auto','의견을 제시하는 글에서 문제 상황은 쓰지 않아도 돼요.',ARRAY['K3-2-u6-X21']::text[],false,'{"seq":6,"concept":"K3-2-u6-C20","difficulty":1,"kind":"ox","stem":"의견을 제시하는 글에서 문제 상황은 쓰지 않아도 돼요.","answer":"X","reason_options":[{"t":"무엇이 문제인지 알아야 의견이 왜 필요한지 알 수 있기 때문에","correct":true},{"t":"의견과 이유만 있으면 문제 상황은 필요 없기 때문에","mis":"K3-2-u6-X21"}],"mis":"K3-2-u6-X21","explanation":["「다른 사람의 마음 이해하기」도 문제 상황부터 썼어요.","문제 상황 → 의견 → 이유 차례예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_d#7','kor',3,2,'u6','','tb_g3_2_kor_u6_review_d','unit_review','K3-2-u6-C26',1,'mc','auto','친구가 쓴 「체력을 기르기 위해 달리기를 하자」에서 둘째 이유(5번 줄)를 고쳐 써야 하는 까닭은 무엇인가요?',ARRAY['K3-2-u6-X27','K3-2-u6-X29']::text[],false,'{"seq":7,"concept":"K3-2-u6-C26","difficulty":1,"kind":"mc","stem":"친구가 쓴 「체력을 기르기 위해 달리기를 하자」에서 둘째 이유(5번 줄)를 고쳐 써야 하는 까닭은 무엇인가요?","options":[{"t":"의견을 뒷받침하지 않는 이유이기 때문","correct":true},{"t":"문장이 너무 길기 때문","mis":"K3-2-u6-X27"},{"t":"고칠 곳이 있으니 글 전체를 다시 써야 하기 때문","mis":"K3-2-u6-X29"},{"t":"맞춤법이 틀렸기 때문","mis":"K3-2-u6-X27"}],"explanation":["5번 줄은 「내가 달리기를 가장 잘하기 때문」이에요.","나만 잘한다는 것은 의견을 받쳐 주지 못해요.","그 줄만 알맞은 이유로 고쳐 쓰면 돼요."],"asset":{"type":"passage","lines":["제목: 체력을 기르기 위해 달리기를 하자","1 요즘 운동량이 부족해서 체력이 약한 어린이가 많다.","2 그래서 체력을 기르기 위해 점심시간에 함께 달리기를 하면 좋겠다.","3 첫째, 친구들과 함께 달리면 운동 효과가 더 좋아지기 때문이다.","4 (간추림) 여럿이 같이 달리면 힘이 나서 더 열심히 달릴 수 있다.","5 둘째, 내가 우리 반에서 달리기를 가장 잘하기 때문이다.","6 (간추림) 기록을 재면 내가 가장 빠르기 때문에 달리기는 항상 자신이 있다.","7 그래서 우리 반 친구들이 다 함께 달리기를 하며 체력을 길렀으면 좋겠다."],"numbered":false,"title":"고쳐 쓸 글 — 『국어』 274쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_d#8','kor',3,2,'u6','','tb_g3_2_kor_u6_review_d','unit_review','K3-2-u6-C41',1,'mc','auto','ㅟ(ㅜ+ㅣ)가 들어 있는 낱말은 무엇인가요?',ARRAY['K3-2-u6-X41']::text[],false,'{"seq":8,"concept":"K3-2-u6-C41","difficulty":1,"kind":"mc","stem":"ㅟ(ㅜ+ㅣ)가 들어 있는 낱말은 무엇인가요?","options":[{"t":"뒷길","correct":true},{"t":"궁궐","mis":"K3-2-u6-X41"},{"t":"훼방","mis":"K3-2-u6-X41"},{"t":"워낙","mis":"K3-2-u6-X41"}],"explanation":["「뒷」에는 ㅜ와 ㅣ를 합친 ㅟ가 있어요.","「궐」, 「워」는 ㅝ, 「훼」는 ㅞ예요.","「바위」, 「귀」에도 ㅟ가 있어요."],"asset":{"type":"passage","lines":["워낙 · 권리 · 궁궐 · 훼방 · 뒷길 · 귀여워하다","바위 위에 올라가니 뭐가 보이니?","궤짝 위에 귀여운 고양이가 낮잠을 자고 있다."],"title":"글씨 쓰기 — 『국어』 285쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_d#9','kor',3,2,'u6','','tb_g3_2_kor_u6_review_d','unit_review','K3-2-u6-C11',2,'mc','auto','「눈사람 넷」 같은 시를 감상하며 재미나 감동을 느끼는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X12','K3-2-u6-X13','K3-2-u6-X01']::text[],false,'{"seq":9,"concept":"K3-2-u6-C11","difficulty":2,"kind":"mc","stem":"「눈사람 넷」 같은 시를 감상하며 재미나 감동을 느끼는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"소리 내어 낭송하며 시의 느낌을 살려 본다","correct":true},{"t":"시에 나온 낱말의 개수만 센다","mis":"K3-2-u6-X12"},{"t":"정해진 감동 한 곳만 찾고 덮는다","mis":"K3-2-u6-X13"},{"t":"지은이 이름만 외운다","mis":"K3-2-u6-X01"}],"explanation":["시를 낭송하면 말의 재미가 살아나요.","떠오르는 장면을 상상하거나 비슷한 경험을 떠올려도 좋아요.","감상하는 방법은 여러 가지예요."],"asset":{"type":"passage","lines":["눈사람 넷, 집에 간다","눈 세상 데리고 간다.","[친구들의 말에서] 눈이 펑펑 내리고, 눈을 맞은 친구들이 집에 간다."],"title":"시 「눈사람 넷」 끝부분 — 『국어활동』 84쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_d#10','kor',3,2,'u6','','tb_g3_2_kor_u6_review_d','unit_review','K3-2-u6-C8',2,'mc','auto','「건전지 엄마」처럼 대사가 없는 만화 영화를 볼 때 인물의 마음을 알아보는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X09','K3-2-u6-X04','K3-2-u6-X01']::text[],false,'{"seq":10,"concept":"K3-2-u6-C8","difficulty":2,"kind":"mc","stem":"「건전지 엄마」처럼 대사가 없는 만화 영화를 볼 때 인물의 마음을 알아보는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"인물의 표정과 몸짓, 행동을 보고 마음을 상상한다","correct":true},{"t":"인물의 키와 옷 색깔을 본다","mis":"K3-2-u6-X09"},{"t":"나오지 않는 대사를 지어내 정답이라고 정한다","mis":"K3-2-u6-X04"},{"t":"소리를 끄고 줄거리만 외운다","mis":"K3-2-u6-X01"}],"explanation":["대사가 없어도 표정과 몸짓에 마음이 드러나요.","앞에서 일어난 일과 이어 상상해요.","사람마다 생각한 대사는 다를 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_d#11','kor',3,2,'u6','','tb_g3_2_kor_u6_review_d','unit_review','K3-2-u6-C17',2,'ox','auto','뜨거운 의자 놀이에서는 인물이 드라마 속에서 답할 수 있는, 인물의 마음이나 까닭을 묻는 질문을 해요.',ARRAY['K3-2-u6-X17']::text[],false,'{"seq":11,"concept":"K3-2-u6-C17","difficulty":2,"kind":"ox","stem":"뜨거운 의자 놀이에서는 인물이 드라마 속에서 답할 수 있는, 인물의 마음이나 까닭을 묻는 질문을 해요.","answer":"O","reason_options":[{"t":"묻고 답하며 서로의 처지를 이해하고 인물이 추구하는 가치를 알아 갈 수 있기 때문에","correct":true},{"t":"배우 이름이나 촬영 장소처럼 드라마 밖의 일을 물어야 재미있기 때문에","mis":"K3-2-u6-X17"}],"mis":"K3-2-u6-X17","explanation":["의자에 앉은 친구는 그 인물이 되어 대답해요.","인물의 마음을 묻는 질문을 해야 대답할 수 있어요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 교실 앞에 의자 하나를 놓는다.","② 드라마에 나오는 인물 가운데에서 한 명을 정한다.","③ 한 친구가 정한 인물이 되어 의자에 앉는다.","④ 다른 친구들은 그 인물에게 궁금한 점을 묻는다.","⑤ 의자에 앉은 친구는 그 인물이 되어 대답한다."],"numbered":false,"title":"인물에게 묻고 답하기(뜨거운 의자) — 『국어』 266쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_d#12','kor',3,2,'u6','','tb_g3_2_kor_u6_review_d','unit_review','K3-2-u6-C20',2,'mc','auto','「다른 사람의 마음 이해하기」에서 3번 문장이 하는 일은 무엇인가요?',ARRAY['K3-2-u6-X21']::text[],false,'{"seq":12,"concept":"K3-2-u6-C20","difficulty":2,"kind":"mc","stem":"「다른 사람의 마음 이해하기」에서 3번 문장이 하는 일은 무엇인가요?","options":[{"t":"그렇게 생각한 이유를 쓴다","correct":true},{"t":"문제 상황을 자세히 쓴다","mis":"K3-2-u6-X21"},{"t":"자신의 의견을 제시한다","mis":"K3-2-u6-X21"}],"explanation":["3번 문장은 「왜냐하면」으로 시작해요.","「…… 때문이다」로 끝나요.","그래서 그렇게 생각한 이유를 쓴 문장이에요."],"asset":{"type":"passage","lines":["(간추림) 국어 시간에 드라마를 보았다. 신비는 친구들이 마음을 몰라주어 서운해했다.","1 신비가 경험한 것처럼 우리 주변에도 상대의 마음을 모른 채","  오해해 상대와 갈등을 겪는 일이 많다.","2 다른 사람의 마음을 잘 이해하기 위해서는 그 사람의 처지에서","  생각해 보는 연습이 필요하다고 생각한다.","3 왜냐하면 같은 일을 겪어도 사람마다 느끼는 마음이나 생각이 다를 수 있기 때문이다.","(간추림) 상대의 마음도 헤아려 주면 갈등이 줄어든다. 다투기 전에 상대의 처지를 생각해 보자."],"numbered":false,"title":"「다른 사람의 마음 이해하기」 — 『국어』 268쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_d#13','kor',3,2,'u6','','tb_g3_2_kor_u6_review_d','unit_review','K3-2-u6-C22',2,'mc','auto','「교실에서 고운 말을 쓰자.」는 의견을 뒷받침하는 적절한 이유는 무엇인가요?',ARRAY['K3-2-u6-X23','K3-2-u6-X25','K3-2-u6-X22']::text[],false,'{"seq":13,"concept":"K3-2-u6-C22","difficulty":2,"kind":"mc","stem":"「교실에서 고운 말을 쓰자.」는 의견을 뒷받침하는 적절한 이유는 무엇인가요?","options":[{"t":"고운 말을 쓰면 서로 기분이 상하지 않아 다툼이 줄어들기 때문","correct":true},{"t":"내가 우리 반에서 고운 말을 가장 잘 쓰기 때문","mis":"K3-2-u6-X23"},{"t":"고운 말은 고운 말이기 때문","mis":"K3-2-u6-X25"},{"t":"우리 교실은 3층에 있기 때문","mis":"K3-2-u6-X22"}],"explanation":["이유는 의견대로 하면 무엇이 좋아지는지 말해요.","나만 잘한다는 것, 같은 말 되풀이는 이유가 아니에요.","의견과 상관없는 것도 이유가 되지 못해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_d#14','kor',3,2,'u6','','tb_g3_2_kor_u6_review_d','unit_review','K3-2-u6-C34',2,'mc','auto','『국어활동』 86~87쪽 글을 고쳐 쓸 때 가장 먼저 할 일은 무엇인가요?',ARRAY['K3-2-u6-X28','K3-2-u6-X44','K3-2-u6-X27']::text[],false,'{"seq":14,"concept":"K3-2-u6-C34","difficulty":2,"kind":"mc","stem":"『국어활동』 86~87쪽 글을 고쳐 쓸 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"이유 ㉰를 의견을 뒷받침하는 이유로 바꾼다","correct":true},{"t":"이유 ㉰를 지우기만 한다","mis":"K3-2-u6-X28"},{"t":"의견을 「스마트 기기를 더 오래 쓰자」로 바꾼다","mis":"K3-2-u6-X44"},{"t":"글씨를 더 크게 쓴다","mis":"K3-2-u6-X27"}],"explanation":["문제 상황과 의견은 잘 어울려요.","이어지지 않는 이유 ㉰가 고칠 곳이에요.","지우기만 하지 않고 받쳐 주는 이유로 바꾸어요."],"asset":{"type":"passage","lines":["문제 상황 — 스마트 기기를 지나치게 오래 사용하는 학생이 많다.","의견 — 스마트 기기 사용 시간을 알맞게 정해 스스로 지키자.","이유 ㉮ 스마트 기기를 너무 오래 사용하면 시력이 나빠지기 때문입니다.","이유 ㉯ 스마트 기기에 빠져 숙제나 독서처럼 꼭 해야 하는 일들을 못 할 수도 있기 때문입니다.","이유 ㉰ 스마트 기기는 우리에게 도움을 주기 때문입니다."],"numbered":false,"title":"『국어활동』 87쪽 예시 답안에 실린 문제 상황·의견·이유"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_d#15','kor',3,2,'u6','','tb_g3_2_kor_u6_review_d','unit_review','K3-2-u6-C37',2,'ox','auto','한 줄 평에는 별이 몇 개인지만 쓰면 충분해요.',ARRAY['K3-2-u6-X37']::text[],false,'{"seq":15,"concept":"K3-2-u6-C37","difficulty":2,"kind":"ox","stem":"한 줄 평에는 별이 몇 개인지만 쓰면 충분해요.","answer":"X","reason_options":[{"t":"느낀 곳과 마음이 담겨야 친구가 공감하고 붙임딱지를 붙여 줄 수 있기 때문에","correct":true},{"t":"한 줄 평은 작품에 점수를 매기는 것이기 때문에","mis":"K3-2-u6-X37"}],"mis":"K3-2-u6-X37","explanation":["한 줄 평은 감상한 작품의 재미나 감동을 나누는 것이에요.","점수만으로는 무엇을 느꼈는지 알 수 없어요.","그래서 X예요."],"asset":{"type":"passage","lines":["① 자신이 재미나 감동을 느끼며 감상한 작품의 포스터를 꾸민다.","② 제목과 한 줄 평을 남긴다.","③ 사물함 문이나 알림판에 붙여서 공유한다.","④ 그 작품을 본 사람은 한 줄 평에 공감할 경우 모양 붙임딱지를 붙여 준다.","한 줄 평 예: 나도 미운 오리 새끼처럼 백조가 될 날이 오면 좋겠다."],"numbered":false,"title":"우리 반 추천 (만화) 영화 한 줄 평 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_d#16','kor',3,2,'u6','','tb_g3_2_kor_u6_review_d','unit_review','K3-2-u6-C30',2,'mc','auto','「쓰레기를 쓰레기통에 버리지 않아서 교실이 더러워진다.」는 문제에 대해 「쓰레기를 버리지 말자.」보다 더 나은 의견은 무엇인가요?',ARRAY['K3-2-u6-X43','K3-2-u6-X32','K3-2-u6-X31']::text[],false,'{"seq":16,"concept":"K3-2-u6-C30","difficulty":2,"kind":"mc","stem":"「쓰레기를 쓰레기통에 버리지 않아서 교실이 더러워진다.」는 문제에 대해 「쓰레기를 버리지 말자.」보다 더 나은 의견은 무엇인가요?","options":[{"t":"쓰레기통을 친구들이 자주 지나다니는 곳으로 옮기자","correct":true},{"t":"쓰레기를 아무 데나 버리지 말자","mis":"K3-2-u6-X43"},{"t":"쓰레기를 버린 친구의 이름을 적자","mis":"K3-2-u6-X32"},{"t":"쓰레기는 어쩔 수 없이 생기니 그냥 두자","mis":"K3-2-u6-X31"}],"explanation":["「……하지 말자」만으로는 문제가 잘 풀리지 않아요.","문제를 근본적으로 해결할 방법을 의견으로 내요.","쓰레기통 자리를 옮기면 버리기 쉬워져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_d#17','kor',3,2,'u6','','tb_g3_2_kor_u6_review_d','unit_review','K3-2-u6-C34',3,'ox','auto','고쳐 쓸 부분이 있는지 확인하고 알맞게 고쳐 쓰는 것은 의견을 제시하는 글을 쓸 때 주의할 점이에요.',ARRAY['K3-2-u6-X45']::text[],false,'{"seq":17,"concept":"K3-2-u6-C34","difficulty":3,"kind":"ox","stem":"고쳐 쓸 부분이 있는지 확인하고 알맞게 고쳐 쓰는 것은 의견을 제시하는 글을 쓸 때 주의할 점이에요.","answer":"O","reason_options":[{"t":"고쳐 쓰면 내 의견이 더 잘 전해지고 문제를 해결하는 데 알맞은지 다시 볼 수 있기 때문에","correct":true},{"t":"처음 쓴 글을 고치면 내 생각이 흐려지기 때문에","mis":"K3-2-u6-X45"}],"mis":"K3-2-u6-X45","explanation":["『국어』 283쪽에서 색칠하는 칸이에요.","고쳐 쓰기는 글을 더 좋게 만드는 과정이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉮ 주제나 문제 상황에 어울리는 의견을 쓴다.","㉯ 의견을 뒷받침하는 적절한 이유를 쓴다.","㉰ 같은 이유를 여러 번 제시한다.","㉱ 고쳐 쓸 부분이 있는지 확인하고 알맞게 고쳐 쓴다."],"numbered":false,"title":"스스로 확인하기 — 『국어』 283쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_d#18','kor',3,2,'u6','','tb_g3_2_kor_u6_review_d','unit_review','K3-2-u6-C2',3,'ox','auto','작품을 즐겨 감상하는 태도란 재미나 감동을 느끼며 즐겁게 작품을 보는 것이에요.',ARRAY['K3-2-u6-X01']::text[],false,'{"seq":18,"concept":"K3-2-u6-C2","difficulty":3,"kind":"ox","stem":"작품을 즐겨 감상하는 태도란 재미나 감동을 느끼며 즐겁게 작품을 보는 것이에요.","answer":"O","reason_options":[{"t":"이 단원은 재미나 감동을 느끼며 작품을 즐겨 감상하는 것을 배우기 때문에","correct":true},{"t":"작품을 많이 보고 줄거리를 많이 외우는 것이 즐겨 감상하는 것이기 때문에","mis":"K3-2-u6-X01"}],"mis":"K3-2-u6-X01","explanation":["감상은 줄거리를 외우는 일이 아니에요.","재미나 감동을 느끼며 즐겁게 보는 것이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["1 자신이 인상 깊게 본 드라마나 만화 영화의 제목을 써 봅시다.","2 재미나 감동을 느낀 부분을 골라 글로 쓰고 장면을 그림으로 나타내 봅시다.","3 드라마나 만화 영화를 즐겁게 감상했나요?  ○○○","  재미나 감동을 느끼며 감상했나요?  ○○○","  재미나 감동을 느낀 부분이 드러나도록 잘 표현했나요?  ○○○"],"numbered":false,"title":"작품을 감상하고 느낀 재미나 감동 표현하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_d#19','kor',3,2,'u6','','tb_g3_2_kor_u6_review_d','unit_review','K3-2-u6-C34',3,'mc','auto','친구가 「이미 다 썼으니 이제 고치면 안 돼.」라고 했어요. 친구에게 해 줄 말로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X45','K3-2-u6-X29','K3-2-u6-X27']::text[],false,'{"seq":19,"concept":"K3-2-u6-C34","difficulty":3,"kind":"mc","stem":"친구가 「이미 다 썼으니 이제 고치면 안 돼.」라고 했어요. 친구에게 해 줄 말로 알맞은 것은 무엇인가요?","options":[{"t":"“점검한 내용을 바탕으로 이유를 더하거나 어색한 문장을 빼도 괜찮아.”","correct":true},{"t":"“맞아, 다 쓴 글은 고치지 않아.”","mis":"K3-2-u6-X45"},{"t":"“고칠 곳이 있으면 못 쓴 글이니 버리자.”","mis":"K3-2-u6-X29"},{"t":"“글씨만 다시 예쁘게 쓰면 돼.”","mis":"K3-2-u6-X27"}],"explanation":["고쳐 쓰는 과정에서 이유를 추가해도 좋아요.","이미 쓴 내용을 삭제해도 괜찮아요.","글의 흐름이 잘 이어지게 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_d#20','kor',3,2,'u6','','tb_g3_2_kor_u6_review_d','unit_review','K3-2-u6-C24',3,'mc','auto','학급에서 나온 여러 의견 가운데 하나를 골라 실천하려고 해요. 고르는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X24','K3-2-u6-X27','K3-2-u6-X43']::text[],false,'{"seq":20,"concept":"K3-2-u6-C24","difficulty":3,"kind":"mc","stem":"학급에서 나온 여러 의견 가운데 하나를 골라 실천하려고 해요. 고르는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"문제를 잘 해결하고, 이유가 적절하고, 실천할 수 있는 의견을 고른다","correct":true},{"t":"친구가 가장 많은 사람의 의견을 고른다","mis":"K3-2-u6-X24"},{"t":"가장 길게 쓴 의견을 고른다","mis":"K3-2-u6-X27"},{"t":"「하지 말자」는 말이 가장 분명한 의견을 고른다","mis":"K3-2-u6-X43"}],"explanation":["문제 상황을 잘 해결할 수 있는지 보아요.","적절한 이유로 뒷받침했는지 보아요.","실천할 수 있는지도 보고 고른 뒤 실천 결과를 나누어요."],"asset":{"type":"passage","lines":["● 문제 상황을 잘 해결할 수 있는가?","● 적절한 이유를 들어 의견을 뒷받침했는가?","● 실천 가능한가?"],"title":"문제 상황을 해결하는 데 가장 효과적인 의견 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_d#21','kor',3,2,'u6','','tb_g3_2_kor_u6_review_d','unit_review','K3-2-u6-C18',3,'mc','auto','드라마 속 인물과 비슷한 경험을 친구들과 나눈 뒤 새롭게 알 수 있는 점으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X16','K3-2-u6-X18','K3-2-u6-X01']::text[],false,'{"seq":21,"concept":"K3-2-u6-C18","difficulty":3,"kind":"mc","stem":"드라마 속 인물과 비슷한 경험을 친구들과 나눈 뒤 새롭게 알 수 있는 점으로 알맞은 것은 무엇인가요?","options":[{"t":"인물처럼 비슷한 상황을 겪으면 어떻게 대처하면 좋을지 알게 된다","correct":true},{"t":"누가 잘못했는지만 가리면 된다는 것을 알게 된다","mis":"K3-2-u6-X16"},{"t":"서운해도 말하지 않는 것이 낫다는 것을 알게 된다","mis":"K3-2-u6-X18"},{"t":"드라마 줄거리를 다 외우게 된다","mis":"K3-2-u6-X01"}],"explanation":["드라마 속 인물들이 중요하게 여기는 가치를 확인해요.","내 일상에서 비슷한 일을 떠올려요.","중요하게 여겨야 할 가치를 서로 나누어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"동생과 싸웠을 때 엄마가 나를 더 혼내셔서 속상했는데, 그날 밤에 침대로 와서 안아 주셔서 오해가 풀렸어."},{"who":"친구 2","text":"두 친구가 나에게 안 들리게 귓속말을 해서 속상했는데, 알고 보니 내 생일 선물을 준비하는 것이어서 오히려 미안했어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_d#22','kor',3,2,'u6','','tb_g3_2_kor_u6_review_d','unit_review','K3-2-u6-C28',3,'ox','auto','고쳐 쓰기 전과 후를 비교해 보면 잘한 점을 찾아 칭찬할 수 있어요.',ARRAY['K3-2-u6-X29']::text[],false,'{"seq":22,"concept":"K3-2-u6-C28","difficulty":3,"kind":"ox","stem":"고쳐 쓰기 전과 후를 비교해 보면 잘한 점을 찾아 칭찬할 수 있어요.","answer":"O","reason_options":[{"t":"고친 글에서 의견이 더 잘 드러난 점을 찾으면 서로에게 힘이 되기 때문에","correct":true},{"t":"고친 글은 처음 글이 못 쓴 글이었다는 뜻이기 때문에","mis":"K3-2-u6-X29"}],"mis":"K3-2-u6-X29","explanation":["『국어』 279쪽 더 나아가기 활동이에요.","고쳐 쓰기 전과 후를 비교해 잘한 점을 찾아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_d#23','kor',3,2,'u6','','tb_g3_2_kor_u6_review_d','unit_review','K3-2-u6-C14',4,'essay','teacher','「신통방통 니 맘 내 맘 계산기」의 인물 한 명을 골라, 그 인물이 소중하게 여기는 것을 말과 행동을 근거로 쓰고 그 인물에 대한 자신의 생각을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-2-u6-C14","difficulty":4,"kind":"essay","stem":"「신통방통 니 맘 내 맘 계산기」의 인물 한 명을 골라, 그 인물이 소중하게 여기는 것을 말과 행동을 근거로 쓰고 그 인물에 대한 자신의 생각을 쓰세요.","answer_guide":{"answer":"예: 인물 — 아빠. 「아빠는 신비가 먹는 것만 봐도 배가 불러요.」라며 맛있는 것을 신비에게 먼저 주는 것으로 보아 딸인 신비와 가족을 가장 소중하게 여긴다. 항상 신비를 먼저 생각하는 모습에서 가족에 대한 사랑을 느꼈고, 나도 우리 가족에게 고마운 마음을 표현해야겠다고 생각했다.","scoring_points":["인물을 골랐는가","말과 행동을 근거로 소중하게 여기는 것을 썼는가","인물에 대한 자신의 생각을 썼는가"]},"explanation":["인물이 처한 상황과 말, 행동을 보아요.","소중하게 여기는 것은 거기서 읽어 내요.","인물에 대한 생각은 사람마다 달라도 괜찮아요."],"asset":{"type":"speech","turns":[{"who":"신비","text":"뭐야? 별로 안 고마운 거야?"},{"who":"기동","text":"인심 썼다. 자! 먼저 먹어."},{"who":"아빠","text":"아빠는 신비가 먹는 것만 봐도 배가 불러요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_d#24','kor',3,2,'u6','','tb_g3_2_kor_u6_review_d','unit_review','K3-2-u6-C24',4,'essay','teacher','「학교 화단 공간을 줄이고, 놀이 공간을 만들어야 하는가?」에 대해 찬성하는 의견과 반대하는 의견을 각각 이유 하나와 함께 쓰고, 의견이 서로 다를 때 무엇을 보고 견주어야 하는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u6-C24","difficulty":4,"kind":"essay","stem":"「학교 화단 공간을 줄이고, 놀이 공간을 만들어야 하는가?」에 대해 찬성하는 의견과 반대하는 의견을 각각 이유 하나와 함께 쓰고, 의견이 서로 다를 때 무엇을 보고 견주어야 하는지 쓰세요.","answer_guide":{"answer":"예: 찬성 — 놀 곳이 넓어지면 복도에서 뛰는 친구가 줄어 안전해지기 때문이다. 반대 — 화단의 식물을 관찰하며 배우는 것이 많고 학교가 푸르러지기 때문이다. 의견이 다를 때에는 어느 쪽 의견인지가 아니라 이유가 의견을 잘 뒷받침하는지, 문제 해결에 도움이 되는지를 보고 견주어야 한다.","scoring_points":["찬성하는 의견과 이유를 썼는가","반대하는 의견과 이유를 썼는가","이유가 의견을 뒷받침하는지로 견주어야 한다고 썼는가"]},"explanation":["한 문제에도 의견은 여러 가지예요.","의견마다 받쳐 주는 이유가 있어요.","정답 의견을 찾는 것이 아니라 이유로 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u6_review_d#25','kor',3,2,'u6','','tb_g3_2_kor_u6_review_d','unit_review','K3-2-u6-C1',4,'mc','auto','『국어』 283쪽 「생활 속으로」에서 세 친구가 실천을 다짐했어요. 소단원 2(의견을 제시하는 글 쓰기)에서 배운 것을 실천하겠다고 한 친구를 모두 고른 것은 무엇인가요?',ARRAY['K3-2-u6-X47']::text[],false,'{"seq":25,"concept":"K3-2-u6-C1","difficulty":4,"kind":"mc","stem":"『국어』 283쪽 「생활 속으로」에서 세 친구가 실천을 다짐했어요. 소단원 2(의견을 제시하는 글 쓰기)에서 배운 것을 실천하겠다고 한 친구를 모두 고른 것은 무엇인가요?","options":[{"t":"친구 2, 친구 3","correct":true},{"t":"친구 1","mis":"K3-2-u6-X47"},{"t":"친구 1, 친구 2","mis":"K3-2-u6-X47"},{"t":"친구 1, 친구 2, 친구 3","mis":"K3-2-u6-X47"}],"explanation":["친구 1은 영화를 감상할 때의 다짐이에요(소단원 1).","친구 2는 이유를 들어 의견을 말하겠다고 했어요.","친구 3은 의견 글을 쓰고 스스로 확인해 고쳐 쓰겠다고 했어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"영화를 볼 때 인물의 표정이나 행동을 살피면서 재미나 감동을 느끼도록 감상할 거야."},{"who":"친구 2","text":"내 의견을 발표할 때 이유를 들어서 말할 거야."},{"who":"친구 3","text":"의견을 제시하는 글을 쓴 뒤 스스로 확인하고 고쳐 써 볼 거야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
